window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0104", [{"word":"slope","ipa_uk":"/sləʊp/","ipa_us":"/sloʊp/","definition_zh":"斜坡；坡度；斜率；倾斜；趋势；溜走","definition_en":"a surface that rises or falls at an angle, or to rise or fall at an angle","core_image":"一片地面从高处向低处缓缓下探，像被轻轻压斜的一块木板","scene":"屋后的花园顺着河岸缓缓下探。The garden lies on a gentle slope above the river.","sceneCN":"这里该词指「倾斜的地面」（第 1 个义项：从高处向低处倾斜的地表）；句意为花园位于河岸上方的一段缓坡上。","pos":[{"tag":"n.","zh":"斜坡；坡度；斜率；趋势"},{"tag":"vi.","zh":"倾斜；有坡度；悄悄溜走"},{"tag":"vt.","zh":"使倾斜；斜放"}],"collocations":[{"phrase":"a steep slope","zh":"陡坡"},{"phrase":"a gentle slope","zh":"缓坡"},{"phrase":"slope down","zh":"向下倾斜"},{"phrase":"the slope of the roof","zh":"屋顶的坡度"},{"phrase":"an upward slope","zh":"上升趋势"},{"phrase":"a ski slope","zh":"滑雪坡道"}],"forms":[{"label":"复数（名词）","form":"slopes"},{"label":"三单（动词）","form":"slopes"},{"label":"过去式","form":"sloped"},{"label":"过去分词","form":"sloped"},{"label":"现在分词","form":"sloping"}],"derivatives":[{"word":"sloping","pos":"adj.","zh":"倾斜的；有坡度的"},{"word":"sloped","pos":"adj.","zh":"成斜坡状的"},{"word":"upslope","pos":"n./adv.","zh":"上坡；向坡上"},{"word":"downslope","pos":"n./adv.","zh":"下坡；向坡下"},{"word":"slope off","pos":"phr.","zh":"溜走；悄悄离开"}],"senses":[{"no":"01","title":"Slanting ground","titleCN":"斜坡：从高处向低处倾斜的地面","definition":"a surface of ground that rises or falls at an angle","definitionCN":"呈一定角度上升或下降的地面","example":"The path follows a gentle slope down to the lake.","exampleCN":"小路沿一段缓坡向下延伸到湖边。","why":"Middle English slopen meant 'to slant or lean', and the noun first named ground that leans away from the level.","whyCN":"中古英语动词意为「倾斜、倚靠」，名词最初就指离开水平面的地面。"},{"no":"02","title":"Degree of slant","titleCN":"坡度：地面倾斜的程度","definition":"the angle at which a surface rises or falls, often given as a proportion","definitionCN":"地表上升或下降的角度，常以比例表示","example":"The slope of the roof is thirty degrees.","exampleCN":"屋顶的坡度是三十度。","why":"Once the surface had a name, the amount of its drop could take the same name.","whyCN":"地面有了名称之后，它下降的量也可以用同一个词表示。"},{"no":"03","title":"Slope of a line or curve","titleCN":"数学：直线或曲线的斜率","definition":"in mathematics, the ratio of vertical change to horizontal change along a line","definitionCN":"数学中直线上竖直变化与水平变化之比","example":"A line with a negative slope falls from left to right.","exampleCN":"斜率为负的直线从左向右下降。","why":"A graph line rises and falls like a hillside, so mathematics borrowed the everyday word for its rise-over-run ratio.","whyCN":"图上的线像山坡一样升降，数学便借用了这个日常词来表示升降比。"},{"no":"04","title":"To rise or fall at an angle","titleCN":"倾斜：呈角度上升或下降","definition":"to be set at an angle rather than level","definitionCN":"呈一定角度而非水平","example":"The field slopes toward the stream.","exampleCN":"这块地向小溪方向倾斜。","why":"The noun turned into a verb without any ending, a common English pattern.","whyCN":"名词不加词尾直接转作动词，这是英语常见的用法。"},{"no":"05","title":"To tilt something","titleCN":"使某物倾斜","definition":"to hold or place something at an angle","definitionCN":"使某物呈一定角度放置或持有","example":"He sloped the plank against the wall.","exampleCN":"他把木板斜靠在墙上。","why":"The causative use adds an object to the same leaning image.","whyCN":"使役用法只是给同一个「倾斜」意象加上宾语。"},{"no":"06","title":"A trend in figures","titleCN":"趋势：数字或局面的走势","definition":"the direction in which a quantity or situation is moving","definitionCN":"数量或形势发展的方向","example":"The graph shows an upward slope in demand.","exampleCN":"图表显示需求呈上升趋势。","why":"A rising line on a chart looks exactly like a hillside, so the word moved from land to trends.","whyCN":"图表上上扬的线正像山坡，这个词便从土地移到趋势上。"},{"no":"07","title":"To leave quietly","titleCN":"溜走：悄悄离开","definition":"to leave a place quietly and without being noticed, usually in a fixed phrase","definitionCN":"悄悄离开某处而不被注意，通常用于固定短语","example":"He sloped off before the meeting ended.","exampleCN":"会议结束前他悄悄溜走了。","why":"The old root sense 'to slip or glide' survived in the phrase for a quiet exit.","whyCN":"词根古老的「滑走」义在表示悄悄离开的短语中保留下来。"},{"no":"08","title":"A prepared hillside for skiing","titleCN":"滑雪坡：供滑雪使用的坡道","definition":"a hillside prepared and marked for skiing","definitionCN":"经过整理并标记、供滑雪使用的山坡","example":"The resort groomed the slope before the first skiers arrived.","exampleCN":"度假村在第一批滑雪者到来前整理好了雪道。","why":"This is the physical sense narrowed to one use: a hillside kept ready for a sport.","whyCN":"这是本义收窄到单一用途：为一项运动准备好山坡。"}],"etymology":{"intro":{"en":"Slope entered English in the late Middle Ages as a verb meaning 'to slant', and its deeper source is not certain. Dates are approximate.","cn":"该词在中世纪末进入英语，最初是表示「倾斜」的动词，更深来源并不确定。年代均为约数。"},"items":[{"era":"MIDDLE ENGLISH","en":"slopen 'to slant, lean' is recorded from the late fourteenth century, first as a verb and soon after as a noun for slanting ground.","cn":"表示「倾斜、倚靠」的中古英语动词在十四世纪晚期有记录，先是动词，随后出现指倾斜地面的名词。"},{"era":"PROBABLE OLD ENGLISH","en":"The verb probably comes from an unrecorded Old English form meaning 'to slip, glide'; this form is a reconstruction, not a attested word.","cn":"这个动词可能出自一个未见于现存文献的古英语形式，意为「滑走、滑动」；该形式属重构，并非有书证的实际词形。"},{"era":"GERMANIC COMPARISONS","en":"Middle Low German and modern German have related verbs for slipping or sliding, which support a Germanic origin.","cn":"中古低地德语与现代德语都有表示滑动的相关动词，这支持日耳曼语来源的判断。"},{"era":"NOUN SENSE","en":"By about 1500 the noun named a piece of slanting ground, and the sense spread to roofs, roads and charts.","cn":"到十六世纪前后，名词已指一段倾斜的地面，随后扩展到屋顶、道路与图表。"},{"era":"MATHEMATICS","en":"Nineteenth-century mathematics fixed slope as rise over run, the vertical change divided by the horizontal change.","cn":"十九世纪数学把坡度固定为竖直变化除以水平变化的比值。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the Old English form is reconstructed, no single Indo-European root is agreed, and the first dates are approximate.","cn":"来源不确定（更深词源）：古英语形式属重构，学界未就单一印欧词根达成一致，首见年代亦为约数。"}]},"similar":{"note":{"en":"Group one holds short words that look or sound close to slope; group two holds the verbs and nouns that also describe a slanted surface.","cn":"第一组是字形或读音接近该词的短词；第二组是同义描述倾斜地面的动词与名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"slop","ipa":"/slɒp/","tag":"spilled liquid","definition":"Wet waste or a small spill; as a verb it means to spill or splash, with no idea of an angle.","definitionCN":"指湿垃圾或少量泼洒物；作动词表示泼出、溅出，与角度无关。"},{"word":"slip","ipa":"/slɪp/","tag":"slide by accident","definition":"To slide unintentionally on a surface; it shares the Germanic stock but names a sudden loss of footing, not a surface.","definitionCN":"指在表面上意外滑倒；与该词同属日耳曼语源，但表示突然失去立足点，而非地表。"},{"word":"slouch","ipa":"/slaʊtʃ/","tag":"sit or stand lazily","definition":"To sit or stand with the body bent forward; the spelling is close, the meaning is about posture, not ground.","definitionCN":"指身体前倾地懒散坐立；拼写接近，但意义关乎姿态，与地面无关。"},{"word":"sloop","ipa":"/sluːp/","tag":"a sailing boat","definition":"A small sailing boat with one mast; it is a nautical term with a different history.","definitionCN":"指只有一根桅杆的小型帆船；这是来历不同的航海术语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"incline","ipa":"/ɪnˈklaɪn/","tag":"lean toward","definition":"To lean or slope, often with a sense of direction or willingness; it stresses the act of leaning rather than the ground itself.","definitionCN":"指倾斜或倾向，常带方向或意愿之意；强调倾斜的动作，而非地面本身。"},{"word":"gradient","ipa":"/ˈɡreɪdiənt/","tag":"measured steepness","definition":"The measured degree of a slope, especially in roads and science; it is the quantity, not the surface.","definitionCN":"指被测量出的坡度，尤用于道路与科学；它是数量，而非地面。"},{"word":"slant","ipa":"/slɑːnt/","tag":"set at an angle","definition":"To lie or place at an angle, or such an angle; it is close in meaning but often more general and less technical.","definitionCN":"指以某个角度放置或倾斜，或指该角度；意义接近，但更宽泛、较少技术色彩。"},{"word":"tilt","ipa":"/tɪlt/","tag":"tip to one side","definition":"To lean or tip to one side, often unintentionally; slope describes a surface, tilt describes an object's position.","definitionCN":"指向一侧翘起，常含意外之意；本词描述地面，对比词描述物体姿态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The earliest recorded verb meant 'to slant or lean', and the ground sense came straight from that lean.","cn":"最早有记录的动词意为「倾斜、倚靠」，地面义直接由这个动作而来。"},{"en":"The family runs slope, sloping, sloped, upslope and downslope.","cn":"同族词包括本词、其现在分词与过去分词，以及上坡与下坡两个复合词。"},{"en":"Fixed phrases mark the senses: a steep slope, a gentle slope, slope down, a ski slope.","cn":"固定搭配标出各义项：陡坡、缓坡、向下倾斜、滑雪坡。"},{"en":"Mathematics reads slope as rise over run, which is the same shape as a hillside.","cn":"数学把斜率读作升降比，这与山坡的形状是同一回事。"},{"en":"The quiet-exit phrase keeps the old 'slip away' sense of the Germanic root.","cn":"表示悄悄离开的短语保留了日耳曼词根「滑走」的旧义。"}],"abstract":[{"en":"Picture a sheet of paper lifted at one corner while the other three stay on the desk.","cn":"想象一张纸被抬起一角，另外三角仍贴在桌面。"},{"en":"Picture a chart line climbing like a footpath up a hill.","cn":"想象图表上的一条线像山间小路一样向上爬。"},{"en":"Picture a conversation quietly sliding away from its first topic.","cn":"想象一场谈话悄悄从最初的话题上滑开。"}]},"examples":[{"en":"The village sits on a slope that faces the morning sun.","cn":"村庄坐落在朝东的缓坡上。"},{"en":"House prices show an upward slope after the new road opens.","cn":"新路开通后房价呈上升趋势。"},{"en":"She sloped off before anyone could ask her a second question.","cn":"还没人来得及问她第二个问题，她就悄悄溜走了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「死漏坡」：水一路漏下去，因为地在往低处斜。","word":"slope"},"root":"中古英语动词意为「倾斜、倚靠」，可能出自古英语中表示「滑走」的未记录动词，属日耳曼语重构形式，更深词源不确定。英语 slope。","sensesIntro":{"en":"Eight senses follow one shape: a surface that leans away from the level. The shape is then measured, drawn on a chart, turned into a verb, read as a trend, used for a prepared hillside, and finally kept in the old sense of slipping away.","cn":"八个义项沿同一个形状展开：离开水平面的地表。这个形状随后被测量、画到图表上、转为动词、读作趋势、用于整理好的山坡，最后保留在「滑走」的旧义中。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flat surface lifted at one edge so that everything on it would roll downward.","cn":"核心意象：一块平板被抬起一边，上面的东西都会往低处滚。"},"chain":["SLANTING GROUND","DEGREE OF DROP","RISE OVER RUN","LEANING SURFACE","UPWARD TREND","QUIET EXIT"],"branches":[{"senses":"S1 · S8","en":"PHYSICAL GROUND: a hillside and a prepared ski run are the same surface put to different uses.","cn":"实地表面：山坡与整理好的雪道是同一块地面的不同用途。"},{"senses":"S2 · S3","en":"MEASUREMENT: the drop of the surface becomes an angle, then a ratio on a graph.","cn":"测量：地面的下降先变成角度，再变成图上的比值。"},{"senses":"S4 · S5","en":"VERBAL LEAN: the noun turns into an act of leaning, with or without an object.","cn":"动词化：名词转为倾斜的动作，可带宾语也可不带。"},{"senses":"S6","en":"TREND: a rising chart line borrows the shape of a hill.","cn":"趋势：上扬的图表线借用了山坡的形状。"},{"senses":"S7","en":"QUIET EXIT: the oldest 'slip away' sense survives only in a fixed phrase.","cn":"悄悄离开：最古老的「滑走」义只保留在固定短语中。"}]},"affixes":{"intro":{"en":"Slope is an English word of Germanic stock, not a Latin derivative, so its word family is built from English suffixes and compounds.","cn":"该词是日耳曼语来源的英语词，并非拉丁派生词，因此其词族由英语后缀与复合构成。"},"latinIntro":{"en":"There is no Latin element here; the recorded history is Middle English and Germanic, so the Latin entry list is left empty.","cn":"这里没有拉丁成分；有记录的历史属中古英语与日耳曼语，因此拉丁词条列表留空。"},"items":[{"word":"slope","structure":"slope (Middle English noun, 'slanting ground')","meaning":"slanting ground","meaningCN":"倾斜的地面","example":"The slope behind the barn is too steep for a tractor.","exampleCN":"谷仓后的坡太陡，拖拉机上不去。"},{"word":"slope","structure":"slope (denominal verb, 'to slant')","meaning":"to slant","meaningCN":"倾斜","example":"The roof slope must slope toward the drain.","exampleCN":"屋顶必须朝排水口倾斜。"},{"word":"slopes","structure":"slope + -s (plural or third person)","meaning":"more than one slope","meaningCN":"多个斜坡","example":"Two slopes meet at the ridge.","exampleCN":"两道斜坡在山脊处相接。"},{"word":"sloping","structure":"slope + -ing (participle or adjective)","meaning":"slanting","meaningCN":"倾斜的","example":"A sloping bank keeps the soil from washing away.","exampleCN":"倾斜的河岸能防止土壤被冲走。"},{"word":"sloped","structure":"slope + -ed (past participle or adjective)","meaning":"made slanting","meaningCN":"做成斜面的","example":"The sloped ceiling gives the room more height.","exampleCN":"斜顶让房间显得更高。"},{"word":"upslope","structure":"up + slope (compound)","meaning":"toward the top of a slope","meaningCN":"向坡上","example":"Cold air moves upslope during the day.","exampleCN":"白天冷空气沿坡向上移动。"},{"word":"downslope","structure":"down + slope (compound)","meaning":"toward the bottom of a slope","meaningCN":"向坡下","example":"Water gathers downslope of the road.","exampleCN":"水聚集在道路下方的低处。"},{"word":"slope off","structure":"slope + off (phrasal verb)","meaning":"to leave quietly","meaningCN":"悄悄离开","example":"He tried to slope off after the speech.","exampleCN":"演讲结束后他想悄悄溜走。"}],"latinEntries":[]}},{"word":"gradient","ipa_uk":"/ˈɡreɪdiənt/","ipa_us":"/ˈɡreɪdiənt/","definition_zh":"坡度；梯度；渐变；变化率；逐渐变化的","definition_en":"the degree to which a road or surface slopes, or the rate at which a quantity changes from place to place","core_image":"一条从浅到深逐渐变色的带子，左端几乎看不出变化，右端已彻底改变","scene":"山路陡峭地向上抬升。The mountain road climbs a steep gradient.","sceneCN":"这里该词指「道路的坡度」（第 1 个义项：路面上升的陡缓程度）；句意为这条山路以很陡的坡度向上爬升。","pos":[{"tag":"n.","zh":"坡度；梯度；渐变；变化率"},{"tag":"adj.","zh":"逐渐变化的；渐变的"}],"collocations":[{"phrase":"a steep gradient","zh":"陡峭的坡度"},{"phrase":"a gentle gradient","zh":"平缓的坡度"},{"phrase":"temperature gradient","zh":"温度梯度"},{"phrase":"pressure gradient","zh":"气压梯度"},{"phrase":"a colour gradient","zh":"色彩渐变"},{"phrase":"social gradient","zh":"社会梯度"},{"phrase":"the gradient of a curve","zh":"曲线的斜率"}],"forms":[{"label":"复数（名词）","form":"gradients"},{"label":"形容词（渐变的）","form":"gradational"},{"label":"名词（渐变过程）","form":"gradation"}],"derivatives":[{"word":"gradation","pos":"n.","zh":"渐变；层次"},{"word":"gradual","pos":"adj.","zh":"逐渐的；渐进的"},{"word":"gradually","pos":"adv.","zh":"逐渐地"},{"word":"gradational","pos":"adj.","zh":"渐变的；分级的"},{"word":"isograd","pos":"n.","zh":"等梯度线"}],"senses":[{"no":"01","title":"Steepness of a road or surface","titleCN":"道路或地面的坡度","definition":"the degree to which a road, railway or surface rises or falls","definitionCN":"道路、铁路或地面上升或下降的程度","example":"The mountain road climbs a steep gradient.","exampleCN":"这条山路以很陡的坡度向上爬升。","why":"The word was coined from a Latin participle meaning 'walking', so it first named the way a road walks up a hill.","whyCN":"这个词由意为「行走」的拉丁分词造成，最初指道路「走」上坡的方式。"},{"no":"02","title":"A gradual change of colour","titleCN":"颜色的渐变","definition":"a smooth transition from one colour or tone to another","definitionCN":"从一种颜色或色调平滑过渡到另一种","example":"The poster uses a gradient from deep blue to pale gold.","exampleCN":"海报用了从深蓝到浅金的渐变。","why":"Design borrowed the word because a colour transition is a slope in colour space: small steps, each a little different.","whyCN":"设计借用了这个词，因为颜色过渡就是色彩空间里的坡：每一小步都略有不同。"},{"no":"03","title":"Slope of a curve in mathematics","titleCN":"数学中曲线切线的斜率","definition":"the slope of a curve at a point, given by the tangent line","definitionCN":"曲线在某一点的斜率，由切线给出","example":"At the top of the arc the gradient is zero.","exampleCN":"在弧线的最高点，斜率为零。","why":"Calculus needed a word for how fast a curve climbs at one point, and the road sense supplied it.","whyCN":"微积分需要一个词描述曲线在某点上升的快慢，道路义正好提供了它。"},{"no":"04","title":"Rate of change in physics","titleCN":"物理中的温度、压力梯度","definition":"the rate at which temperature, pressure or another quantity changes with distance","definitionCN":"温度、压力或其他量随距离变化的速率","example":"A strong temperature gradient drives the wind.","exampleCN":"强烈的温度梯度驱动风。","why":"Science generalized the road slope into any quantity that changes across space.","whyCN":"科学把道路坡度推广为任何随空间变化的量。"},{"no":"05","title":"A social or economic scale","titleCN":"社会或经济梯度","definition":"a scale of difference in health, wealth or status across groups","definitionCN":"不同群体在健康、财富或地位上的差异阶梯","example":"Researchers measured the social gradient in life expectancy.","exampleCN":"研究者测量了预期寿命上的社会梯度。","why":"A scale of difference looks like a slope when plotted, so the word spread from space to society.","whyCN":"差异画出来像一条斜坡，这个词便从空间扩展到社会。"},{"no":"06","title":"Gradual in manner","titleCN":"形容词：逐渐的、渐变的","definition":"changing slowly by small steps rather than suddenly","definitionCN":"以小的步伐缓慢变化，而非突然改变","example":"The gradient change in policy avoided a shock.","exampleCN":"政策上的渐进变化避免了冲击。","why":"The adjective keeps the 'stepping' image: change that moves one step at a time.","whyCN":"形容词保留了「一步步」的意象：一次只走一级的变化。"},{"no":"07","title":"The rise of a railway line","titleCN":"铁路或道路的纵坡","definition":"the measured rise of a track or road over a fixed distance, used by engineers","definitionCN":"轨道或道路在固定距离内的上升量，供工程使用","example":"The line was built with a gentle gradient to save fuel.","exampleCN":"这条铁路以平缓的纵坡修建，以节省燃料。","why":"Railways made the word technical: a train's power depends on how many metres it must climb per kilometre.","whyCN":"铁路让它成为技术词：火车需要多少动力，取决于每公里要爬多少米。"},{"no":"08","title":"Pitch change in speech","titleCN":"语音中的音高渐变","definition":"a continuous change of pitch or loudness in speech","definitionCN":"说话时音高或音量的连续变化","example":"The speaker's voice showed a falling gradient at the end.","exampleCN":"说话者句尾的声音呈下降的音高渐变。","why":"Phonetics borrowed the same spatial word for sound that slides from one level to another.","whyCN":"语音学借用了同一个空间词，用来描述从一个高度滑向另一个高度的声音。"}],"etymology":{"intro":{"en":"Gradient comes from Latin gradi 'to walk, step', through the participle gradiens. The mathematical sense was coined in the nineteenth century. Dates are approximate.","cn":"该词出自拉丁语表示「行走、迈步」的动词，经其分词形式进入近代学术语言；数学义在十九世纪被造出。年代均为约数。"},"items":[{"era":"LATIN GRADUS","en":"gradus meant 'step, degree', and it also gives English grade, gradual and graduate.","cn":"拉丁语词意为「台阶、等级」，也衍生出表示等级、逐渐与毕业的英语词。"},{"era":"LATIN GRADI","en":"gradi 'to walk, step' supplied the present participle gradiens, literally 'walking'.","cn":"表示「行走、迈步」的动词给出现在分词形式，字面义为「正在行走的」。"},{"era":"NINETEENTH-CENTURY SCIENCE","en":"Calculus and physics coined gradient for the rate of change of a quantity in space, first for curves and then for temperature and pressure.","cn":"微积分与物理学造出本词表示量在空间中的变化率，先用于曲线，后用于温度与压力。"},{"era":"ENGINEERING","en":"Railway and road engineering adopted it for the rise of a track over distance.","cn":"铁路与道路工程采用它表示轨道在距离上的上升量。"},{"era":"EXTENDED USES","en":"Twentieth-century design extended it to colour transitions, and social science to scales of health and status.","cn":"二十世纪的设计把它扩展到颜色过渡，社会科学则扩展到健康与地位阶梯。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest citations for the colour and social senses are not precisely fixed, and dates are approximate.","cn":"来源不确定（首见年代）：颜色义与社会义的最早书证没有确切记录，年代为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin step-root that are often confused; group two holds the everyday words for a sloping surface.","cn":"第一组是同出拉丁「台阶」词根、容易混淆的词；第二组是描述倾斜地面的日常词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gradation","ipa":"/ɡrəˈdeɪʃn/","tag":"arrangement in steps","definition":"A series of small steps or stages; it names the arrangement, while gradient names the measured rate.","definitionCN":"指一系列小台阶或阶段；它指排列方式，而本词指被测量的变化率。"},{"word":"gradual","ipa":"/ˈɡrædʒuəl/","tag":"happening by steps","definition":"Happening slowly over time; it is an adjective of manner, not a measured quantity.","definitionCN":"指随时间缓慢发生；它是方式形容词，不是被测量的量。"},{"word":"graduate","ipa":"/ˈɡrædʒuət/","tag":"complete a course","definition":"To complete a course of study; the shared root is 'step', but the modern meaning has moved to education.","definitionCN":"指完成学业；同出「台阶」词根，但现代义已转到教育领域。"},{"word":"grade","ipa":"/ɡreɪd/","tag":"rank or level","definition":"A level, rank or mark; it comes from the same step-root but names a position, not a slope.","definitionCN":"指等级、级别或分数；同出「台阶」词根，但指位置，而非坡度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"slope","ipa":"/sləʊp/","tag":"the surface itself","definition":"The slanting ground or its angle; gradient is the measured rate of that slant.","definitionCN":"指倾斜的地面或角度；本词是这种倾斜被测量出的变化率。"},{"word":"incline","ipa":"/ɪnˈklaɪn/","tag":"lean or slope","definition":"To lean or be willing; as a noun it is a sloping surface, while gradient is a number.","definitionCN":"指倾斜或愿意；作名词指斜面，而本词是数值。"},{"word":"ramp","ipa":"/ræmp/","tag":"built slope","definition":"A built slope joining two levels; it names the structure, not its steepness.","definitionCN":"指连接两个高度的建筑坡道；它指结构，而非陡度。"},{"word":"pitch","ipa":"/pɪtʃ/","tag":"degree of tilt","definition":"The angle of a roof or a ship's rise and fall; it is a technical angle, narrower than gradient.","definitionCN":"指屋顶的角度或船只起伏；它是较窄的技术角度词，范围比本词小。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root is Latin gradus 'step', so a gradient is change measured step by step.","cn":"词根是拉丁语「台阶」，所以梯度就是一级一级量出来的变化。"},{"en":"The family runs gradient, gradation, gradual, gradually, gradational.","cn":"同族词包括本词、渐变名词、逐渐形容词、逐渐副词与渐变形容词。"},{"en":"Fixed phrases mark the senses: steep gradient, temperature gradient, colour gradient, social gradient.","cn":"固定搭配标出各义项：陡坡、温度梯度、颜色渐变、社会梯度。"},{"en":"In physics a gradient points toward the fastest increase, like the steepest way up a hill.","cn":"物理中的梯度指向上升最快的方向，就像上山最陡的那条路。"},{"en":"Railway engineers measure a gradient as rise per kilometre.","cn":"铁路工程师把坡度测为每公里的上升量。"}],"abstract":[{"en":"Picture a staircase painted so that each step is a slightly deeper shade of blue.","cn":"想象一段楼梯被涂成蓝色，每上一级颜色就深一点。"},{"en":"Picture a thermometer lying across a map, warm at one end and cold at the other.","cn":"想象一支温度计横放在地图上，一端暖一端冷。"},{"en":"Picture a social ladder whose rungs are health and income rather than wood.","cn":"想象一架社会阶梯，横档不是木头，而是健康与收入。"}]},"examples":[{"en":"The old road has a gradient of one in ten, so carts needed extra horses.","cn":"这条老路的坡度是十分之一，所以马车要多套几匹马。"},{"en":"A strong pressure gradient pulls air from the mountains toward the plain.","cn":"强烈的气压梯度把空气从山地拉向平原。"},{"en":"The designer added a gradient that fades from green to white.","cn":"设计师加了一层由绿到白的渐变。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「格瑞迪恩特」太长，记住核心「格」：一格一格地变，就是渐变与梯度。","word":"gradient"},"root":"拉丁语 gradus「台阶、等级」与 gradi「行走、迈步」，经分词形式进入学术英语；数学义在十九世纪由微积分与物理学造出。英语 gradient。","sensesIntro":{"en":"Eight senses follow one idea: change measured step by step. The steps run from a road's rise to a colour fade, a curve's tangent, a physical rate, a social scale, a manner of change, a railway grade and a slide in pitch.","cn":"八个义项沿一个观念展开：一步一步量出的变化。这些步子从道路的上升，延伸到颜色渐变、曲线切线、物理变化率、社会阶梯、渐变方式、铁路纵坡与音高滑动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a staircase whose steps change colour and height as it goes, so each step measures a difference.","cn":"核心意象：一段台阶边走边变色、边升高，每一级都在量一个差别。"},"chain":["STEP","RISE OF A ROAD","RATE OF CHANGE","SMOOTH FADE","SOCIAL SCALE","SLIDING PITCH"],"branches":[{"senses":"S1 · S7","en":"BUILT SLOPE: a road and a railway both turn the step-root into a measured climb.","cn":"人工坡道：道路与铁路都把「台阶」词根变成可测量的爬升。"},{"senses":"S2 · S6","en":"SMOOTH CHANGE: a colour fade and a gradual manner are change without a jump.","cn":"平滑变化：颜色渐变与渐进方式都是不跳跃的变化。"},{"senses":"S3","en":"CURVE: calculus asks how steep a curve is at a single point.","cn":"曲线：微积分问的是曲线在单点上有多陡。"},{"senses":"S4","en":"PHYSICAL RATE: temperature and pressure change across space in the same way.","cn":"物理变化率：温度与压力在空间中以同样方式变化。"},{"senses":"S5 · S8","en":"HUMAN SCALE: social position and speech pitch are also read as steps between levels.","cn":"人的尺度：社会位置与语音音高也被读成层级之间的台阶。"}]},"affixes":{"intro":{"en":"Gradient is built from the Latin step-root plus an adjectival ending, and that root also builds a large English family.","cn":"该词由拉丁「台阶」词根加形容词性词尾构成，这个词根还构成一个很大的英语词族。"},"latinIntro":{"en":"Latin gradi and gradus give gradient, gradation, gradual, grade and graduate, all through the idea of a step.","cn":"拉丁语的「行走」与「台阶」衍生出本词以及表示渐变、逐渐、等级与毕业的词，核心都是「一步」。"},"items":[{"word":"gradi","structure":"gradi (Latin verb, third conjugation, deponent)","meaning":"to walk, step","meaningCN":"行走；迈步","example":"The root supplies the image of walking up a slope.","exampleCN":"这个词根提供「走上斜坡」的意象。"},{"word":"gradus","structure":"gradus, gradus (m., fourth declension)","meaning":"step, degree","meaningCN":"台阶；等级","example":"Every measurement on a slope is a kind of step.","exampleCN":"斜坡上的每一次测量都像一级台阶。"},{"word":"gradient","structure":"gradi + -ent (present participle ending)","meaning":"walking; the rate of rise","meaningCN":"行走的；上升的速率","example":"The gradient tells how fast the ground rises.","exampleCN":"梯度说明地面上升得多快。"},{"word":"gradation","structure":"gradus + -ation (process or result)","meaning":"arrangement in steps","meaningCN":"渐变；分级","example":"The gradation from grey to black is barely visible.","exampleCN":"从灰到黑的渐变几乎看不出来。"},{"word":"gradual","structure":"gradus + -al (relating to)","meaning":"step by step","meaningCN":"逐步的；逐渐的","example":"The gradual warming changed the lake.","exampleCN":"逐渐的升温改变了这个湖。"},{"word":"gradually","structure":"gradual + -ly (manner)","meaning":"in small steps","meaningCN":"逐渐地","example":"The path gradually climbs above the trees.","exampleCN":"小路逐渐升到树林之上。"},{"word":"grade","structure":"gradus -> grade (rank or level)","meaning":"a level or rank","meaningCN":"等级；级别","example":"The road has a grade of five percent.","exampleCN":"这条路的纵坡为百分之五。"},{"word":"graduate","structure":"gradus + -ate (to take a step)","meaning":"to complete a course","meaningCN":"毕业；完成学业","example":"She will graduate next spring.","exampleCN":"她明年春天毕业。"},{"word":"isograd","structure":"iso- (equal) + gradient","meaning":"a line of equal gradient","meaningCN":"等梯度线","example":"The map draws an isograd across the basin.","exampleCN":"地图在盆地上画出一条等梯度线。"}],"latinEntries":[{"word":"gradus","structure":"gradus, gradus (m., fourth declension)","meaning":"step, degree, rank","meaningCN":"台阶；等级；级别"},{"word":"gradi","structure":"gradi, gressus sum (verb, third conjugation, deponent)","meaning":"to walk, step, go","meaningCN":"行走；迈步；前进"},{"word":"gradatio","structure":"gradatio, gradationis (f., third declension)","meaning":"a stepping, a gradual advance","meaningCN":"逐级上升；渐进"},{"word":"gradiens","structure":"gradiens, gradientis (present participle of gradi)","meaning":"walking, going","meaningCN":"行走的；前进的"}]}},{"word":"incline","ipa_uk":"/ɪnˈklaɪn/","ipa_us":"/ɪnˈklaɪn/","definition_zh":"倾向；使倾斜；倾斜；斜坡；使愿意；点头","definition_en":"to lean or slope, to make something lean, or to be willing to do something","core_image":"一根靠在墙边的梯子，顶端慢慢向墙面倒过去","scene":"过了桥之后，小路开始明显向上抬升。The path begins to incline sharply after the bridge.","sceneCN":"这里该词指「道路向上倾斜」（第 3 个义项：地面呈斜度延伸）；句意为过桥之后小路开始陡然上斜。","pos":[{"tag":"vi.","zh":"倾斜；有坡度；倾向于"},{"tag":"vt.","zh":"使倾斜；使倾向于"},{"tag":"n.","zh":"斜坡；斜面"}],"collocations":[{"phrase":"be inclined to do","zh":"倾向于做某事"},{"phrase":"incline toward","zh":"倾向于；偏向"},{"phrase":"a steep incline","zh":"陡坡"},{"phrase":"incline the head","zh":"点头；低头"},{"phrase":"an upward incline","zh":"上坡"},{"phrase":"incline to agree","zh":"倾向于同意"}],"forms":[{"label":"三单（动词）","form":"inclines"},{"label":"过去式","form":"inclined"},{"label":"过去分词","form":"inclined"},{"label":"现在分词","form":"inclining"},{"label":"名词（倾向）","form":"inclination"},{"label":"形容词（有倾向的）","form":"inclined"}],"derivatives":[{"word":"inclination","pos":"n.","zh":"倾向；倾斜；倾角"},{"word":"inclined","pos":"adj.","zh":"有倾向的；倾斜的"},{"word":"disinclined","pos":"adj.","zh":"不愿的；不感兴趣的"},{"word":"inclining","pos":"n./adj.","zh":"倾斜；倾向的"}],"senses":[{"no":"01","title":"To be willing to do something","titleCN":"倾向于、愿意做某事","definition":"to be willing or likely to do something","definitionCN":"愿意或很可能做某事","example":"I incline to agree with the second proposal.","exampleCN":"我倾向于同意第二个提案。","why":"Latin inclinare already meant both 'to lean' and 'to favour', so the mind leans toward a choice just as a body leans toward a wall.","whyCN":"拉丁语原词同时有「倾斜」与「偏向」两义，心朝某个选择倾过去，正如身体朝墙倾过去。"},{"no":"02","title":"To make something lean","titleCN":"使某物倾斜","definition":"to cause an object to lean or be set at an angle","definitionCN":"使物体倾斜或以某个角度放置","example":"He inclined the mirror toward the window.","exampleCN":"他把镜子朝窗户倾斜。","why":"The causative sense adds an object to the basic act of leaning.","whyCN":"使役义只是给基本的倾斜动作加上宾语。"},{"no":"03","title":"To slope upward or downward","titleCN":"地面向上或向下倾斜","definition":"to rise or fall at an angle, said of ground or a path","definitionCN":"指地面或道路呈角度上升或下降","example":"The path begins to incline sharply after the bridge.","exampleCN":"过桥之后小路开始陡然上斜。","why":"The physical sense is the oldest: a surface inclines when it leans away from the horizontal.","whyCN":"物理义最古老：地面离开水平面时，就是倾斜。"},{"no":"04","title":"To persuade someone toward a choice","titleCN":"使某人倾向于某个选择","definition":"to make someone more willing to accept or choose something","definitionCN":"使某人更愿意接受或选择某事","example":"The evidence inclined the committee toward delay.","exampleCN":"这些证据使委员会倾向于推迟。","why":"Persuasion is a push that tilts a mind, so the leaning verb took on a causal social sense.","whyCN":"说服是把心思扳斜的一推，于是这个倾斜动词获得了社会性的使役义。"},{"no":"05","title":"A sloping surface","titleCN":"斜坡（名词）","definition":"a sloping surface, especially on a road or railway","definitionCN":"倾斜的表面，尤指道路或铁路上的","example":"The train slowed as it reached the incline.","exampleCN":"火车到达斜坡时减速。","why":"The noun keeps the first-syllable stress and names the slope itself rather than the act.","whyCN":"名词重音落在第一音节，指斜坡本身，而非倾斜动作。"},{"no":"06","title":"The inclined plane","titleCN":"力学中的斜面","definition":"a flat surface set at an angle, used as one of the simple machines","definitionCN":"以一定角度放置的平面，用作简单机械之一","example":"A ramp is an inclined plane that trades distance for force.","exampleCN":"坡道是一种斜面，用距离换取省力。","why":"Mechanics fixed the phrase inclined plane for a slope used to raise loads.","whyCN":"力学固定了「斜面」这一说法，指用来抬高重物的斜坡。"},{"no":"07","title":"To bow or nod","titleCN":"点头；低头","definition":"to bend the head or body forward slightly","definitionCN":"使头或身体略向前弯","example":"She inclined her head to hear the whisper.","exampleCN":"她低下头去听那句耳语。","why":"A bow is a brief lean of the body, the same gesture at human scale.","whyCN":"鞠躬就是身体短暂的倾斜，是同一动作在人身上的尺度。"},{"no":"08","title":"A trend in a series","titleCN":"数据或价格的走势","definition":"to tend upward or downward over a period","definitionCN":"在一段时间内呈上升或下降趋势","example":"Prices incline upward as the season ends.","exampleCN":"季末价格呈上行趋势。","why":"A trend line leans in one direction, so the verb describes a movement in figures.","whyCN":"趋势线朝一个方向倾斜，于是这个动词也用于描述数字的走向。"}],"etymology":{"intro":{"en":"Incline comes from Latin inclinare 'to bend toward', built on in- 'toward' and clinare 'to bend'. The same root gives decline, recline and climate. Dates are approximate.","cn":"该词来自拉丁语表示「朝……弯」的动词，由表示「朝向」的前缀与表示「弯」的词根构成。同一词根还给出表示下降、向后靠与气候的词。年代均为约数。"},"items":[{"era":"LATIN CLINARE","en":"clinare 'to bend, lean' is the root; it also underlies English decline and recline.","cn":"表示「弯、倾」的词根，也是英语中表示下降与向后靠两词的基础。"},{"era":"LATIN INCLINARE","en":"in- 'toward' plus clinare made inclinare 'to bend toward, lean', used for bodies, ground and minds.","cn":"表示「朝向」的前缀加「弯」构成「朝……弯、倾斜」，可用于身体、地面与心思。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French encliner brought the verb into English, where it kept both the physical and the mental senses.","cn":"古法语把这个动词带入英语，物理义与心理义都保留下来。"},{"era":"NOUN STRESS","en":"The noun incline shifted stress to the first syllable, a common way English marks a noun beside its verb.","cn":"名词把重音移到第一音节，这是英语区分名词与动词的常见方式。"},{"era":"MECHANICS","en":"The phrase inclined plane became standard in physics for one of the simple machines.","cn":"「斜面」这一说法在物理学中成为简单机械之一的标准名称。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin history of clinare is unsettled, and the first date of the noun is approximate.","cn":"来源不确定（更深词源）：该词根在拉丁语之前的来历无定论，名词首见年代为约数。"}]},"similar":{"note":{"en":"Group one holds words built on the same leaning root with different prefixes; group two holds verbs and nouns that also express a tilt or a tendency.","cn":"第一组是同出「倾斜」词根、前缀不同的词；第二组是同样表示倾斜或倾向的动词与名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decline","ipa":"/dɪˈklaɪn/","tag":"bend downward","definition":"De- 'down' plus clinare: to slope down, fall in number, or refuse politely.","definitionCN":"表示「向下」的前缀加「弯」：向下倾斜、数量下降，或委婉拒绝。"},{"word":"recline","ipa":"/rɪˈklaɪn/","tag":"lean back","definition":"Re- 'back' plus clinare: to lean the body backward, as in a reclining seat.","definitionCN":"表示「向后」的前缀加「弯」：身体向后靠，如可躺座椅。"},{"word":"climate","ipa":"/ˈklaɪmət/","tag":"same root through Greek","definition":"From Greek klima 'slope, zone', from the same bend-root: the slant of the sun over a region.","definitionCN":"经希腊语「斜坡、地带」而来，同出这一「弯」词根：指太阳对某一地区的斜射角。"},{"word":"lean","ipa":"/liːn/","tag":"plain English verb","definition":"The everyday verb for leaning; it is not derived from the Latin word but covers the same physical act.","definitionCN":"表示倾斜的日常动词；并非由该拉丁词派生，但描述同一身体动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"slope","ipa":"/sləʊp/","tag":"the surface","definition":"The slanting ground itself or its angle; incline can also name the surface but often stresses the act.","definitionCN":"指倾斜的地面或其角度；本词也可指地面，但更常强调动作。"},{"word":"tilt","ipa":"/tɪlt/","tag":"tip sideways","definition":"To tip an object to one side, often sharply; incline is usually gentler and can be mental.","definitionCN":"使物体向一侧翘起，常较突然；本词通常更平缓，且可用于心理。"},{"word":"tend","ipa":"/tend/","tag":"be likely","definition":"To be likely to do or be something; it covers the mental sense without the physical image.","definitionCN":"指很可能做某事或呈某状态；可表达心理义，但不带物理意象。"},{"word":"persuade","ipa":"/pəˈsweɪd/","tag":"win someone over","definition":"To cause someone to agree by argument; incline is a milder shift of willingness.","definitionCN":"通过论证使人同意；本词是更轻微的意愿偏移。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'toward' + clinare 'bend': leaning toward something, in body or in mind.","cn":"表示「朝向」的前缀加「弯」：朝某物倾过去，身体如此，心思也如此。"},{"en":"The family runs incline, inclination, inclined, disinclined, inclining.","cn":"同族词包括本词、表示倾向的名词、表示有倾向的形容词、表示不愿的形容词与现在分词。"},{"en":"Fixed phrases mark the senses: be inclined to do, incline the head, a steep incline.","cn":"固定搭配标出各义项：倾向于做、点头、陡坡。"},{"en":"The root also builds decline and recline, where the prefixes direct the lean.","cn":"这个词根还构成表示下降与向后靠的两个词，由前缀决定倾斜的方向。"},{"en":"The noun shifts stress forward: IN-cline, while the verb says in-CLINE.","cn":"名词重音前移，动词重音在后，以此区分词性。"}],"abstract":[{"en":"Picture a ladder slowly settling toward a wall.","cn":"想象一架梯子慢慢朝墙倒过去。"},{"en":"Picture a judge's head tipping a few degrees to catch a whispered word.","cn":"想象法官把头偏几度，去听一句耳语。"},{"en":"Picture a committee's mood tilting toward one option after one strong fact.","cn":"想象一个委员会的情绪在一条有力事实之后倒向一个选项。"}]},"examples":[{"en":"Most residents incline toward keeping the old market open.","cn":"多数居民倾向于让老市场继续开下去。"},{"en":"The road inclines gently for the first mile and then turns steep.","cn":"道路在第一英里平缓上斜，随后变陡。"},{"en":"She inclined her head and waited for him to finish.","cn":"她低下头，等他讲完。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「因克莱恩」：因为克莱恩一靠，墙就斜了——倾斜。","word":"incline"},"root":"拉丁语 in-（朝向）+ clinare（弯、倾）构成 inclinare「朝……弯、倾斜」；同一词根还构成 decline、recline 与 climate。英语 incline。","sensesIntro":{"en":"Eight senses follow one gesture: leaning toward something. The gesture is applied to the mind's willingness, a tilted object, sloping ground, a persuaded choice, a railway grade, a simple machine, a bowing head and a trend line.","cn":"八个义项沿同一个动作展开：朝某物倾过去。这个动作依次用于心思的意愿、被倾斜的物体、倾斜的地面、被说服的选择、铁路坡度、简单机械、低下的头和趋势线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body or surface slowly leaning toward a support until it rests against it.","cn":"核心意象：身体或表面慢慢朝支撑物倾过去，直到靠住。"},"chain":["LEAN TOWARD","SLOPE UP","WILLING MIND","PERSUADE","SLOPING SURFACE","INCLINED PLANE"],"branches":[{"senses":"S1 · S4","en":"MIND: willingness leans toward a choice, and evidence can push that lean.","cn":"心思：意愿朝某个选择倾过去，证据可以推动这个倾斜。"},{"senses":"S2 · S3 · S5","en":"BODY AND GROUND: an object, a path and a railway all take the same angle.","cn":"物体与地面：物件、小路与铁路都取同一个角度。"},{"senses":"S6","en":"MACHINE: the inclined plane turns a lean into mechanical advantage.","cn":"机械：斜面把倾斜变成机械利益。"},{"senses":"S7","en":"GESTURE: a bow is a brief human-sized incline.","cn":"姿态：鞠躬是人身上短暂的倾斜。"},{"senses":"S8","en":"TREND: a line of figures leans steadily in one direction.","cn":"趋势：一串数字形成的线朝一个方向稳定倾斜。"}]},"affixes":{"intro":{"en":"Incline is a Latin verb of prefix plus root, and both parts also build other English words.","cn":"该词是前缀加词根构成的拉丁动词，这两部分还构成其他英语词。"},"latinIntro":{"en":"Latin clinare gives incline, decline, recline and climate; in- adds direction toward something.","cn":"拉丁语「弯、倾」衍生本词以及表示下降、向后靠与气候的词；表示「朝向」的前缀增添方向。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'toward, into')","meaning":"toward","meaningCN":"朝向；进入","example":"The prefix points the lean at something.","exampleCN":"这个前缀把倾斜指向某个目标。"},{"word":"clinare","structure":"clinare (Latin verb, first conjugation)","meaning":"to bend, lean","meaningCN":"弯；倾","example":"The root carries the physical bend.","exampleCN":"词根承载物理上的弯曲。"},{"word":"incline","structure":"in- + clinare","meaning":"to lean toward","meaningCN":"朝……倾斜","example":"The path begins to incline after the bridge.","exampleCN":"过桥后小路开始上斜。"},{"word":"inclination","structure":"incline + -ation (state or action)","meaning":"a tendency or a tilt","meaningCN":"倾向；倾斜","example":"Her inclination was to wait.","exampleCN":"她的倾向是等待。"},{"word":"inclined","structure":"incline + -ed (past participle or adjective)","meaning":"willing or slanted","meaningCN":"有意的；倾斜的","example":"The board is inclined at a slight angle.","exampleCN":"木板略微倾斜。"},{"word":"decline","structure":"de- (down) + clinare","meaning":"to bend downward","meaningCN":"向下弯；下降","example":"Sales decline in winter.","exampleCN":"冬天销量下降。"},{"word":"recline","structure":"re- (back) + clinare","meaning":"to lean back","meaningCN":"向后靠","example":"The seat reclines almost flat.","exampleCN":"座椅几乎能放平。"},{"word":"disinclined","structure":"dis- (away) + inclined","meaning":"unwilling","meaningCN":"不愿的","example":"He was disinclined to argue.","exampleCN":"他不愿争论。"},{"word":"inclined plane","structure":"inclined + plane (compound term)","meaning":"a sloped flat surface","meaningCN":"斜面","example":"An inclined plane reduces the force needed.","exampleCN":"斜面能减少所需的力。"}],"latinEntries":[{"word":"clinare","structure":"clinare, clinavi, clinatum (verb, first conjugation)","meaning":"to bend, turn, incline","meaningCN":"弯；转；倾"},{"word":"inclinare","structure":"inclinare, inclinavi, inclinatum (verb, first conjugation)","meaning":"to bend toward, lean","meaningCN":"朝……弯；倾斜"},{"word":"inclinatio","structure":"inclinatio, inclinationis (f., third declension)","meaning":"a leaning, tendency","meaningCN":"倾斜；倾向"}]}},{"word":"coastline","ipa_uk":"/ˈkəʊstlaɪn/","ipa_us":"/ˈkoʊstlaɪn/","definition_zh":"海岸线；海岸带；海岸轮廓","definition_en":"the line where the land meets the sea, or the shape of that edge","core_image":"一条弯弯曲曲的线，把蓝色海面与绿色陆地分开","scene":"暴风雨在一夜之间改变了海岸线的形状。The storm reshaped the coastline overnight.","sceneCN":"这里该词指「陆地与海交界处的轮廓」（第 1 个义项：海陆分界线）；句意为暴风雨一夜之间改变了海岸的轮廓。","pos":[{"tag":"n.","zh":"海岸线；海岸带；海岸轮廓"}],"collocations":[{"phrase":"a rugged coastline","zh":"崎岖的海岸线"},{"phrase":"coastline erosion","zh":"海岸侵蚀"},{"phrase":"along the coastline","zh":"沿着海岸线"},{"phrase":"coastline management","zh":"海岸线管理"},{"phrase":"the coastline length","zh":"海岸线长度"},{"phrase":"a coastline survey","zh":"海岸线测量"}],"forms":[{"label":"复数（名词）","form":"coastlines"},{"label":"形容词（海岸的）","form":"coastal"},{"label":"名词（海岸）","form":"coast"},{"label":"副词（沿海地）","form":"coastally"}],"derivatives":[{"word":"coastal","pos":"adj.","zh":"海岸的；沿海的"},{"word":"coast","pos":"n./v.","zh":"海岸；沿海航行"},{"word":"coastward","pos":"adv./adj.","zh":"朝海岸方向"},{"word":"coastland","pos":"n.","zh":"沿海陆地"}],"senses":[{"no":"01","title":"The edge where land meets sea","titleCN":"陆地与海交界的分界线","definition":"the line along which the land meets the sea","definitionCN":"陆地与海相接的那条线","example":"The storm reshaped the coastline overnight.","exampleCN":"暴风雨一夜之间改变了海岸线的形状。","why":"coast names the land's side and line names the edge, so the compound is literally the side-line of the land.","whyCN":"前半指陆地的侧边，后半指界线，合起来字面就是陆地的边线。"},{"no":"02","title":"The coastal strip","titleCN":"海岸带：沿海的一片区域","definition":"the strip of land and water near the shore, treated as one zone","definitionCN":"近岸的陆地与水域，作为一个地带看待","example":"Farms occupy the narrow coastline west of the hills.","exampleCN":"农场占据山丘以西那条狭窄的海岸带。","why":"Planners extended the line into a zone, because the land and water within it affect each other.","whyCN":"规划者把这条线扩展成一个地带，因为其中的陆地与水域相互影响。"},{"no":"03","title":"The outline of a coast","titleCN":"海岸的轮廓与走向","definition":"the shape or outline of a coast as seen on a map","definitionCN":"海岸在地图上呈现的形状或轮廓","example":"The coastline curves inward around the bay.","exampleCN":"海岸线在湾口处向内弯曲。","why":"A line on a map represents the shape of the edge, so the word also names that outline.","whyCN":"地图上的线代表边缘形状，因此这个词也指那个轮廓。"},{"no":"04","title":"Measured length of a coast","titleCN":"海岸线的测量长度","definition":"the total length of a coast as measured at a given scale","definitionCN":"在给定比例尺下测得的海岸总长度","example":"Measuring the coastline gives a different answer at every scale.","exampleCN":"在不同比例尺下测量海岸线，会得到不同的长度。","why":"A coast is so irregular that its length depends on the ruler used, a puzzle named after the coastline.","whyCN":"海岸太不规则，长度取决于所用尺子，这一难题正是以海岸线命名的。"},{"no":"05","title":"A coast retreating under erosion","titleCN":"受侵蚀而后退的海岸线","definition":"a coastline that is moving inland as waves and currents wear it away","definitionCN":"因波浪与水流侵蚀而向内陆移动的海岸线","example":"The coastline has retreated ten metres in twenty years.","exampleCN":"二十年间海岸线后退了十米。","why":"The word can name not only the edge but its movement, because an eroding coast is never still.","whyCN":"这个词不仅能指边缘，也能指边缘的移动，因为受侵蚀的海岸从不安定。"},{"no":"06","title":"The line drawn on a chart","titleCN":"地图或海图上的海岸线","definition":"the line on a map or chart that marks the shore","definitionCN":"地图或海图上标示岸线的线","example":"The chart shows the coastline in fine detail.","exampleCN":"海图细致地标出了海岸线。","why":"Cartography made the line a graphic object, separate from the physical shore it represents.","whyCN":"制图学把这条线变成图形对象，与它所代表的实际岸线分开。"},{"no":"07","title":"Coastal habitat","titleCN":"海岸生态与栖息地","definition":"the coastal environment as a habitat for wildlife","definitionCN":"作为野生生物栖息地的沿海环境","example":"The coastline supports nesting birds and shellfish beds.","exampleCN":"这片海岸养活了筑巢的鸟与贝类床。","why":"Ecology treats the edge as a living zone rather than a line, so the word came to mean habitat.","whyCN":"生态学把这条边缘当作活的区域而非一条线，于是这个词也指栖息地。"},{"no":"08","title":"A line to be defended","titleCN":"需要防护的岸线","definition":"the coast as an object of engineering protection against the sea","definitionCN":"作为工程防护对象的岸线","example":"Engineers reinforced the coastline with stone walls.","exampleCN":"工程师用石墙加固了岸线。","why":"Coastal defence treats the coast as a boundary to be held, which gives the word this engineering sense.","whyCN":"海岸防护把海岸当作要守住的边界，因此产生这一工程义。"}],"etymology":{"intro":{"en":"Coastline joins coast, from Latin costa 'rib, side', to line, from Latin linea 'thread'. The compound itself is modern English. Dates are approximate.","cn":"该词把来自拉丁语「肋骨、侧边」的词与来自拉丁语「线」的词组合起来，复合词本身是近代英语。年代均为约数。"},"items":[{"era":"LATIN COSTA","en":"costa meant 'rib, side, flank'; through Old French coste it named the side of a land facing the sea.","cn":"拉丁语词意为「肋骨、侧边、侧翼」；经古法语进入英语后指陆地朝海的一侧。"},{"era":"LATIN LINEA","en":"linea 'linen thread, string' gives English line, linear and lineage.","cn":"拉丁语「亚麻线、绳」给出英语中表示线、线形与世系的词。"},{"era":"ENGLISH COMPOUND","en":"Coastline is an English compound of the two words, recorded in the nineteenth century when survey maps needed a name for the edge itself.","cn":"该复合词由这两个词在英语中组合而成，十九世纪有记录，当时测量地图需要给边缘本身命名。"},{"era":"MEASUREMENT PUZZLE","en":"Twentieth-century mathematics used the coastline to show that length grows as the measuring stick shrinks.","cn":"二十世纪数学用海岸线说明：量尺越短，量出的长度越大。"},{"era":"COASTAL MANAGEMENT","en":"The rise of coastal management in the same century made coastline a term in planning and engineering.","cn":"同一世纪海岸管理的兴起，使这个词成为规划与工程术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest citation for coastline is not precisely fixed, and dates are approximate.","cn":"来源不确定（首见年代）：该复合词的最早书证没有确切记录，年代为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike words including a false pair; group two holds words that also name the sea's edge.","cn":"第一组是形近词，其中有一对容易误认的假同源；第二组是同样指海陆边缘的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"coast","ipa":"/kəʊst/","tag":"the land side","definition":"The land next to the sea; coastline is the edge or outline of that land.","definitionCN":"指临海的陆地；本词指这片陆地的边缘或轮廓。"},{"word":"coastal","ipa":"/ˈkəʊstl/","tag":"adjective form","definition":"Relating to the coast; it is the adjective while coastline is the noun.","definitionCN":"指与海岸有关的；它是形容词，而本词是名词。"},{"word":"costal","ipa":"/ˈkɒstl/","tag":"ribs, not coast","definition":"Relating to the ribs, from Latin costa 'rib'; it looks like coastal but belongs to anatomy.","definitionCN":"指与肋骨有关的，来自拉丁语「肋骨」；形似形容词形式，却属解剖学。"},{"word":"coaster","ipa":"/ˈkəʊstə/","tag":"ship or mat","definition":"A ship that sails along a coast, or a small mat for a glass; it is a derivative of coast, not of coastline.","definitionCN":"指沿海航行的船，或杯垫；它是前半部分的派生词，不是本词的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"shore","ipa":"/ʃɔː/","tag":"the land at the water","definition":"The land along the edge of a sea or lake; it can include the beach, while coastline stresses the line.","definitionCN":"指海或湖边的陆地；可包括沙滩，而本词更强调那条线。"},{"word":"shoreline","ipa":"/ˈʃɔːlaɪn/","tag":"water's edge","definition":"The line where water meets land, especially of a lake or sea; it is close to coastline but less tied to maps.","definitionCN":"指水与陆相接的线，尤用于湖或海；与本词接近，但较少用于地图。"},{"word":"seaboard","ipa":"/ˈsiːbɔːd/","tag":"coastal region","definition":"The land along a sea, viewed as a region; it is broader than the line itself.","definitionCN":"指沿海的一片陆地，作为区域看待；比一条线更宽。"},{"word":"beach","ipa":"/biːtʃ/","tag":"sand by the water","definition":"The sandy or pebbly strip at the water's edge; it is a material place, not a line.","definitionCN":"指水边由沙或卵石构成的条带；它是实物地带，不是一条线。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"coast 'side of the land' + line 'edge': the side-line of the land.","cn":"前半指陆地的侧边，后半指界线：合起来就是陆地的边线。"},{"en":"The family runs coast, coastal, coastline, coastward, coastland.","cn":"同族词包括本词的前半部分、其形容词、本词、朝岸方向词与沿海陆地词。"},{"en":"Fixed phrases mark the senses: rugged coastline, coastline erosion, coastline management.","cn":"固定搭配标出各义项：崎岖海岸线、海岸侵蚀、海岸线管理。"},{"en":"The false pair costal means 'rib-related', not 'coastal'.","cn":"形近的对比词意为「肋骨的」，而不是「海岸的」。"},{"en":"A coastline's measured length grows as the ruler gets shorter.","cn":"量尺越短，海岸线量出的长度越长。"}],"abstract":[{"en":"Picture a blue thread laid along the border of a green cloth.","cn":"想象一根蓝线沿着一块绿布的边缘铺开。"},{"en":"Picture a map whose edge keeps redrawing itself after every storm.","cn":"想象一张地图，每次风暴过后边缘都要重画。"},{"en":"Picture a ruler so short that it can follow every tiny curve of a shore.","cn":"想象一把短到能贴着岸边每一道小弯走的尺子。"}]},"examples":[{"en":"The island's coastline is broken by deep inlets and rocky points.","cn":"这座岛的海岸线被深湾与岩角切得破碎。"},{"en":"Rising seas threaten the low coastline near the delta.","cn":"海面上升威胁着三角洲附近的低平海岸。"},{"en":"The survey team walked the coastline from end to end.","cn":"测量队从一端走到另一端，走完了整条海岸线。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「扣死特莱恩」：把海岸的边线扣死在地图上——海岸线。","word":"coastline"},"root":"coast 来自拉丁语 costa「肋骨、侧边」，经古法语指陆地朝海的一侧；line 来自拉丁语 linea「线」。二者在英语中复合为 coastline。","sensesIntro":{"en":"Eight senses follow one edge: the meeting of land and sea. The edge is then widened into a zone, read as an outline, measured, watched as it retreats, drawn on charts, treated as habitat and finally defended as a boundary.","cn":"八个义项沿一条边缘展开：陆地与海的相接处。这条边缘随后被扩展成地带、读作轮廓、加以测量、观察其后退、画上海图、当作栖息地，最后作为边界加以防护。"},"semanticMap":{"core":{"en":"CORE IMAGE: a single wavering line separating blue water from green land.","cn":"核心意象：一条起伏的线，把蓝色海水与绿色陆地分开。"},"chain":["LAND-SEA EDGE","COASTAL ZONE","OUTLINE","MEASURED LENGTH","RETREAT","DEFENDED BOUNDARY"],"branches":[{"senses":"S1 · S3 · S6","en":"THE LINE: the physical edge, its map outline and its chart line are the same boundary seen three ways.","cn":"那条线：实际边缘、地图轮廓与海图线是同一边界的三种看法。"},{"senses":"S2 · S7","en":"THE ZONE: planners and ecologists widen the line into a strip of land and water.","cn":"那个地带：规划者与生态学者把线扩成一条陆水地带。"},{"senses":"S4","en":"MEASUREMENT: the length depends on the scale of the ruler.","cn":"测量：长度取决于量尺的比例。"},{"senses":"S5","en":"MOVEMENT: an eroding coast makes the line itself travel inland.","cn":"移动：受侵蚀的海岸使这条线本身向内陆移动。"},{"senses":"S8","en":"DEFENCE: engineering treats the edge as a boundary that must be held.","cn":"防护：工程把这条边缘当作必须守住的边界。"}]},"affixes":{"intro":{"en":"Coastline is an English compound of two Latin loanwords, so each half can be read separately even though the compound is modern.","cn":"该词是两个拉丁借词在英语中的复合，虽属近代造词，两半仍可分开读。"},"latinIntro":{"en":"Latin costa gives coast and coastal; Latin linea gives line and linear. The compound adds no new morpheme.","cn":"拉丁语「肋骨、侧边」给出本词的前半与形容词形式；拉丁语「线」给出后半与线形形容词。复合本身没有新增语素。"},"items":[{"word":"coast","structure":"coast (from Latin costa 'rib, side')","meaning":"the land beside the sea","meaningCN":"临海的陆地","example":"The coast runs north for many miles.","exampleCN":"海岸向北延伸许多英里。"},{"word":"line","structure":"line (from Latin linea 'thread')","meaning":"a long mark or edge","meaningCN":"长线；边缘","example":"A thin line marks the border.","exampleCN":"一条细线标出边界。"},{"word":"coastline","structure":"coast + line (English compound)","meaning":"the edge of the coast","meaningCN":"海岸的边缘","example":"The coastline bends around the bay.","exampleCN":"海岸线绕过海湾。"},{"word":"coastal","structure":"coast + -al (relating to)","meaning":"of the coast","meaningCN":"海岸的","example":"Coastal roads flood in winter.","exampleCN":"沿海道路在冬天会被淹。"},{"word":"coastward","structure":"coast + -ward (direction)","meaning":"toward the coast","meaningCN":"朝海岸方向","example":"The wind turned coastward at noon.","exampleCN":"中午风转向海岸。"},{"word":"coastland","structure":"coast + land (compound)","meaning":"land along a coast","meaningCN":"沿海陆地","example":"Coastland is protected from new building.","exampleCN":"沿海陆地受保护，不许新建。"},{"word":"shoreline","structure":"shore + line (parallel compound)","meaning":"the water's edge","meaningCN":"水岸线","example":"The shoreline moves with the tide.","exampleCN":"水岸线随潮水移动。"},{"word":"coastline erosion","structure":"coastline + erosion (compound term)","meaning":"wear of the coastal edge","meaningCN":"海岸侵蚀","example":"Coastline erosion closed the path.","exampleCN":"海岸侵蚀使小路关闭。"}],"latinEntries":[{"word":"costa","structure":"costa, costae (f., first declension)","meaning":"rib, side, flank","meaningCN":"肋骨；侧边；侧翼"},{"word":"linea","structure":"linea, lineae (f., first declension)","meaning":"line, thread","meaningCN":"线；绳"},{"word":"costalis","structure":"costalis, costale (adj., third declension)","meaning":"of the ribs","meaningCN":"肋骨的"}]}},{"word":"peninsula","ipa_uk":"/pəˈnɪnsjələ/","ipa_us":"/pəˈnɪnsələ/","definition_zh":"半岛；半岛状地带；伸入水中的陆块","definition_en":"a piece of land almost surrounded by water but still joined to the mainland","core_image":"一块三面被水包围、只有一条窄颈连着大陆的陆地","scene":"一座灯塔立在半岛的尽头。A lighthouse stands at the tip of the peninsula.","sceneCN":"这里该词指「三面环水、一面连陆的陆地」（第 1 个义项：伸入水中的陆块）；句意为灯塔立在半岛尖端。","pos":[{"tag":"n.","zh":"半岛；半岛状地带"}],"collocations":[{"phrase":"the Iberian Peninsula","zh":"伊比利亚半岛"},{"phrase":"a narrow peninsula","zh":"狭长的半岛"},{"phrase":"the tip of the peninsula","zh":"半岛的尖端"},{"phrase":"a peninsula region","zh":"半岛地区"},{"phrase":"on the peninsula","zh":"在半岛上"},{"phrase":"a peninsula resort","zh":"半岛度假地"}],"forms":[{"label":"复数（名词）","form":"peninsulas"},{"label":"形容词（半岛的）","form":"peninsular"},{"label":"复合名词（半岛尖端）","form":"peninsula tip"}],"derivatives":[{"word":"peninsular","pos":"adj.","zh":"半岛的；半岛状的"},{"word":"peninsularity","pos":"n.","zh":"半岛状态；半岛特性"},{"word":"peninsula effect","pos":"n.","zh":"半岛效应（生态学）"}],"senses":[{"no":"01","title":"Land almost surrounded by water","titleCN":"半岛：三面环水、一面连陆的陆地","definition":"a piece of land that projects into water and is joined to the mainland by a narrow neck","definitionCN":"伸入水中、以狭窄地颈与大陆相连的陆块","example":"A lighthouse stands at the tip of the peninsula.","exampleCN":"一座灯塔立在半岛的尽头。","why":"Latin paene 'almost' plus insula 'island' names land that is almost an island, which is exactly the shape.","whyCN":"拉丁语「几乎」加「岛」构成「几乎是岛」，正是这种地形的形状。"},{"no":"02","title":"A peninsula-shaped area","titleCN":"半岛状地带","definition":"any land area shaped like a peninsula, even if small","definitionCN":"任何形状像半岛的陆地区域，即使很小","example":"The garden ends in a small peninsula of grass.","exampleCN":"花园尽头是一小块半岛状的草地。","why":"The shape, not the size, defines the word, so small projections can take it too.","whyCN":"决定这个词的是形状而非大小，因此小的突出地块也能用它。"},{"no":"03","title":"A geographic unit for study","titleCN":"作为地理单元的半岛","definition":"a peninsula treated as a unit of physical geography","definitionCN":"作为自然地理单元看待的半岛","example":"The peninsula has its own rainfall pattern.","exampleCN":"这个半岛有自己的一套降水规律。","why":"Geographers treat the joined landmass as one unit because its water on three sides shapes its climate.","whyCN":"地理学者把这块连陆的陆地当作一个单元，因为三面环水塑造了它的气候。"},{"no":"04","title":"The settled region on a peninsula","titleCN":"半岛上的居住区","definition":"the towns and countryside on a peninsula, seen as a region","definitionCN":"半岛上的城镇与乡村，作为一片地区看待","example":"Fishing villages ring the peninsula.","exampleCN":"渔村环绕着这个半岛。","why":"The landform becomes a human region once people settle it, so the word can name the place rather than the shape.","whyCN":"一旦有人定居，地形就变成人文区域，因此这个词可以指地方而非形状。"},{"no":"05","title":"A strategic salient","titleCN":"军事上的突出部","definition":"a military position that projects into enemy ground on three sides","definitionCN":"三面伸入敌方阵地的军事位置","example":"The troops held the peninsula against attacks from three sides.","exampleCN":"部队守住了这个三面受敌的突出部。","why":"A salient and a peninsula share the same exposed shape, so military language borrowed the word.","whyCN":"突出部与半岛共享同一种暴露的形状，军事语言便借用了这个词。"},{"no":"06","title":"A projection into another area","titleCN":"伸入他处的突出部分","definition":"a part of something that projects into a different area","definitionCN":"某物伸入另一区域的部分","example":"A dry peninsula of sand reached into the marsh.","exampleCN":"一段干燥的沙质突出部伸进沼泽。","why":"Any narrow projection can be pictured as a peninsula, which is how the metaphor works.","whyCN":"任何狭长的突出部分都能被想象成半岛，比喻就是这样运作的。"},{"no":"07","title":"The neck joining it to the mainland","titleCN":"半岛与大陆相连的地颈","definition":"the narrow link by which a peninsula is attached to the mainland","definitionCN":"半岛连接大陆的狭窄地带","example":"A road crosses the peninsula's narrow neck.","exampleCN":"一条路穿过半岛狭窄的地颈。","why":"Without the neck the land would be an island, so the joining strip is central to the definition.","whyCN":"没有地颈，这块陆地就是岛，因此连接地带是定义的核心。"},{"no":"08","title":"A named cultural region","titleCN":"专名中的半岛地区","definition":"a peninsula used in a proper name for a cultural or political region","definitionCN":"用于文化或政治区域专名的半岛","example":"The Korean peninsula has a long shared history.","exampleCN":"朝鲜半岛有悠久的共同历史。","why":"Proper names such as the Iberian Peninsula turn the landform into a political and cultural label.","whyCN":"伊比利亚半岛之类的专名把地形变成政治与文化标签。"}],"etymology":{"intro":{"en":"Peninsula comes from Latin paeninsula, literally 'almost an island', built on paene 'almost' and insula 'island'. Dates are approximate.","cn":"该词来自拉丁语，字面义为「几乎是岛」，由表示「几乎」与「岛」的两个词构成。年代均为约数。"},"items":[{"era":"LATIN PAENE","en":"paene meant 'almost, nearly', and it marks how close the land comes to being an island.","cn":"拉丁语词意为「几乎、将近」，标出这块陆地离岛有多近。"},{"era":"LATIN INSULA","en":"insula 'island' also gives English insular, isolate and insulation through related forms.","cn":"拉丁语「岛」还通过相关形式给出英语中表示岛屿的、使孤立的与绝缘的词。"},{"era":"LATIN PAENINSULA","en":"paeninsula joined the two words for land that is nearly but not fully surrounded by water.","cn":"两个词合成后，指几乎但并未完全被水包围的陆地。"},{"era":"ENGLISH BORROWING","en":"English took the word directly from Latin in the sixteenth century, keeping the geographic sense.","cn":"英语在十六世纪直接从拉丁语借入，保留了地理义。"},{"era":"MODERN USES","en":"Later use extended the shape to military salients, small projections and proper names of regions.","cn":"后来的用法把这种形状扩展到军事突出部、小型突出地块与地区专名。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation is not precisely fixed, and dates are approximate.","cn":"来源不确定（首见年代）：英语最早书证没有确切记录，年代为约数。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close to peninsula; group two holds other coastal landforms that are easily mixed up with it.","cn":"第一组是字形或读音接近该词的词；第二组是容易与它混淆的其他海岸地形词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"peninsular","ipa":"/pəˈnɪnsjələ/","tag":"adjective form","definition":"Relating to a peninsula; it is the adjective while peninsula is the noun.","definitionCN":"指与半岛有关的；它是形容词，而本词是名词。"},{"word":"insular","ipa":"/ˈɪnsjələ/","tag":"island-minded","definition":"Relating to an island, or narrow in outlook; it comes from Latin insula, the second half of peninsula.","definitionCN":"指岛屿的，或心胸狭隘的；来自拉丁语「岛」，正是本词的后半部分。"},{"word":"insulation","ipa":"/ˌɪnsjuˈleɪʃn/","tag":"different word","definition":"Material that stops heat or sound; it looks similar but belongs to a different Latin verb.","definitionCN":"指阻隔热量或声音的材料；形似但属于另一个拉丁动词。"},{"word":"peninsularity","ipa":"/pəˌnɪnsjəˈlærəti/","tag":"rare noun","definition":"The condition of being a peninsula or of having an isolated outlook; it is a rare derivative.","definitionCN":"指处于半岛状态或具有孤立心态；属罕见派生词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cape","ipa":"/keɪp/","tag":"point of land","definition":"A high point of land projecting into the sea; it is a point, not a nearly enclosed mass.","definitionCN":"指伸入海中的高地角；它是一个尖端，不是几乎被围住的陆块。"},{"word":"headland","ipa":"/ˈhedlənd/","tag":"cliff promontory","definition":"A narrow piece of land projecting into the sea, usually with a cliff; smaller and narrower than a peninsula.","definitionCN":"指伸入海中的狭长陆地，通常带悬崖；比半岛更小更窄。"},{"word":"spit","ipa":"/spɪt/","tag":"sand bar","definition":"A long narrow bank of sand or shingle projecting into water; it is built by currents, not by the mainland shape.","definitionCN":"指伸入水中的狭长沙洲或砾石洲；由水流堆积而成，不是大陆形状。"},{"word":"island","ipa":"/ˈaɪlənd/","tag":"fully surrounded","definition":"Land completely surrounded by water; the key contrast is that a peninsula still touches the mainland.","definitionCN":"指四面完全被水包围的陆地；关键差别是半岛仍与大陆相连。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"paene 'almost' + insula 'island': almost an island, still joined to land.","cn":"「几乎」加「岛」：几乎是岛，却仍连着陆地。"},{"en":"The family runs peninsula, peninsular, peninsularity and the ecological peninsula effect.","cn":"同族词包括本词、其形容词、其状态名词，以及生态学的半岛效应。"},{"en":"Fixed phrases mark the senses: the Iberian Peninsula, a narrow peninsula, the tip of the peninsula.","cn":"固定搭配标出各义项：伊比利亚半岛、狭长半岛、半岛尖端。"},{"en":"The key test is the neck: with a link to the mainland it is a peninsula, without one it is an island.","cn":"关键看地颈：与大陆相连就是半岛，没有连接就是岛。"},{"en":"The same shape serves as a metaphor for a military salient or any narrow projection.","cn":"同一形状可比喻军事突出部或任何狭长突出部分。"}],"abstract":[{"en":"Picture a hand with three fingers in water and the wrist still on the table.","cn":"想象一只手三根手指浸在水里，手腕仍搭在桌上。"},{"en":"Picture a conversation that almost leaves the main topic but stays tied to it by one thread.","cn":"想象一场谈话几乎离开主题，却被一根线牵住。"},{"en":"Picture a stage that juts into the audience while still joined to the back wall.","cn":"想象一个伸进观众席、却仍连着后墙的舞台。"}]},"examples":[{"en":"The peninsula shelters the harbour from the open sea.","cn":"这个半岛为港口挡住了外海。"},{"en":"They walked the length of the peninsula in a single afternoon.","cn":"他们用一个下午走完了整个半岛。"},{"en":"The narrow neck of the peninsula floods at high tide.","cn":"半岛狭窄的地颈在涨潮时会被淹。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「怕你死啦」：三面都是水，只剩一条窄路回家——半岛。","word":"peninsula"},"root":"拉丁语 paene（几乎）+ insula（岛）构成 paeninsula「几乎是岛」，指三面环水、一面连陆的陆地。英语 peninsula。","sensesIntro":{"en":"Eight senses follow one shape: land nearly cut off by water. The shape is then applied to small projections, a geographic unit, a settled region, a military salient, any narrow projection, the joining neck and a named cultural region.","cn":"八个义项沿同一个形状展开：几乎被水切断的陆地。这个形状随后用于小型突出地块、地理单元、居住区域、军事突出部、任何狭长突出部分、连接地颈以及专名中的文化区域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a broad hand of land reaching into water, held to the mainland by a narrow wrist.","cn":"核心意象：一只伸进水中的宽大陆掌，被狭窄的手腕连在大陆上。"},"chain":["ALMOST AN ISLAND","PROJECTING LAND","GEOGRAPHIC UNIT","SETTLED REGION","SALIENT","JOINING NECK"],"branches":[{"senses":"S1 · S7","en":"THE SHAPE: the projecting mass and the neck that keeps it from being an island.","cn":"形状：突出的陆块与使它不至于成为岛的地颈。"},{"senses":"S2 · S6","en":"SMALL PROJECTIONS: the same outline works at the scale of a garden or a sandbank.","cn":"小型突出：同一轮廓可用于花园或沙洲的尺度。"},{"senses":"S3","en":"GEOGRAPHY: three sides of water make the peninsula one climatic unit.","cn":"地理：三面环水使半岛成为一个气候单元。"},{"senses":"S4 · S8","en":"HUMAN LABEL: settlements and proper names turn the shape into a place.","cn":"人文标签：定居点与专名把形状变成地方。"},{"senses":"S5","en":"SALIENT: military language borrows the exposed outline.","cn":"突出部：军事语言借用了这种暴露的轮廓。"}]},"affixes":{"intro":{"en":"Peninsula is a Latin compound of an adverb and a noun, and both parts also build other English words.","cn":"该词是副词与名词构成的拉丁复合词，两部分还构成其他英语词。"},"latinIntro":{"en":"Latin paene 'almost' and insula 'island' combine in paeninsula; insula also gives insular and isolate.","cn":"拉丁语「几乎」与「岛」合成该词；「岛」还给出表示岛屿的形容词与使孤立的动词。"},"items":[{"word":"paene","structure":"paene (Latin adverb, 'almost')","meaning":"almost","meaningCN":"几乎；将近","example":"The prefix of meaning says the land is nearly an island.","exampleCN":"这个表示「几乎」的成分说明这块陆地差不多是岛。"},{"word":"insula","structure":"insula, insulae (f., first declension)","meaning":"island","meaningCN":"岛","example":"The noun half supplies the island image.","exampleCN":"名词那一半提供岛的意象。"},{"word":"peninsula","structure":"paene + insula","meaning":"almost an island","meaningCN":"几乎是岛","example":"A lighthouse stands at the tip of the peninsula.","exampleCN":"灯塔立在半岛尖端。"},{"word":"peninsular","structure":"peninsula + -ar (relating to)","meaning":"of a peninsula","meaningCN":"半岛的","example":"Peninsular roads follow the shore.","exampleCN":"半岛的道路沿着海岸走。"},{"word":"peninsularity","structure":"peninsular + -ity (state)","meaning":"the state of being peninsular","meaningCN":"半岛状态","example":"Peninsularity shaped the region's trade.","exampleCN":"半岛状态塑造了这个地区的贸易。"},{"word":"insular","structure":"insula + -ar (relating to)","meaning":"of an island; narrow","meaningCN":"岛屿的；狭隘的","example":"Insular habits kept the village closed.","exampleCN":"岛屿式的习惯让村子封闭。"},{"word":"isolate","structure":"insula + -ate (make separate)","meaning":"to set apart","meaningCN":"隔离；使孤立","example":"Floods can isolate the peninsula.","exampleCN":"洪水能把半岛与外界隔开。"},{"word":"peninsula effect","structure":"peninsula + effect (compound term)","meaning":"a biological pattern on peninsulas","meaningCN":"半岛效应","example":"The peninsula effect predicts fewer species at the tip.","exampleCN":"半岛效应预测越靠尖端物种越少。"}],"latinEntries":[{"word":"paene","structure":"paene (adverb)","meaning":"almost, nearly","meaningCN":"几乎；将近"},{"word":"insula","structure":"insula, insulae (f., first declension)","meaning":"island; block of buildings","meaningCN":"岛；街区"},{"word":"paeninsula","structure":"paeninsula, paeninsulae (f., first declension)","meaning":"almost an island","meaningCN":"几乎是岛；半岛"},{"word":"insularis","structure":"insularis, insulare (adj., third declension)","meaning":"of an island","meaningCN":"岛屿的"}]}},{"word":"island","ipa_uk":"/ˈaɪlənd/","ipa_us":"/ˈaɪlənd/","definition_zh":"岛；岛屿；岛状物；安全岛；孤立的区域","definition_en":"a piece of land completely surrounded by water, or something resembling such a piece","core_image":"一块四面环水的陆地，像被蓝色包围的一块绿色拼图","scene":"清晨的渡船朝那座小岛驶去。The morning ferry heads for the small island.","sceneCN":"这里该词指「四面环水的陆地」（第 1 个义项：被水完全包围的陆块）；句意为清晨的渡船朝那座小岛驶去。","pos":[{"tag":"n.","zh":"岛；岛屿；岛状物；安全岛"},{"tag":"vt.","zh":"使成岛；使孤立（较少用）"}],"collocations":[{"phrase":"a remote island","zh":"偏远的岛屿"},{"phrase":"a desert island","zh":"荒岛"},{"phrase":"an island nation","zh":"岛国"},{"phrase":"an island chain","zh":"岛链"},{"phrase":"on the island","zh":"在岛上"},{"phrase":"a traffic island","zh":"交通岛；安全岛"}],"forms":[{"label":"复数（名词）","form":"islands"},{"label":"名词（岛民）","form":"islander"},{"label":"名词（小岛）","form":"islet"},{"label":"名词（孤岛运行）","form":"islanding"}],"derivatives":[{"word":"islander","pos":"n.","zh":"岛民；岛上居民"},{"word":"islet","pos":"n.","zh":"小岛；小岛状组织"},{"word":"islanding","pos":"n.","zh":"孤岛化；电力孤岛运行"},{"word":"island-like","pos":"adj.","zh":"岛状的；孤立的"}],"senses":[{"no":"01","title":"Land surrounded by water","titleCN":"岛：四面环水的陆地","definition":"a piece of land completely surrounded by water","definitionCN":"完全被水包围的一块陆地","example":"The morning ferry heads for the small island.","exampleCN":"清晨的渡船朝那座小岛驶去。","why":"Old English joined a word for 'watery land' to land, so the oldest sense is land that stands in water.","whyCN":"古英语把表示「水边之地」的词与「陆地」组合，最古老的义项就是立在水中的陆地。"},{"no":"02","title":"A raised patch in a road","titleCN":"交通岛：道路中的安全岛","definition":"a raised area in a road that separates traffic or protects pedestrians","definitionCN":"道路中分隔车流或保护行人的隆起区域","example":"Wait on the island before crossing the second lane.","exampleCN":"过第二条车道前先在安全岛上等候。","why":"The shape is a small patch surrounded by traffic, so the land word was borrowed for road design.","whyCN":"它的形状是被车流包围的一小块，于是借用了表示陆地的词。"},{"no":"03","title":"A habitat cut off from others","titleCN":"生态孤岛：与其他栖息地隔离的生境","definition":"an area of habitat separated from similar areas by unsuitable land","definitionCN":"被不适合的土地隔开、与同类栖息地分离的区域","example":"The wood is an island of shade in open farmland.","exampleCN":"这片树林是开阔农田中的一块荫凉孤岛。","why":"Ecology uses the sea as a metaphor: unsuitable ground acts like water around a habitat.","whyCN":"生态学把海当作比喻：不适合的土地就像包围栖息地的水。"},{"no":"04","title":"A lonely or isolated position","titleCN":"比喻：孤立无援的处境","definition":"a situation in which someone feels cut off from other people","definitionCN":"某人感到与他人隔断的处境","example":"After the move he felt like an island in a strange city.","exampleCN":"搬来之后，他觉得自己像陌生城市里的一座孤岛。","why":"The physical isolation of land becomes a picture of social isolation.","whyCN":"陆地的物理隔绝变成社会隔绝的图景。"},{"no":"05","title":"An island culture or nation","titleCN":"岛屿文化或岛国","definition":"a society or country whose life is shaped by island geography","definitionCN":"生活受岛屿地理塑造的社会或国家","example":"The island has kept its own dialect for centuries.","exampleCN":"这座岛几百年来保留着自己的方言。","why":"Water around land also separates people, so island can name a culture as well as a place.","whyCN":"环岛之水也把人隔开，因此这个词既可指地方，也可指文化。"},{"no":"06","title":"A kitchen island","titleCN":"厨房中岛：独立的操作台","definition":"a free-standing worktop in the middle of a kitchen","definitionCN":"厨房中央独立设置的操作台","example":"The kitchen island holds the sink and the chopping board.","exampleCN":"厨房中岛放着水槽与砧板。","why":"A counter standing alone in a room looks like land standing alone in water, hence the household use.","whyCN":"独立站在房间里的台面就像立在水中一块陆地，于是有了这个家居用法。"},{"no":"07","title":"An island of tissue","titleCN":"解剖：组织中的胰岛","definition":"a small cluster of cells distinct from the tissue around it, as in the pancreas","definitionCN":"与周围组织不同的一小簇细胞，如胰腺中的","example":"The islets of the pancreas release insulin.","exampleCN":"胰腺中的小岛细胞释放胰岛素。","why":"Histology saw clusters of cells standing out like islands, and named them with the same word.","whyCN":"组织学看到一簇簇细胞像岛屿一样突出，便用同一个词命名。"},{"no":"08","title":"A detached platform","titleCN":"孤立的平台或设施","definition":"a structure standing apart from the shore or from other structures","definitionCN":"与岸边或其他结构分开站立的设施","example":"The drilling island stands in deep water.","exampleCN":"钻井平台立在深水中。","why":"Engineering extends the word to any structure that stands alone, whether in water or on land.","whyCN":"工程把这个词扩展到任何独立站立的设施，无论在水上还是陆上。"}],"etymology":{"intro":{"en":"Island comes from Old English, not from Latin. Its spelling was later altered by a mistaken link with Latin insula. Dates are approximate.","cn":"该词来自古英语，并非拉丁语；后来有人误把它与拉丁语表示「岛」的词联系起来，才改动拼写。年代均为约数。"},"items":[{"era":"OLD ENGLISH","en":"Old English iegland joined ieg 'island, watery land' and land 'land', giving the ancestor of the modern word.","cn":"古英语把一个表示「岛、水边之地」的词与「陆地」组合，形成现代词的祖先。"},{"era":"GERMANIC SOURCE","en":"The first element goes back to a Germanic word for something standing in water, related only distantly to Latin aqua.","cn":"前半部分可追溯到日耳曼语中表示「立于水中之物」的词，与拉丁语表示「水」的词只有很远的亲缘。"},{"era":"FALSE LATIN LINK","en":"In the sixteenth century the spelling gained an s by mistaken association with Latin insula and Old French isle; that s is not etymological.","cn":"十六世纪时，拼写因误与拉丁语「岛」及古法语同义词联系而多出一个字母，这个字母并非词源所有。"},{"era":"GENERAL EXTENSION","en":"The word spread from land in the sea to any isolated patch: a traffic island, a kitchen island, a habitat island.","cn":"这个词从海中陆地扩展到任何孤立的小块：交通岛、厨房中岛、栖息地孤岛。"},{"era":"SCIENTIFIC USES","en":"Medicine named cell clusters islets, and electrical engineering uses islanding for a grid running alone.","cn":"医学把细胞簇称为小岛，电气工程则用「孤岛运行」指独自运转的电网。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): Old English spellings vary, and the exact date of the added s is approximate.","cn":"来源不确定（首见年代）：古英语拼写有多种变体，多出字母的确切年代为约数。"}]},"similar":{"note":{"en":"Group one holds words that look close to island, including one false relative; group two holds other terms for land in water.","cn":"第一组是字形接近该词的词，其中有一个假同源；第二组是其他表示水中陆地的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"isle","ipa":"/aɪl/","tag":"poetic synonym","definition":"A literary word for an island, borrowed from Old French and Latin insula; it is not the source of island.","definitionCN":"指岛的文学用词，借自古法语与拉丁语；它并不是该词的来源。"},{"word":"islet","ipa":"/ˈaɪlət/","tag":"small island","definition":"A small island; it is formed from the old word plus a French diminutive ending.","definitionCN":"指小岛；由旧词加法语指小后缀构成。"},{"word":"insular","ipa":"/ˈɪnsjələ/","tag":"island-related","definition":"Relating to an island or a narrow outlook; it comes from Latin insula, not from the English word.","definitionCN":"指岛屿的或心胸狭隘的；来自拉丁语表示「岛」的词，而非英语本词。"},{"word":"peninsula","ipa":"/pəˈnɪnsjələ/","tag":"almost an island","definition":"Land almost surrounded by water; the key difference is that it still joins the mainland.","definitionCN":"指几乎被水包围的陆地；关键差别是它仍与大陆相连。"}]},{"heading":"NEAR MEANING","entries":[{"word":"islet","ipa":"/ˈaɪlət/","tag":"very small island","definition":"A very small island; it is the everyday narrow term beside the general word.","definitionCN":"指很小的岛；是通用词旁边的日常窄义词。"},{"word":"cay","ipa":"/keɪ/","tag":"low sandy island","definition":"A low island of sand or coral, often in tropical seas; it names the material and height as well.","definitionCN":"指由沙或珊瑚构成的低岛，多见于热带海域；还标出材质与高度。"},{"word":"atoll","ipa":"/əˈtɒl/","tag":"ring-shaped reef island","definition":"A ring of coral around a lagoon; the shape is a ring, not a single mass.","definitionCN":"指环抱潟湖的珊瑚环礁；其形状是环，不是单一陆块。"},{"word":"mainland","ipa":"/ˈmeɪnlænd/","tag":"the opposite","definition":"The main landmass of a country or region, as opposed to its islands; it is the natural contrast.","definitionCN":"指一国或地区的主要陆地，与岛屿相对；它是天然的对立面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Old English joined 'watery land' to 'land': land that stands in water.","cn":"古英语把「水边之地」与「陆地」组合：立在水中的陆地。"},{"en":"The s in the modern spelling is a later mistake borrowed from the Latin word for island.","cn":"现代拼写中的那个字母是后来误借拉丁语「岛」而多出来的。"},{"en":"The family runs island, islander, islet, islanding and island-like.","cn":"同族词包括本词、岛民、小岛、孤岛运行与岛状形容词。"},{"en":"Fixed phrases mark the senses: a remote island, an island nation, a traffic island, a kitchen island.","cn":"固定搭配标出各义项：偏远岛屿、岛国、交通岛、厨房中岛。"},{"en":"A habitat island is a patch of green cut off by farmland, just as an island is cut off by sea.","cn":"栖息地孤岛是被农田隔开的一块绿地，正如岛被海隔开。"}],"abstract":[{"en":"Picture one green stone left in a wide blue dish.","cn":"想象一只宽大的蓝盘里只剩一颗绿石。"},{"en":"Picture a kitchen counter standing alone in the middle of a room.","cn":"想象一张厨房台面独自立在房间中央。"},{"en":"Picture a person in a crowd who is surrounded by silence.","cn":"想象人群中的一个人被寂静包围。"}]},"examples":[{"en":"The island has no bridge, so everything arrives by boat.","cn":"这座岛没有桥，所有东西都靠船运到。"},{"en":"A raised island in the road lets pedestrians wait for a gap.","cn":"道路中的安全岛让行人等待车流空隙。"},{"en":"The forest island shelters birds that cannot cross the fields.","cn":"这片森林孤岛庇护着无法越过田野的鸟。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「爱懒的」：岛上的人爱懒散，四面是水不用出门。","word":"island"},"root":"古英语把表示「水边之地」的词与「陆地」组合而成；更深来源属日耳曼语。现代拼写多出的字母是十六世纪误与拉丁语「岛」联系所致，并非词源成分。","sensesIntro":{"en":"Eight senses follow one situation: something completely cut off by what surrounds it. The situation runs from land in the sea to a traffic island, a habitat patch, a lonely person, an island culture, a kitchen counter, a cell cluster and a detached platform.","cn":"八个义项沿同一种处境展开：某物被周围之物完全隔开。这种处境从海中陆地，延伸到交通岛、栖息地小片、孤独的人、岛屿文化、厨房台面、细胞簇与孤立平台。"},"semanticMap":{"core":{"en":"CORE IMAGE: a piece of land standing alone in water, with no road to the shore.","cn":"核心意象：一块独自立在水中的陆地，没有路通向岸边。"},"chain":["LAND IN WATER","RAISED PATCH","CUT-OFF HABITAT","LONELY POSITION","ISLAND CULTURE","DETACHED STRUCTURE"],"branches":[{"senses":"S1 · S5","en":"LAND AND PEOPLE: water around land separates a place and can shape a culture.","cn":"陆地与人：环岛之水隔开一个地方，也能塑造一种文化。"},{"senses":"S2 · S6 · S8","en":"DETACHED THINGS: a road patch, a kitchen counter and a platform all stand alone.","cn":"孤立之物：道路小块、厨房台面与平台都是独自站立的。"},{"senses":"S3","en":"HABITAT: unsuitable land works like sea around a patch of green.","cn":"栖息地：不适合的土地就像包围绿地的海。"},{"senses":"S4","en":"FEELING: physical isolation becomes a picture of loneliness.","cn":"感受：物理隔绝变成孤独的图景。"},{"senses":"S7","en":"TISSUE: cell clusters stand out from their surroundings like islands.","cn":"组织：细胞簇像岛屿一样从周围突出。"}]},"affixes":{"intro":{"en":"Island is an Old English compound, not a Latin derivative; its two halves are old Germanic words, and the modern spelling was later reshaped.","cn":"该词是古英语复合词，并非拉丁派生词；两半都是古老的日耳曼语词，现代拼写后来被改动过。"},"latinIntro":{"en":"There is no true Latin element: the Latin word for island influenced the spelling but is not an ancestor, so the Latin entry list is empty.","cn":"这里没有真正的拉丁成分：拉丁语表示「岛」的词只影响了拼写，并非祖先，因此拉丁词条列表留空。"},"items":[{"word":"ieg","structure":"Old English ieg (noun, 'island, watery land')","meaning":"watery land","meaningCN":"水边之地","example":"The old element named land standing in water.","exampleCN":"这个古老成分指立在水中的陆地。"},{"word":"land","structure":"Old English land (noun, 'ground, territory')","meaning":"land","meaningCN":"陆地","example":"The second half supplies the ground itself.","exampleCN":"后半部分提供陆地本身。"},{"word":"island","structure":"ieg + land (Old English compound)","meaning":"land in water","meaningCN":"水中的陆地","example":"The morning ferry heads for the small island.","exampleCN":"清晨的渡船朝小岛驶去。"},{"word":"islands","structure":"island + -s (plural)","meaning":"more than one island","meaningCN":"多个岛屿","example":"The bay holds three small islands.","exampleCN":"这个湾里有三座小岛。"},{"word":"islander","structure":"island + -er (person)","meaning":"a person who lives on an island","meaningCN":"岛民","example":"The islander knows every reef.","exampleCN":"这位岛民熟悉每一处暗礁。"},{"word":"islet","structure":"old island word + -et (French diminutive)","meaning":"a small island","meaningCN":"小岛","example":"A rocky islet marks the channel.","exampleCN":"一座岩石小岛标出航道。"},{"word":"islanding","structure":"island + -ing (action or state)","meaning":"running as an isolated unit","meaningCN":"孤岛运行；孤岛化","example":"Islanding protects the local grid during a fault.","exampleCN":"孤岛运行在故障时保护本地电网。"},{"word":"island platform","structure":"island + platform (compound)","meaning":"a detached working platform","meaningCN":"孤立平台","example":"The island platform serves both tracks.","exampleCN":"这座岛式站台服务两条轨道。"}],"latinEntries":[]}},{"word":"archipelago","ipa_uk":"/ˌɑːkɪˈpeləɡəʊ/","ipa_us":"/ˌɑːrkɪˈpeləɡoʊ/","definition_zh":"群岛；群岛海域；群岛国家；岛弧","definition_en":"a group or chain of many islands in a sea","core_image":"海面上散布着一串大大小小的岛屿，像撒开的一把石子","scene":"那片群岛横卧在一片宽阔的海域上。The archipelago lies across a wide expanse of sea.","sceneCN":"这里该词指「成串分布的群岛」（第 1 个义项：一群岛屿）；句意为这片群岛横卧在一片宽阔的海域上。","pos":[{"tag":"n.","zh":"群岛；群岛海域；群岛国家"}],"collocations":[{"phrase":"a volcanic archipelago","zh":"火山群岛"},{"phrase":"a scattered archipelago","zh":"散布的群岛"},{"phrase":"archipelago waters","zh":"群岛水域"},{"phrase":"an archipelago nation","zh":"群岛国家"},{"phrase":"the Aegean archipelago","zh":"爱琴海群岛"},{"phrase":"a tropical archipelago","zh":"热带群岛"}],"forms":[{"label":"复数（常规形式）","form":"archipelagos"},{"label":"复数（变体形式）","form":"archipelagoes"},{"label":"形容词（群岛的）","form":"archipelagic"},{"label":"复合名词（群岛水域）","form":"archipelagic waters"}],"derivatives":[{"word":"archipelagic","pos":"adj.","zh":"群岛的；群岛水域的"},{"word":"archipelagic waters","pos":"n.","zh":"群岛水域"},{"word":"archipelago state","pos":"n.","zh":"群岛国家"}],"senses":[{"no":"01","title":"A group of many islands","titleCN":"群岛：成组分布的许多岛屿","definition":"a group or chain of many islands","definitionCN":"成组或成链分布的许多岛屿","example":"The archipelago lies across a wide expanse of sea.","exampleCN":"这片群岛横卧在一片宽阔的海域上。","why":"Greek named the Aegean 'the chief sea', and the islands within it took the name of the sea itself.","whyCN":"希腊语把爱琴海称为「首要之海」，海中的岛屿便随海名而得名。"},{"no":"02","title":"The sea around a group of islands","titleCN":"群岛海域","definition":"the sea area in which a group of islands lies","definitionCN":"群岛所在的那片海域","example":"Storms often cross the archipelago in autumn.","exampleCN":"秋天风暴常穿过这片群岛海域。","why":"The name first belonged to the sea, so the water around the islands kept the same word.","whyCN":"这个名字最初属于海，因此环岛的水域沿用了同一个词。"},{"no":"03","title":"An island country","titleCN":"群岛国家","definition":"a state made up of many islands","definitionCN":"由许多岛屿组成的国家","example":"The archipelago governs more than seven hundred islands.","exampleCN":"这个群岛国家管辖七百多座岛屿。","why":"A group of islands can become one political unit, so the geographic word serves as a state label.","whyCN":"一群岛屿可以成为一个政治单元，因此地理词也用作国家称谓。"},{"no":"04","title":"An island arc in geology","titleCN":"地质学中的岛弧","definition":"a curved line of volcanic islands above a subducting plate","definitionCN":"位于俯冲板块之上的弧形火山岛链","example":"The archipelago marks where one plate sinks beneath another.","exampleCN":"这片群岛标出一块板块俯冲到另一块之下的位置。","why":"Geology explains the chain as an arc above a sinking plate, which gives the group its shape.","whyCN":"地质学把这条链解释为俯冲板块上方的弧，岛群的形状由此而来。"},{"no":"05","title":"A cluster of separate things","titleCN":"比喻：分散却成组的一簇事物","definition":"a set of similar things scattered across a space but seen as a group","definitionCN":"散布在一片空间、却被视为一组的一批同类事物","example":"A small archipelago of research stations circles the polar sea.","exampleCN":"一小群研究站环绕着极地海域。","why":"Separate islands with water between them are a natural picture for scattered but related units.","whyCN":"被水分开的岛屿，正是分散却相关之单位的天然图景。"},{"no":"06","title":"An island biogeographic unit","titleCN":"群岛生态与生物地理单元","definition":"the islands of a group considered together as a living environment","definitionCN":"把一群岛屿作为一个生存环境来看待","example":"The archipelago supports species found nowhere else.","exampleCN":"这片群岛养育着别处没有的物种。","why":"Isolation on each island drives evolution, so the group acts as one natural laboratory.","whyCN":"每座岛的隔离推动演化，因此整个岛群像一个天然实验室。"},{"no":"07","title":"Waters used for navigation","titleCN":"群岛间的航道与水域","definition":"the channels and waters among a group of islands, used by ships","definitionCN":"岛群之间供船只使用的海峡与水域","example":"Pilots learn the archipelago before they take a large ship through.","exampleCN":"引航员先熟悉这片群岛水域，才带大船通过。","why":"Between the islands lie many narrow passages, so the group also names a navigational zone.","whyCN":"岛屿之间有许多狭窄水道，因此岛群也指一片航行区域。"},{"no":"08","title":"A named sea and its islands","titleCN":"专名中的群岛海域","definition":"a proper name for a particular sea together with its islands","definitionCN":"某一特定海域连同其岛屿的专名","example":"Sailors still speak of the old archipelago by its Greek name.","exampleCN":"水手仍用古老的希腊名称称呼那片群岛。","why":"The word began as the name of one sea, and proper names preserve that origin.","whyCN":"这个词最初是一片海的名字，专名保留了这一来源。"}],"etymology":{"intro":{"en":"Archipelago is Greek: arkhi- 'chief' plus pelagos 'sea', first naming the Aegean. It came to English through Italian. Dates are approximate.","cn":"该词是希腊语复合词：表示「首要」的成分加表示「海」的成分，最初指爱琴海，经意大利语进入英语。年代均为约数。"},"items":[{"era":"GREEK ARKHI-","en":"arkhi- meant 'chief, first' and also opens English words such as archbishop and architect.","cn":"这个希腊语成分意为「首要、第一」，也出现在表示大主教与建筑师的英语词开头。"},{"era":"GREEK PELAGOS","en":"pelagos meant 'open sea', and it survives in English pelagic 'of the open sea'.","cn":"这个希腊语词意为「开阔的海」，在英语表示「远洋的」形容词中留有痕迹。"},{"era":"THE AEGEAN","en":"The phrase first named the Aegean as the chief sea, and the islands in it were called by the same name.","cn":"这一短语最初把爱琴海称为首要之海，海中的岛屿也随之得名。"},{"era":"ITALIAN AND ENGLISH","en":"Italian applied the name to other island groups, and English borrowed it in the sixteenth century.","cn":"意大利语把这个名称用于其他岛群，英语在十六世纪借入。"},{"era":"MODERN SCIENCE","en":"Geology and biology added island arc and archipelagic waters to the older geographic sense.","cn":"地质学与生物学在旧地理义之外增加了岛弧与群岛水域等说法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation is approximate, and the transfer from the Aegean to other groups is not dated exactly.","cn":"来源不确定（首见年代）：英语最早书证为约数，从爱琴海移用到其他岛群的确切年代也无定论。"}]},"similar":{"note":{"en":"Group one holds look-alike words from the same Greek sea-root; group two holds the geographic terms that overlap with a group of islands.","cn":"第一组是形近、同出希腊「海」词根的词；第二组是与群岛语义重叠的地理术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"archipelagic","ipa":"/ˌɑːkɪpəˈlædʒɪk/","tag":"adjective form","definition":"Relating to an archipelago; it is the adjective while the noun names the group.","definitionCN":"指与群岛有关的；它是形容词，而名词指群岛本身。"},{"word":"pelagic","ipa":"/pəˈlædʒɪk/","tag":"open-sea","definition":"Living in or relating to the open sea; it uses the same sea-root without the 'chief' prefix.","definitionCN":"指生活在开阔海或与之有关的；它使用同一个「海」词根，但没有「首要」前缀。"},{"word":"arch","ipa":"/ɑːtʃ/","tag":"prefix or curve","definition":"A curved structure, or a prefix meaning 'chief'; the prefix is the same element that opens archipelago.","definitionCN":"指拱形结构，或表示「首要」的前缀；这个前缀正是该词开头的成分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"island chain","ipa":"/ˈaɪlənd tʃeɪn/","tag":"linear group","definition":"A line of islands, especially one formed by the same process; it stresses the line rather than the sea.","definitionCN":"指排成一线的一串岛屿，尤指由同一过程形成者；强调线状而非海域。"},{"word":"island group","ipa":"/ˈaɪlənd ɡruːp/","tag":"general term","definition":"Any set of islands considered together; it is plainer than the Greek word.","definitionCN":"指任何被视为一组的岛屿；比这个希腊词更平实。"},{"word":"atoll","ipa":"/əˈtɒl/","tag":"ring reef","definition":"A ring of coral islands around a lagoon; it is one kind of island group, not a general name.","definitionCN":"指环抱潟湖的珊瑚岛环；它是岛群的一种，不是通称。"},{"word":"islet cluster","ipa":"/ˈaɪlət ˈklʌstə/","tag":"small islands","definition":"A close group of very small islands; it stresses small size rather than number or sea.","definitionCN":"指紧靠在一起的一群很小的岛；强调尺寸小，而非数量或海域。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"'Chief sea' is the literal sense: the Aegean was the sea that gave the whole group its name.","cn":"字面义是「首要之海」：爱琴海就是给整个岛群命名的海。"},{"en":"The family runs archipelago, archipelagic, archipelagic waters and archipelago state.","cn":"同族词包括本词、群岛形容词、群岛水域与群岛国家。"},{"en":"Fixed phrases mark the senses: a volcanic archipelago, archipelago waters, an archipelago nation.","cn":"固定搭配标出各义项：火山群岛、群岛水域、群岛国家。"},{"en":"The sea-root also survives in pelagic, which means 'of the open sea'.","cn":"这个「海」词根还保留在表示「远洋的」形容词中。"},{"en":"Geology reads the chain as an island arc above a sinking plate.","cn":"地质学把这条岛链读作俯冲板块上方的岛弧。"}],"abstract":[{"en":"Picture a handful of pebbles thrown across a wide blue cloth.","cn":"想象一把石子撒在一块宽大的蓝布上。"},{"en":"Picture a few bright shops separated by empty streets but known as one district.","cn":"想象几家明亮的店铺被空街隔开，却同属一个街区。"},{"en":"Picture stars scattered across a dark sea and counted as one constellation.","cn":"想象星星散布在暗色海面上，却被算作一个星座。"}]},"examples":[{"en":"The archipelago is home to birds that never reach the mainland.","cn":"这片群岛是那些从不飞到大陆的鸟的家园。"},{"en":"A ferry links the five main islands of the archipelago.","cn":"一艘渡船连接着群岛中的五座主要岛屿。"},{"en":"The archipelago lies on the line where two plates meet.","cn":"这片群岛位于两块板块相接的线上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「阿基佩拉戈」：阿基把一把石子撒进海里，成了群岛。","word":"archipelago"},"root":"希腊语 arkhi-（首要）+ pelagos（海）构成，字面义「首要之海」，最初指爱琴海及其岛屿，经意大利语进入英语。","sensesIntro":{"en":"Eight senses follow one group: many islands seen together with the sea between them. The group is then read as a sea area, a nation, a geological arc, a scattered cluster, a living unit, a navigational zone and a proper name.","cn":"八个义项沿同一个群体展开：许多岛屿连同其间的海一起看。这个群体随后被读作海域、国家、地质岛弧、分散的一簇、生存单元、航行区域与专名。"},"semanticMap":{"core":{"en":"CORE IMAGE: a chain of stones scattered across a blue surface, each separated yet read as one pattern.","cn":"核心意象：一串石子散布在蓝色表面上，彼此分开却读成一个图案。"},"chain":["GROUP OF ISLANDS","ISLAND SEA","ISLAND STATE","ISLAND ARC","SCATTERED CLUSTER","NAMED SEA"],"branches":[{"senses":"S1 · S2 · S8","en":"SEA AND ISLANDS: the group and the water around it share one name from the start.","cn":"海与岛：岛群与环岛之水从一开始就共享一个名字。"},{"senses":"S3","en":"POLITICS: many islands can become one state.","cn":"政治：许多岛屿可以成为一个国家。"},{"senses":"S4 · S5","en":"PATTERN: an arc of volcanoes and a scatter of stations both read as a group.","cn":"图案：火山弧与分散的研究站都被读成一组。"},{"senses":"S6","en":"LIFE: isolation on each island turns the group into a laboratory of evolution.","cn":"生命：每座岛的隔离把整个岛群变成演化实验室。"},{"senses":"S7","en":"NAVIGATION: the passages between islands form a zone sailors must learn.","cn":"航行：岛间水道构成一片水手必须熟悉的区域。"}]},"affixes":{"intro":{"en":"Archipelago is a Greek compound of two combining elements, with no Latin root; both elements also appear in other English words.","cn":"该词是两个希腊语组合成分构成的复合词，没有拉丁词根；两个成分也出现在其他英语词中。"},"latinIntro":{"en":"There is no Latin element: the word is Greek and reached English through Italian, so the Latin entry list is empty.","cn":"这里没有拉丁成分：该词是希腊语，经意大利语进入英语，因此拉丁词条列表留空。"},"items":[{"word":"arkhi-","structure":"Greek arkhi- (combining form, 'chief, first')","meaning":"chief; first","meaningCN":"首要；第一","example":"The element also opens words for a chief bishop and a master builder.","exampleCN":"这个成分也出现在表示大主教与建筑大师的词开头。"},{"word":"pelagos","structure":"Greek pelagos (noun, 'open sea')","meaning":"open sea","meaningCN":"开阔的海","example":"The sea element survives in the adjective for open-sea life.","exampleCN":"这个「海」成分保留在表示远洋生物的形容词中。"},{"word":"archipelago","structure":"arkhi- + pelagos","meaning":"chief sea; a group of islands","meaningCN":"首要之海；群岛","example":"The archipelago lies across a wide expanse of sea.","exampleCN":"这片群岛横卧在宽阔海域上。"},{"word":"archipelagos","structure":"archipelago + -s (plural)","meaning":"more than one archipelago","meaningCN":"多个群岛","example":"Two archipelagos face each other across the strait.","exampleCN":"两个群岛隔海峡相望。"},{"word":"archipelagic","structure":"archipelago + -ic (relating to)","meaning":"of an archipelago","meaningCN":"群岛的","example":"Archipelagic waters fall under a special legal rule.","exampleCN":"群岛水域适用特殊的法律规则。"},{"word":"archipelagic waters","structure":"archipelagic + waters (legal term)","meaning":"waters within an island group","meaningCN":"群岛水域","example":"The treaty protects archipelagic waters.","exampleCN":"条约保护群岛水域。"},{"word":"archipelago state","structure":"archipelago + state (compound)","meaning":"a country of islands","meaningCN":"群岛国家","example":"The archipelago state runs its own ferries.","exampleCN":"这个群岛国家经营自己的渡船。"},{"word":"island arc","structure":"island + arc (geological term)","meaning":"a curved chain of volcanic islands","meaningCN":"岛弧","example":"The island arc parallels the trench.","exampleCN":"岛弧与海沟平行。"}],"latinEntries":[]}},{"word":"isthmus","ipa_uk":"/ˈɪsməs/","ipa_us":"/ˈɪsməs/","definition_zh":"地峡；峡部；狭窄的连接通道","definition_en":"a narrow strip of land joining two larger areas of land, with water on both sides","core_image":"两块大陆之间一条窄窄的陆桥，两侧都是海","scene":"一条运河横穿地峡。A canal cuts across the isthmus.","sceneCN":"这里该词指「连接两块陆地的狭长地带」（第 1 个义项：两侧临水的陆桥）；句意为一条运河横穿地峡。","pos":[{"tag":"n.","zh":"地峡；峡部；狭窄通道"}],"collocations":[{"phrase":"the Isthmus of Panama","zh":"巴拿马地峡"},{"phrase":"a narrow isthmus","zh":"狭窄的地峡"},{"phrase":"across the isthmus","zh":"横穿地峡"},{"phrase":"an isthmus canal","zh":"地峡运河"},{"phrase":"the Corinthian isthmus","zh":"科林斯地峡"},{"phrase":"an isthmus between two seas","zh":"两海之间的地峡"}],"forms":[{"label":"复数（名词）","form":"isthmuses"},{"label":"形容词（地峡的）","form":"isthmian"},{"label":"形容词（峡部的）","form":"isthmic"}],"derivatives":[{"word":"isthmian","pos":"adj.","zh":"地峡的；科林斯地峡的"},{"word":"isthmic","pos":"adj.","zh":"峡部的；地峡的"},{"word":"isthmus canal","pos":"n.","zh":"地峡运河"},{"word":"isthmus neck","pos":"n.","zh":"地峡颈部"}],"senses":[{"no":"01","title":"A narrow neck of land","titleCN":"地峡：连接两块陆地的狭长地带","definition":"a narrow strip of land with water on both sides that joins two larger land areas","definitionCN":"两侧临水、连接两块较大陆地的狭长地带","example":"A canal cuts across the isthmus.","exampleCN":"一条运河横穿地峡。","why":"Greek isthmos named a narrow passage, first the neck at Corinth, where land is the passage between two seas.","whyCN":"希腊语原指狭窄通道，最初是科林斯的地颈，那里陆地成了两海之间的通道。"},{"no":"02","title":"The isthmus zone","titleCN":"地峡地带","definition":"the whole strip of land and its immediate surroundings","definitionCN":"整条陆地狭带及其周边","example":"Roads and railways crowd the isthmus zone.","exampleCN":"公路与铁路挤满了地峡地带。","why":"Planners treat more than the neck itself as a zone because traffic concentrates there.","whyCN":"规划者把地颈以外的一带也算作区域，因为交通在此集中。"},{"no":"03","title":"A narrow part in anatomy","titleCN":"解剖：峡部","definition":"a narrow passage joining two larger parts of an organ","definitionCN":"连接器官两个较大部分之间的狭窄通道","example":"The auditory isthmus links the middle ear to the throat.","exampleCN":"耳峡把中耳与咽部连接起来。","why":"Anatomy borrowed the land image for any narrow joining passage in the body.","whyCN":"解剖学借用了陆地意象，指身体内任何狭窄的连接通道。"},{"no":"04","title":"A narrow link between fields","titleCN":"比喻：两个领域之间的窄连接","definition":"a narrow connection between two otherwise separate fields or systems","definitionCN":"两个原本分离的领域或系统之间的狭窄连接","example":"A single road is the isthmus between the two towns.","exampleCN":"一条路就是两镇之间的地峡。","why":"Any narrow link carrying traffic between two bodies can be pictured as an isthmus.","whyCN":"任何在两个主体之间输送往来的狭窄连接，都能被想象成地峡。"},{"no":"05","title":"A canal across an isthmus","titleCN":"横穿地峡的运河","definition":"a waterway cut through an isthmus to join the seas on either side","definitionCN":"穿过地峡、连接两侧海域的水道","example":"The isthmus canal shortened the voyage by weeks.","exampleCN":"这条地峡运河把航程缩短了几周。","why":"An isthmus blocks ships, so cutting it turns land passage into water passage.","whyCN":"地峡阻挡船只，切开它就把它从陆上通道变成水上通道。"},{"no":"06","title":"A strategic choke point","titleCN":"战略咽喉","definition":"a narrow land passage of military or commercial importance","definitionCN":"具有军事或商业重要性的狭窄陆上通道","example":"Armies fought for control of the isthmus.","exampleCN":"军队争夺这条地峡的控制权。","why":"Because everything must pass through the neck, control of it controls movement.","whyCN":"因为一切都要经过这条地颈，控制它就控制了往来。"},{"no":"07","title":"A land bridge in geography","titleCN":"地理学中的陆桥","definition":"a broad land connection between continents, especially in the geological past","definitionCN":"大陆之间宽阔的陆地连接，尤指地质历史上的","example":"The isthmus once let animals cross between the continents.","exampleCN":"这条地峡曾让动物在两块大陆之间通行。","why":"A land bridge is the larger, historical version of an isthmus; scale and time separate the terms.","whyCN":"陆桥是地峡更大、更具历史尺度的版本；规模与时间区分二者。"},{"no":"08","title":"How an isthmus forms","titleCN":"地峡的形成过程","definition":"a land connection built by sediment or by the meeting of two shores","definitionCN":"由沉积物堆积或两岸相接而形成的陆地连接","example":"Sand built the isthmus that now joins the island.","exampleCN":"沙子堆积成地峡，如今把岛与大陆连在一起。","why":"Currents and sediment can close a gap, which is one physical way an isthmus appears.","whyCN":"水流与沉积物能填满缺口，这是地峡出现的物理方式之一。"}],"etymology":{"intro":{"en":"Isthmus comes from Greek isthmos, a narrow passage, first used of the neck at Corinth. Its deeper origin is uncertain. Dates are approximate.","cn":"该词来自希腊语，意为狭窄通道，最初用于科林斯地颈。其更深来源并不确定。年代均为约数。"},"items":[{"era":"GREEK ISTHMOS","en":"isthmos meant 'narrow passage, neck of land', and it first named the Corinthian isthmus.","cn":"希腊语词意为「狭窄通道、地颈」，最初指科林斯地峡。"},{"era":"UNCERTAIN ROOT","en":"Its deeper origin is uncertain: one suggestion links it to a verb 'to go', another to 'to stand', and neither is proved.","cn":"其更深来源不确定：有人把它与表示「走」的动词联系，也有人与表示「站立」的词联系，两种说法都未获证明。"},{"era":"LATIN BORROWING","en":"Latin borrowed the Greek word as isthmus without changing its meaning, so the Latin form is a loan, not a native root.","cn":"拉丁语原样借入这个希腊词，意义未变，因此拉丁形式是借词，不是本族词根。"},{"era":"ENGLISH","en":"English took the Latin form in the sixteenth century and applied it to narrow land bridges elsewhere.","cn":"英语在十六世纪借入拉丁形式，并把它用于其他地方的狭窄陆桥。"},{"era":"ANATOMY","en":"The same narrow-passage image was applied to organs, giving the anatomical sense of a narrow joining part.","cn":"同一「狭窄通道」意象被用于器官，产生解剖学中狭窄连接部分的义项。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (origin): several hypotheses exist and no single root is agreed; the first English date is approximate.","cn":"来源不确定（词根）：存在多种假说，学界未就单一词根达成一致；英语首见年代为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike forms of the same Greek word; group two holds the geographic terms most often confused with an isthmus.","cn":"第一组是同一个希腊词的形近形式；第二组是最容易与地峡混淆的地理术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"isthmian","ipa":"/ˈɪsmiən/","tag":"adjective form","definition":"Relating to an isthmus, especially the Corinthian one; it is the adjective while the noun names the land.","definitionCN":"指与地峡有关的，尤指科林斯地峡；它是形容词，而名词指陆地。"},{"word":"isthmic","ipa":"/ˈɪsmɪk/","tag":"narrow-part adjective","definition":"Relating to a narrow joining part, especially in anatomy; it is the technical adjective.","definitionCN":"指与狭窄连接部分有关的，尤用于解剖；它是技术形容词。"},{"word":"asthma","ipa":"/ˈæstmə/","tag":"breathing illness","definition":"A condition of difficult breathing; it shares some letters and sounds but has a different Greek origin.","definitionCN":"指呼吸困难的疾病；部分字母与读音相同，但希腊来源不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"land bridge","ipa":"/ˈlænd brɪdʒ/","tag":"broad connection","definition":"A wide land connection between continents, often of the geological past; an isthmus is narrower and present-day.","definitionCN":"指大陆之间宽阔的陆地连接，常属地质历史；地峡更窄且多为现今存在。"},{"word":"neck","ipa":"/nek/","tag":"narrow part","definition":"The narrow part joining a head to a body, or any narrow joining part; it is the plain everyday word.","definitionCN":"指连接头与身体的狭窄部分，或任何狭窄连接处；它是平实的日常词。"},{"word":"strait","ipa":"/streɪt/","tag":"water passage","definition":"A narrow passage of water between two lands; it is the water counterpart of an isthmus.","definitionCN":"指两片陆地之间的狭窄水道；它是地峡的水上对应物。"},{"word":"peninsula","ipa":"/pəˈnɪnsjələ/","tag":"land nearly surrounded","definition":"Land almost surrounded by water; it projects rather than joins two masses.","definitionCN":"指几乎被水包围的陆地；它是向外突出，而非连接两块陆地。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The original sense is 'narrow passage', and land is the passage between two seas.","cn":"原义是「狭窄通道」，而陆地就是两海之间的通道。"},{"en":"The family runs isthmus, isthmian, isthmic, isthmus canal and isthmus neck.","cn":"同族词包括本词、地峡形容词、峡部形容词、地峡运河与地峡颈部。"},{"en":"Fixed phrases mark the senses: the Isthmus of Panama, a narrow isthmus, an isthmus canal.","cn":"固定搭配标出各义项：巴拿马地峡、狭窄地峡、地峡运河。"},{"en":"The contrast to remember is simple: an isthmus is land between waters, a strait is water between lands.","cn":"要记住的对比很简单：地峡是水之间的陆地，海峡是陆地之间的水。"},{"en":"Anatomy uses the same image for any narrow joining part of an organ.","cn":"解剖学用同一意象指器官内任何狭窄的连接部分。"}],"abstract":[{"en":"Picture a thin bridge of stone joining two wide rooms.","cn":"想象一条窄窄的石桥连着两个宽房间。"},{"en":"Picture a short corridor that is the only way between two halls.","cn":"想象一条短走廊，是两座大厅之间唯一的通道。"},{"en":"Picture a narrow waist joining two larger parts of a body.","cn":"想象一条窄腰连接身体两个较宽的部分。"}]},"examples":[{"en":"The isthmus is only a few kilometres wide at its narrowest point.","cn":"这条地峡最窄处只有几公里宽。"},{"en":"Traffic between the two seas must cross the isthmus by rail.","cn":"两海之间的往来必须靠铁路穿过地峡。"},{"en":"The isthmus of the thyroid joins its two lobes.","cn":"甲状腺峡部连接它的两个叶。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「一死没死」：地峡窄得只剩一条路，人挤着也要过去。","word":"isthmus"},"root":"希腊语 isthmos「狭窄通道、地颈」，最初指科林斯地峡；更深词根存疑，主要有「走」与「站立」两种未证实假说。拉丁语只是借入，英语 isthmus。","sensesIntro":{"en":"Eight senses follow one narrow link: land joining two larger masses across water. The link is then widened into a zone, narrowed to an organ, used as a metaphor, cut by a canal, fought over, compared with a land bridge and explained as a formation.","cn":"八个义项沿同一条狭窄连接展开：陆地跨水连接两块较大陆地。这条连接随后被扩成地带、收窄到器官、用作比喻、被运河切开、成为争夺对象、与陆桥比较，并被解释为一种形成过程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a narrow land bridge with sea on both sides, the only dry route between two masses.","cn":"核心意象：两侧是海的狭长陆桥，是两块陆地之间唯一的旱路。"},"chain":["NARROW LAND LINK","ISTHMUS ZONE","ANATOMICAL NECK","METAPHORICAL LINK","CANAL CUT","STRATEGIC CHOKE"],"branches":[{"senses":"S1 · S7","en":"THE LINK: a present-day neck and a prehistoric land bridge are the same idea at different scales.","cn":"连接：现今地颈与史前陆桥是同一观念的不同尺度。"},{"senses":"S2 · S8","en":"THE ZONE: traffic and sediment both gather around the narrow strip.","cn":"地带：交通与沉积物都聚集在这条狭带上。"},{"senses":"S3","en":"THE BODY: anatomy borrows the image for any narrow joining part.","cn":"身体：解剖学借这个意象指任何狭窄连接部分。"},{"senses":"S4 · S6","en":"CONTROL: a narrow link funnels movement, which makes it strategic.","cn":"控制：狭窄连接把往来集中起来，因此具有战略意义。"},{"senses":"S5","en":"THE CUT: a canal turns the land link into a water route.","cn":"切开：运河把陆地连接变成水上通道。"}]},"affixes":{"intro":{"en":"Isthmus is a Greek loan with almost no productive English morphology; its family is small and technical.","cn":"该词是希腊语借词，在英语中几乎不产生新词，词族小而偏技术。"},"latinIntro":{"en":"Latin only borrowed the Greek word, so there is no Latin root family and the Latin entry list is empty.","cn":"拉丁语只是借入这个希腊词，没有拉丁词根词族，因此拉丁词条列表留空。"},"items":[{"word":"isthmos","structure":"Greek isthmos (noun, 'narrow passage')","meaning":"narrow passage","meaningCN":"狭窄通道","example":"The Greek word first named the Corinthian neck.","exampleCN":"这个希腊词最初指科林斯地颈。"},{"word":"isthmus","structure":"Greek isthmos -> Latin isthmus","meaning":"a narrow land link","meaningCN":"狭窄的陆地连接","example":"A canal cuts across the isthmus.","exampleCN":"一条运河横穿地峡。"},{"word":"isthmuses","structure":"isthmus + -es (plural)","meaning":"more than one isthmus","meaningCN":"多个地峡","example":"Two isthmuses join the island to the coast.","exampleCN":"两条地峡把岛与海岸连接起来。"},{"word":"isthmian","structure":"isthmus + -ian (relating to)","meaning":"of an isthmus","meaningCN":"地峡的","example":"The Isthmian games were held at Corinth.","exampleCN":"地峡运动会曾在科林斯举行。"},{"word":"isthmic","structure":"isthmus + -ic (relating to)","meaning":"of a narrow part","meaningCN":"峡部的","example":"The isthmic region is the narrowest point.","exampleCN":"峡部区域是最窄的地方。"},{"word":"isthmus canal","structure":"isthmus + canal (compound)","meaning":"a canal through an isthmus","meaningCN":"地峡运河","example":"The isthmus canal opened in 1914.","exampleCN":"这条地峡运河于一九一四年通航。"},{"word":"isthmus neck","structure":"isthmus + neck (compound)","meaning":"the narrowest part of an isthmus","meaningCN":"地峡颈部","example":"The road crosses the isthmus neck.","exampleCN":"道路穿过地峡颈部。"},{"word":"Isthmus of Panama","structure":"proper name (geographic)","meaning":"the isthmus joining North and South America","meaningCN":"巴拿马地峡","example":"The Isthmus of Panama links two continents.","exampleCN":"巴拿马地峡连接两块大陆。"}],"latinEntries":[]}},{"word":"strait","ipa_uk":"/streɪt/","ipa_us":"/streɪt/","definition_zh":"海峡；水道；困境；狭窄的；严格的","definition_en":"a narrow passage of water between two larger bodies of water, or a difficult situation","core_image":"两片陆地之间一条狭窄的水道，船只能一艘接一艘通过","scene":"渡船每小时穿过一次海峡。Ferries cross the strait every hour.","sceneCN":"这里该词指「连接两片海域的狭窄水道」（第 1 个义项：海峡）；句意为渡船每小时穿过一次海峡。","pos":[{"tag":"n.","zh":"海峡；水道；（复数）困境"},{"tag":"adj.","zh":"狭窄的；严格的（现多用于固定搭配）"}],"collocations":[{"phrase":"the Strait of Gibraltar","zh":"直布罗陀海峡"},{"phrase":"a narrow strait","zh":"狭窄的海峡"},{"phrase":"cross the strait","zh":"穿过海峡"},{"phrase":"dire straits","zh":"困境；窘境"},{"phrase":"the straits of","zh":"……海峡"},{"phrase":"strait-laced","zh":"拘谨的；古板的"}],"forms":[{"label":"复数（名词）","form":"straits"},{"label":"形容词（拮据的）","form":"straitened"},{"label":"形容词（拘谨的）","form":"strait-laced"},{"label":"名词（拘束衣）","form":"straitjacket"}],"derivatives":[{"word":"straits","pos":"n.","zh":"困境；窘境"},{"word":"straitened","pos":"adj.","zh":"拮据的；窘迫的"},{"word":"strait-laced","pos":"adj.","zh":"拘谨的；古板的"},{"word":"straitjacket","pos":"n.","zh":"拘束衣；束缚"}],"senses":[{"no":"01","title":"A narrow sea passage","titleCN":"海峡：两片陆地间的狭窄水道","definition":"a narrow passage of water joining two larger bodies of water","definitionCN":"连接两片较大海域的狭窄水道","example":"Ferries cross the strait every hour.","exampleCN":"渡船每小时穿过一次海峡。","why":"The word first meant 'narrow' or 'tight', and a narrow passage of sea is simply that narrowness applied to water.","whyCN":"这个词最初意为「狭窄、紧绷」，而狭窄的海上通道就是把「窄」用到水上。"},{"no":"02","title":"The waters of such a passage","titleCN":"海峡水域","definition":"the water area within a narrow passage, used for navigation","definitionCN":"狭窄通道内的水域，供航行使用","example":"Currents in the strait run faster than in the open sea.","exampleCN":"海峡里的水流比外海更快。","why":"The passage is also a place, so the word names the water inside it as well as the route.","whyCN":"通道也是地点，因此这个词既指路线，也指其中的水域。"},{"no":"03","title":"A difficult situation","titleCN":"困境：窘迫的处境","definition":"a difficult or dangerous situation, usually in the plural","definitionCN":"困难或危险的处境，通常用复数","example":"The company is in dire straits after the flood.","exampleCN":"洪水之后公司陷入严重困境。","why":"A narrow passage offers little room to move, so the plural became a picture of a pressing situation.","whyCN":"狭窄通道几乎没有回旋余地，复数形式便成为紧迫处境的图景。"},{"no":"04","title":"Narrow or tight","titleCN":"狭窄的、紧的（古义）","definition":"narrow, tight or confined, an older adjective use","definitionCN":"狭窄、紧绷或受限制的，较旧的形容词用法","example":"They passed through a strait gate into the yard.","exampleCN":"他们穿过一道窄门进入院子。","why":"This is the original sense of the Latin root, kept in older and biblical style.","whyCN":"这是拉丁词根的原义，保留在较旧与圣经风格的语言中。"},{"no":"05","title":"Strict in behaviour","titleCN":"拘谨的、古板的","definition":"strict or morally narrow, especially in the fixed phrase strait-laced","definitionCN":"严格或道德上狭隘的，尤用于固定短语","example":"His strait-laced upbringing made him avoid any joke about money.","exampleCN":"他拘谨的教养使他不肯拿钱开玩笑。","why":"Moral narrowness is a tightness of behaviour, so the old adjective survives in this phrase.","whyCN":"道德上的狭隘就是行为上的紧绷，旧形容词因此留在这个短语里。"},{"no":"06","title":"Short of money","titleCN":"拮据的、窘迫的","definition":"limited in money or resources, in the phrase straitened circumstances","definitionCN":"钱财或资源受限，用于「拮据的境况」这一说法","example":"The family lived in straitened circumstances for years.","exampleCN":"这家人多年生活拮据。","why":"Being pressed for money is being squeezed into a narrow space, which is the root image again.","whyCN":"缺钱就是被挤进狭窄空间，又回到词根的意象。"},{"no":"07","title":"A narrow anatomical passage","titleCN":"解剖或地理中的狭窄通道","definition":"a narrow passage in the body or in a landscape","definitionCN":"身体或地形中的狭窄通道","example":"The pelvic strait is the narrowest part of the birth canal.","exampleCN":"骨盆峡是产道最窄的部分。","why":"The narrow-passage sense extends from sea to any confined channel.","whyCN":"狭窄通道义从海上扩展到任何受限制的通道。"},{"no":"08","title":"A proper name for a sea passage","titleCN":"专名中的海峡","definition":"a capitalized name for a particular sea passage, as in the Straits of Dover","definitionCN":"某一特定海上通道的专名，如多佛海峡","example":"Ships wait for the tide before entering the Straits.","exampleCN":"船只在进入海峡前等待潮水。","why":"Named passages become proper nouns, and the plural form is conventional for some of them.","whyCN":"被命名的通道成为专名，其中一些惯用复数形式。"}],"etymology":{"intro":{"en":"Strait comes from Latin strictus 'drawn tight', through Old French estreit 'narrow'. The same root gives strict and stringent. Dates are approximate.","cn":"该词来自拉丁语表示「拉紧的」分词，经古法语「狭窄的」进入英语。同一词根还给出表示严格与严厉的词。年代均为约数。"},"items":[{"era":"LATIN STRINGERE","en":"stringere meant 'to draw tight, bind, compress', and it also gives English strain and stringent.","cn":"拉丁语词意为「拉紧、束缚、压缩」，也给出英语中表示拉紧与严厉的词。"},{"era":"LATIN STRICTUS","en":"The participle strictus 'drawn tight, narrow' became the adjective behind the English word.","cn":"分词形式意为「被拉紧的、狭窄的」，成为英语词背后的形容词。"},{"era":"OLD FRENCH ESTREIT","en":"Old French estreit meant 'tight, narrow, close', and English borrowed it in the Middle Ages.","cn":"古法语词意为「紧绷、狭窄、贴近」，英语在中世纪借入。"},{"era":"GEOGRAPHY","en":"The geographic sense narrows the adjective to a narrow sea passage between two lands.","cn":"地理义把形容词收窄为两片陆地之间的狭窄海上通道。"},{"era":"TROUBLE","en":"The plural straits shifted from narrow water to a narrow, pressing situation, hence dire straits.","cn":"复数形式从狭窄水域转为狭窄紧迫的处境，因此有「严重困境」之说。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation is approximate, and the adjective is now archaic outside fixed phrases.","cn":"来源不确定（首见年代）：英语最早书证为约数，形容词除固定短语外已属古旧。"}]},"similar":{"note":{"en":"Group one holds look-alike words, including a famous false pair; group two holds the water terms that overlap with a strait.","cn":"第一组是形近词，其中有一对著名的假同源；第二组是与海峡语义重叠的水域词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"straight","ipa":"/streɪt/","tag":"not a relative","definition":"Direct, not curved or bent; it comes from a different Old English root meaning 'stretched', so it is a false relative.","definitionCN":"指直的、不弯的；来自另一个意为「伸展」的古英语词根，因此是假同源。"},{"word":"strict","ipa":"/strɪkt/","tag":"same root","definition":"Severe or exact, from the same Latin participle 'drawn tight'; it describes rules, not water.","definitionCN":"指严厉或精确的，同出表示「拉紧」的拉丁分词；它描述规则，不描述水。"},{"word":"stringent","ipa":"/ˈstrɪndʒənt/","tag":"same root","definition":"Strict and binding, from the same tightening root; it is used of laws and tests.","definitionCN":"指严格而有约束力的，同出「拉紧」词根；用于法律与检验。"},{"word":"strain","ipa":"/streɪn/","tag":"same root","definition":"To stretch or press tightly, or the pressure itself; it shares the tightening image but not the geography.","definitionCN":"指拉紧或挤压，或指这种压力；共享「拉紧」意象，但不用于地理。"}]},{"heading":"NEAR MEANING","entries":[{"word":"channel","ipa":"/ˈtʃænl/","tag":"water route","definition":"A water passage, often a deeper route for ships; it is wider in use than a strait.","definitionCN":"指水上通道，常为供船行的较深路线；使用范围比海峡更广。"},{"word":"sound","ipa":"/saʊnd/","tag":"sea passage","definition":"A narrow sea passage, especially between an island and the mainland; it is close to strait but more local.","definitionCN":"指狭窄的海上通道，尤指岛与大陆之间；与海峡接近，但更具地方性。"},{"word":"passage","ipa":"/ˈpæsɪdʒ/","tag":"general word","definition":"Any way through, by water or land; it is the general term that strait narrows.","definitionCN":"指任何通过之路，水陆皆可；它是海峡所收窄的通用词。"},{"word":"gulf","ipa":"/ɡʌlf/","tag":"enclosed sea","definition":"A large area of sea partly enclosed by land; it is broad, while a strait is narrow.","definitionCN":"指部分被陆地围住的大片海域；它宽阔，而海峡狭窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root means 'drawn tight', and a strait is water drawn into a narrow passage.","cn":"词根意为「拉紧」，海峡就是被拉成狭窄通道的水。"},{"en":"The family runs strait, straits, straitened, strait-laced and straitjacket.","cn":"同族词包括本词、困境复数、拮据形容词、拘谨形容词与拘束衣。"},{"en":"Fixed phrases mark the senses: the Strait of Gibraltar, dire straits, strait-laced.","cn":"固定搭配标出各义项：直布罗陀海峡、严重困境、拘谨的。"},{"en":"Do not confuse it with the word for 'direct', which looks the same and comes from a different root.","cn":"不要把它与表示「直的」那一个词混淆，二者同形却词根不同。"},{"en":"A strait is water between lands, the opposite of an isthmus, which is land between waters.","cn":"海峡是陆地之间的水，与地峡相反，后者是水之间的陆地。"}],"abstract":[{"en":"Picture a tight collar that leaves almost no room to turn the head.","cn":"想象一只紧领子，几乎不给人转头的余地。"},{"en":"Picture a narrow door between two large rooms, with people filing through.","cn":"想象两个大房间之间一道窄门，人们排队通过。"},{"en":"Picture a corridor whose walls press closer with every step.","cn":"想象一条走廊，每走一步两壁就更紧。"}]},"examples":[{"en":"The strait is too shallow for the largest ships.","cn":"这道海峡对最大的船来说太浅。"},{"en":"After the factory closed, the town was in dire straits.","cn":"工厂关闭后，小镇陷入严重困境。"},{"en":"A lighthouse marks the narrowest point of the strait.","cn":"一座灯塔标出海峡最窄处。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「死追特」：船在窄海峡里只能死追着前船走。","word":"strait"},"root":"拉丁语 stringere「拉紧、束缚」的分词 strictus「拉紧的、狭窄的」，经古法语 estreit「狭窄的」进入英语；同一词根还构成 strict 与 stringent。","sensesIntro":{"en":"Eight senses follow one tightness: water squeezed between two lands. The tightness then widens into the waters themselves, presses into a difficult situation, returns as an old adjective for narrow, becomes moral tightness, money shortage, an anatomical passage and a proper name.","cn":"八个义项沿同一种「紧」展开：被两片陆地夹紧的水。这种紧随后扩展到水域本身、压成困境、回到表示狭窄的旧形容词、转为道德上的紧、钱财上的紧、解剖通道与专名。"},"semanticMap":{"core":{"en":"CORE IMAGE: two shores pressing close together, leaving only a narrow lane of water.","cn":"核心意象：两岸紧紧靠拢，只留下一条狭窄的水道。"},"chain":["TIGHT NARROW","SEA PASSAGE","ITS WATERS","DIFFICULT SITUATION","MORAL TIGHTNESS","SHORT OF MONEY"],"branches":[{"senses":"S1 · S2 · S8","en":"THE PASSAGE: the narrow route, its water and its proper name are one place.","cn":"通道：狭窄路线、其中的水与它的专名是同一个地方。"},{"senses":"S3","en":"TROUBLE: a passage with no room to move becomes a picture of hardship.","cn":"困境：没有回旋余地的通道成为困苦的图景。"},{"senses":"S4 · S5","en":"TIGHTNESS OF RULE: narrow in space and strict in behaviour are the same root image.","cn":"规则之紧：空间上的窄与行为上的严是同一词根意象。"},{"senses":"S6","en":"MONEY: being short is being squeezed into a narrow margin.","cn":"钱财：短缺就是被挤进狭窄的余量。"},{"senses":"S7","en":"BODY: anatomy uses the same narrow-passage image.","cn":"身体：解剖学使用同一狭窄通道意象。"}]},"affixes":{"intro":{"en":"Strait is a Latin participle turned English noun, and the tightening root builds a small but common family.","cn":"该词是拉丁分词转成的英语名词，其「拉紧」词根构成一个小而常见的词族。"},"latinIntro":{"en":"Latin stringere and strictus give strait, strict, stringent and strain; the prefixes and endings decide the shade.","cn":"拉丁语的「拉紧」动词与分词给出本词以及表示严格、严厉与拉紧的词；前缀与词尾决定意味。"},"items":[{"word":"stringere","structure":"stringere (Latin verb, third conjugation)","meaning":"to draw tight, bind","meaningCN":"拉紧；束缚","example":"The root supplies the image of tightening.","exampleCN":"这个词根提供「收紧」的意象。"},{"word":"strictus","structure":"strictus (Latin past participle, 'drawn tight')","meaning":"drawn tight, narrow","meaningCN":"拉紧的；狭窄的","example":"The participle became the adjective behind the noun.","exampleCN":"这个分词成为名词背后的形容词。"},{"word":"strait","structure":"strictus -> Old French estreit -> strait","meaning":"narrow; a narrow sea passage","meaningCN":"狭窄的；海峡","example":"Ferries cross the strait every hour.","exampleCN":"渡船每小时穿过海峡。"},{"word":"straits","structure":"strait + -s (plural)","meaning":"difficult circumstances","meaningCN":"困境","example":"The town is in dire straits.","exampleCN":"小镇陷入严重困境。"},{"word":"straitened","structure":"strait + -en + -ed (made narrow)","meaning":"restricted in money","meaningCN":"拮据的","example":"They lived in straitened circumstances.","exampleCN":"他们生活拮据。"},{"word":"strait-laced","structure":"strait + laced (compound adjective)","meaning":"strictly moral","meaningCN":"拘谨的；古板的","example":"His strait-laced aunt disapproved of the plan.","exampleCN":"他古板的姑妈不赞成这个计划。"},{"word":"straitjacket","structure":"strait + jacket (compound noun)","meaning":"a tight restraining jacket","meaningCN":"拘束衣；束缚","example":"The rules became a straitjacket for the staff.","exampleCN":"这些规定成了员工的束缚。"},{"word":"strict","structure":"strictus -> strict (adjective)","meaning":"severe, exact","meaningCN":"严格的；精确的","example":"The school has strict rules about lateness.","exampleCN":"学校对迟到有严格规定。"},{"word":"stringent","structure":"stringere + -ent (adjective)","meaning":"binding, severe","meaningCN":"严厉的；有约束力的","example":"Stringent tests protect the water supply.","exampleCN":"严格的检验保护供水。"}],"latinEntries":[{"word":"stringere","structure":"stringere, strinxi, strictum (verb, third conjugation)","meaning":"to draw tight, bind, compress","meaningCN":"拉紧；束缚；压缩"},{"word":"strictus","structure":"strictus, stricta, strictum (adj., first/second declension)","meaning":"drawn tight, narrow","meaningCN":"拉紧的；狭窄的"},{"word":"strictio","structure":"strictio, strictionis (f., third declension)","meaning":"a tightening, compression","meaningCN":"收紧；压缩"}]}},{"word":"channel","ipa_uk":"/ˈtʃænl/","ipa_us":"/ˈtʃænl/","definition_zh":"航道；频道；渠道；沟槽；引导；输送；信道","definition_en":"a narrow passage of water, a medium through which something passes, or to direct something along a route","core_image":"一条被两岸夹住的水道，船顺着它把货物送到远处","scene":"救援船从狭窄的航道中驶出。The rescue boat moved through the narrow channel.","sceneCN":"这里该词指「可供船只通行的水道」（第 1 个义项：河流或海峡中的航道）；句意为救援船从狭窄的航道中驶出。","pos":[{"tag":"n.","zh":"航道；频道；渠道；沟槽；信道"},{"tag":"vt.","zh":"引导；输送；把……用于特定用途"}],"collocations":[{"phrase":"the English Channel","zh":"英吉利海峡"},{"phrase":"a shipping channel","zh":"航运水道"},{"phrase":"a television channel","zh":"电视频道"},{"phrase":"channel funds","zh":"拨付资金"},{"phrase":"a communication channel","zh":"沟通渠道"},{"phrase":"a water channel","zh":"水渠；水道"}],"forms":[{"label":"复数（名词）","form":"channels"},{"label":"三单（动词）","form":"channels"},{"label":"过去式（英式）","form":"channelled"},{"label":"过去分词（英式）","form":"channelled"},{"label":"现在分词（英式）","form":"channelling"},{"label":"过去式（美式）","form":"channeled"}],"derivatives":[{"word":"channelization","pos":"n.","zh":"渠道化；河道整治"},{"word":"channelized","pos":"adj.","zh":"被渠道化的；被引导的"},{"word":"channeler","pos":"n.","zh":"传导者；通灵者"},{"word":"channel-surf","pos":"v.","zh":"频繁换台"},{"word":"multi-channel","pos":"adj.","zh":"多渠道的；多频道的"}],"senses":[{"no":"01","title":"A waterway for ships","titleCN":"航道：供船只通行的水道","definition":"a narrow passage of water, especially a route kept open for ships","definitionCN":"狭窄的水道，尤指为船只保持通行的路线","example":"The rescue boat moved through the narrow channel.","exampleCN":"救援船从狭窄的航道中驶出。","why":"Latin canalis first meant a pipe or groove, and a waterway is a groove that water and ships follow.","whyCN":"拉丁语原指管道或沟槽，水道就是水与船共同循行的沟。"},{"no":"02","title":"A broadcast frequency","titleCN":"频道：广播或电视的频率","definition":"a frequency band or programme service used for broadcasting","definitionCN":"用于广播的频率段或节目服务","example":"The news moved to a different channel.","exampleCN":"新闻节目换到了另一个频道。","why":"Radio borrowed the water word for a path that signals travel along, one band beside another.","whyCN":"无线电借用了水的词，指信号沿之行进的路径，一条频带挨着另一条。"},{"no":"03","title":"A means of communication","titleCN":"渠道：沟通或办事的途径","definition":"a means by which information, requests or goods pass between people","definitionCN":"信息、请求或货物在人与人之间传递的途径","example":"Complaints should go through the official channel.","exampleCN":"投诉应通过正式渠道提出。","why":"A route carries water; a social route carries messages, so the metaphor is direct.","whyCN":"路线运送水，社会路线运送信息，比喻由此直接成立。"},{"no":"04","title":"A groove or duct","titleCN":"沟槽或管道","definition":"a long groove or passage cut into a surface or built for liquids","definitionCN":"在表面切出的长沟，或为液体修建的通道","example":"Rain runs down the stone channel beside the road.","exampleCN":"雨水沿路旁的石头沟槽流下。","why":"This is the oldest material sense: the pipe or groove itself.","whyCN":"这是最古老的实物义：管道或沟槽本身。"},{"no":"05","title":"To direct money or effort","titleCN":"引导、输送资金或精力","definition":"to send money, resources or effort to a particular purpose","definitionCN":"把资金、资源或精力送往特定用途","example":"The foundation channels funds into rural schools.","exampleCN":"基金会把资金输送到乡村学校。","why":"The noun's route becomes a verb: to make something follow that route.","whyCN":"名词的路线转为动词：使某物沿那条路线走。"},{"no":"06","title":"To focus energy or emotion","titleCN":"把精力或情绪导向某处","definition":"to direct energy, emotion or talent toward one use","definitionCN":"把精力、情绪或才能导向某一用途","example":"She channels her anger into training.","exampleCN":"她把愤怒投入训练。","why":"The image is the same: strong feeling is water that needs a bed to run in.","whyCN":"意象相同：强烈情绪像需要河床才能流的水。"},{"no":"07","title":"A path for a signal","titleCN":"通信信道","definition":"a path or connection over which signals travel in a communication system","definitionCN":"通信系统中信号行进的路径或连接","example":"The data channel failed during the storm.","exampleCN":"数据信道在暴风雨中失效。","why":"Engineering keeps the metaphor of a route, now for electrical or optical signals.","whyCN":"工程沿用路线的比喻，如今指电信号或光信号。"},{"no":"08","title":"A proper name for a sea passage","titleCN":"专名：英吉利海峡","definition":"a capitalized name for a particular sea passage, especially the one between England and France","definitionCN":"特定海上通道的专名，尤指英法之间的海峡","example":"Swimmers rarely cross the Channel alone.","exampleCN":"游泳者很少独自横渡英吉利海峡。","why":"A named channel becomes a proper noun, and the capital letter marks the specific passage.","whyCN":"被命名的海峡成为专名，大写字母标出那条特定的通道。"}],"etymology":{"intro":{"en":"Channel comes from Latin canalis 'pipe, groove', built on canna 'reed'. The same root gives canal. Dates are approximate.","cn":"该词来自拉丁语表示「管道、沟槽」的词，其基础是表示「芦苇」的词；同一词根还给出表示人工水道的词。年代均为约数。"},"items":[{"era":"LATIN CANNA","en":"canna meant 'reed', borrowed from Greek; a reed pipe was one of the first things the word named.","cn":"拉丁语词意为「芦苇」，借自希腊语；芦苇管是它最早命名的事物之一。"},{"era":"LATIN CANALIS","en":"canalis 'pipe, groove, water channel' is the direct source, and it also gives English canal.","cn":"表示「管道、沟槽、水渠」的词是直接来源，也给出英语中表示人工水道的词。"},{"era":"OLD FRENCH CHANEL","en":"Old French chanel 'bed of a waterway' brought the word into English in the Middle Ages.","cn":"古法语表示「水道河床」的词在中世纪把该词带入英语。"},{"era":"TELEGRAPHY AND RADIO","en":"Telegraphy, then radio, extended channel from water to a path for signals.","cn":"电报与随后的无线电把这个词从水上扩展到信号的路径。"},{"era":"FIGURATIVE USE","en":"The route image produced the verb, so money, energy and emotion can be channeled.","cn":"路线意象产生动词用法，因此资金、精力与情绪都可以被引导。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates of the media senses): early citations vary, and dates are approximate.","cn":"来源不确定（媒介义的首见年代）：早期书证不一，年代为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike words, including one true relative and one false friend; group two holds the water-route words that overlap with channel.","cn":"第一组是形近词，其中有一个真同源和一个假朋友；第二组是与航道语义重叠的水路词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"canal","ipa":"/kəˈnæl/","tag":"same root","definition":"A man-made waterway; it comes from the same Latin word but names a built ditch, not a natural passage.","definitionCN":"指人工水道；同出这一拉丁词，但指修建的沟渠，不是天然通道。"},{"word":"kennel","ipa":"/ˈkenl/","tag":"different root","definition":"A shelter for dogs; it looks similar but comes from a French word for a dog's house.","definitionCN":"指狗舍；形似但来自法语表示狗屋的词。"},{"word":"chancel","ipa":"/ˈtʃænsl/","tag":"church part","definition":"The part of a church around the altar; it looks close but comes from a Latin word for a lattice screen.","definitionCN":"指教堂祭坛周围的部分；形似但来自拉丁语表示格栅屏风的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"strait","ipa":"/streɪt/","tag":"narrow sea passage","definition":"A narrow passage between two seas; it is a physical water route, while channel can also be a signal path.","definitionCN":"指两片海域之间的狭窄通道；它是实物水路，而本词也可指信号路径。"},{"word":"waterway","ipa":"/ˈwɔːtəweɪ/","tag":"general route","definition":"Any route for water or boats, natural or built; it is the broader everyday term.","definitionCN":"指任何水道或航道，天然或人工皆可；它是更宽泛的日常词。"},{"word":"passage","ipa":"/ˈpæsɪdʒ/","tag":"way through","definition":"A way through or across; it is general and can apply to sea, land, time or text.","definitionCN":"指通过或穿越之路；它很通用，可用于海、陆、时间或文本。"},{"word":"conduit","ipa":"/ˈkɒndjuɪt/","tag":"pipe for flow","definition":"A pipe or tube carrying water or signals; it stresses the physical carrier more than the route.","definitionCN":"指输送水或信号的管道；比路线更强调物理载体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root is a reed pipe: a hollow route that carries something through.","cn":"词根是芦苇管：一条把某物送过去的中空路线。"},{"en":"The family runs channel, channels, channelization, channeler and multi-channel.","cn":"同族词包括本词、其复数、渠道化、传导者与多渠道形容词。"},{"en":"Fixed phrases mark the senses: a shipping channel, a television channel, channel funds, a communication channel.","cn":"固定搭配标出各义项：航运水道、电视频道、拨付资金、沟通渠道。"},{"en":"The same word moved from water to television to electronics without changing its route image.","cn":"同一个词从水路移到电视再到电子，始终没有换掉「路线」意象。"},{"en":"The proper name with a capital letter usually means the sea passage between England and France.","cn":"大写的专名通常指英法之间的海上通道。"}],"abstract":[{"en":"Picture a groove cut in a wooden board, guiding a marble in one direction.","cn":"想象木板上刻出一道沟，把弹珠引向一个方向。"},{"en":"Picture a switchboard sending each call down a different wire.","cn":"想象交换机把每通电话送到不同的线上。"},{"en":"Picture a riverbed that gives angry water a fixed way to run.","cn":"想象河床给愤怒的水一条固定的去路。"}]},"examples":[{"en":"The harbour entrance is a narrow channel that silts up each winter.","cn":"港口入口是一条狭窄航道，每年冬天都会淤积。"},{"en":"The charity channels donations toward local clinics.","cn":"这家慈善机构把捐款输送到本地诊所。"},{"en":"Switch to another channel if the storm interrupts the broadcast.","cn":"如果暴风雨打断广播，就换到另一个频道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「穿牛」：水从一条窄道穿过去，像牛穿过小巷——航道、渠道。","word":"channel"},"root":"拉丁语 canna「芦苇」→ canalis「管道、沟槽、水渠」，经古法语 chanel 进入英语；同一词根还构成 canal。","sensesIntro":{"en":"Eight senses follow one route: something is carried through a narrow way. The route runs from a ship channel to a broadcast band, a social means, a groove, directed money, focused emotion, a signal path and a named sea passage.","cn":"八个义项沿同一条路线展开：某物被带过一条狭窄通道。这条路线从船舶航道，延伸到广播频带、社会途径、沟槽、被引导的资金、被集中的情绪、信号路径与专名海峡。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cut or pipe that gives whatever passes through it one fixed direction.","cn":"核心意象：一条沟或管道，给通过之物一个固定方向。"},"chain":["WATER ROUTE","BROADCAST BAND","SOCIAL MEANS","GROOVE","DIRECTED MONEY","SIGNAL PATH"],"branches":[{"senses":"S1 · S8","en":"WATER: a natural passage and its proper name are the same route.","cn":"水：天然通道与它的专名是同一条路线。"},{"senses":"S2 · S7","en":"SIGNAL: broadcast bands and data paths borrow the water route.","cn":"信号：广播频带与数据路径借用了水上路线。"},{"senses":"S3","en":"SOCIETY: information and requests travel through channels too.","cn":"社会：信息与请求也沿渠道传递。"},{"senses":"S4","en":"MATERIAL: the groove or pipe is the oldest physical form of the route.","cn":"实物：沟槽或管道是这条路最古老的实物形态。"},{"senses":"S5 · S6","en":"DIRECTION: money and emotion are made to follow a chosen route.","cn":"导向：资金与情绪被引导到选定的路线。"}]},"affixes":{"intro":{"en":"Channel is a Latin loan whose root also builds canal; the English family is mostly technical compounds.","cn":"该词是拉丁借词，其词根还构成表示人工水道的词；英语词族多为技术复合词。"},"latinIntro":{"en":"Latin canna 'reed' and canalis 'pipe' give channel and canal; the reed pipe is the earliest image.","cn":"拉丁语「芦苇」与「管道」给出本词与表示人工水道的词；芦苇管是最早的意象。"},"items":[{"word":"canna","structure":"canna, cannae (f., first declension)","meaning":"reed","meaningCN":"芦苇","example":"The reed gave its name to a hollow pipe.","exampleCN":"芦苇把自己的名字给了中空的管子。"},{"word":"canalis","structure":"canalis, canalis (m., third declension)","meaning":"pipe, groove, water channel","meaningCN":"管道；沟槽；水渠","example":"The Latin noun named a groove for water.","exampleCN":"这个拉丁名词指让水流过的沟。"},{"word":"channel","structure":"canalis -> Old French chanel -> channel","meaning":"a water route","meaningCN":"航道；水道","example":"The rescue boat moved through the narrow channel.","exampleCN":"救援船从狭窄航道中驶出。"},{"word":"channels","structure":"channel + -s (plural or third person)","meaning":"more than one channel","meaningCN":"多个渠道","example":"Two channels keep the harbour open.","exampleCN":"两条航道让港口保持通行。"},{"word":"channelization","structure":"channel + -ization (process)","meaning":"the cutting of a straight channel","meaningCN":"渠道化；河道整治","example":"Channelization narrowed the river.","exampleCN":"河道整治使河流变窄。"},{"word":"channelized","structure":"channel + -ized (made into a channel)","meaning":"turned into a fixed channel","meaningCN":"被渠道化的","example":"The channelized stream runs straight to the sea.","exampleCN":"被渠道化的溪流笔直入海。"},{"word":"channeler","structure":"channel + -er (one who does)","meaning":"one who directs or transmits","meaningCN":"传导者；引导者","example":"The channeler passed the message to the group.","exampleCN":"传导者把信息传给群体。"},{"word":"multi-channel","structure":"multi- (many) + channel","meaning":"using several channels","meaningCN":"多渠道的","example":"A multi-channel shop sells online and in stores.","exampleCN":"多渠道商店同时在线上与门店销售。"},{"word":"the Channel","structure":"proper noun (geographic)","meaning":"the sea passage between England and France","meaningCN":"英吉利海峡","example":"The Channel is busy with ferries.","exampleCN":"英吉利海峡渡船繁忙。"}],"latinEntries":[{"word":"canna","structure":"canna, cannae (f., first declension)","meaning":"reed, cane","meaningCN":"芦苇；茎秆"},{"word":"canalis","structure":"canalis, canalis (m., third declension)","meaning":"pipe, groove, channel","meaningCN":"管道；沟槽；水道"},{"word":"canaliculatus","structure":"canaliculatus, canaliculata, canaliculatum (adj.)","meaning":"grooved, channeled","meaningCN":"有沟的；具渠道的"}]}},{"word":"bay","ipa_uk":"/beɪ/","ipa_us":"/beɪ/","definition_zh":"海湾；凹进的隔间；月桂；栗色马；吠叫；困境","definition_en":"a part of the sea partly enclosed by land, or a recessed space, a laurel, a reddish-brown horse, or to bark","core_image":"一片海水弯进陆地，三面被岸包围，只留一个宽口通向大海","scene":"渔船在湾内下锚，避开了外海的风浪。Fishing boats anchor inside the bay, away from the open sea.","sceneCN":"这里该词指「三面被陆地环抱的海水」（第 1 个义项：海湾）；句意为渔船在湾内下锚，避开外海的风浪。","pos":[{"tag":"n.","zh":"海湾；凹间；月桂；栗色马"},{"tag":"vi.","zh":"吠叫；长嚎"},{"tag":"vt.","zh":"使陷入困境；围困（多用于固定短语）"}],"collocations":[{"phrase":"a sheltered bay","zh":"避风的海湾"},{"phrase":"the Bay of Bengal","zh":"孟加拉湾"},{"phrase":"a loading bay","zh":"装卸区"},{"phrase":"bay leaves","zh":"月桂叶"},{"phrase":"a bay horse","zh":"栗色马"},{"phrase":"keep at bay","zh":"使无法靠近；遏制"}],"forms":[{"label":"复数（名词）","form":"bays"},{"label":"三单（动词）","form":"bays"},{"label":"过去式","form":"bayed"},{"label":"过去分词","form":"bayed"},{"label":"现在分词","form":"baying"}],"derivatives":[{"word":"baying","pos":"n.","zh":"吠叫声；长嚎"},{"word":"bay window","pos":"n.","zh":"凸窗"},{"word":"bay leaf","pos":"n.","zh":"月桂叶"},{"word":"parking bay","pos":"n.","zh":"停车位"},{"word":"keep at bay","pos":"phr.","zh":"使无法靠近；遏制"}],"senses":[{"no":"01","title":"A sea inlet","titleCN":"海湾：部分被陆地围住的海水","definition":"a part of the sea partly enclosed by land, with a wide opening to the open water","definitionCN":"部分被陆地围住、留有宽口通向开阔水域的海面","example":"Fishing boats anchor inside the bay, away from the open sea.","exampleCN":"渔船在湾内下锚，避开外海的风浪。","why":"Old French baie named an inlet, probably from an Iberian word rather than from Latin.","whyCN":"古法语词指小海湾，可能来自伊比利亚语，而非拉丁语。"},{"no":"02","title":"A loading or parking space","titleCN":"装卸区或停车位","definition":"a marked recessed area for loading goods or parking a vehicle","definitionCN":"为装卸货物或停放车辆划出的凹进区域","example":"The truck waited in the loading bay.","exampleCN":"卡车在装卸区等候。","why":"An opening in a building is like an inlet in a coast: both are recesses cut into a larger surface.","whyCN":"建筑上的开口像海岸上的小湾：两者都是切进更大表面中的凹入处。"},{"no":"03","title":"A projecting window","titleCN":"凸窗","definition":"a window that projects outward from a wall, forming a small recess inside","definitionCN":"从墙面凸出、在室内形成小凹间的窗","example":"She reads in the bay window every morning.","exampleCN":"她每天早晨在凸窗边读书。","why":"The projecting window creates a small bay-like recess inside the room.","whyCN":"凸出的窗在室内造出一个像小海湾的凹间。"},{"no":"04","title":"The laurel tree","titleCN":"月桂树与月桂叶","definition":"a laurel tree or its dried leaf, used in cooking","definitionCN":"月桂树或其干叶，用于烹调","example":"Add two bay leaves to the soup.","exampleCN":"汤里放两片月桂叶。","why":"This sense comes through Old French from Latin for 'berry', because the laurel bears small dark berries.","whyCN":"这一义项经古法语来自拉丁语表示「浆果」的词，因为月桂结深色小果。"},{"no":"05","title":"A reddish-brown horse","titleCN":"栗色马","definition":"a horse with a reddish-brown coat and black points","definitionCN":"毛色红棕、四肢末端为黑色的马","example":"The bay mare led the others across the field.","exampleCN":"那匹栗色母马领着其他马穿过田野。","why":"This is a separate word from Latin for 'chestnut-brown', which became the colour name for horses.","whyCN":"这是另一个词，来自拉丁语表示「栗褐色」，后来成为马的毛色名。"},{"no":"06","title":"To bark or howl","titleCN":"吠叫、长嚎","definition":"to make a long barking cry, especially of a hound","definitionCN":"发出长声吠叫，尤指猎犬","example":"The hounds bayed at the moon.","exampleCN":"猎犬对着月亮长嚎。","why":"The barking sense comes from an imitative Old French verb, not from the sea inlet.","whyCN":"吠叫义来自古法语拟声动词，与海湾义无关。"},{"no":"07","title":"To hold something off","titleCN":"使无法靠近；遏制","definition":"to keep someone or something at a distance, in the phrase keep at bay","definitionCN":"使某人或某物保持距离，用于固定短语","example":"Vaccination kept the disease at bay.","exampleCN":"接种疫苗遏制住了这种疾病。","why":"A hunted animal held off by barking hounds gave the image of keeping danger at a distance.","whyCN":"被猎犬吠声挡住的猎物，给出把危险挡在远处的意象。"},{"no":"08","title":"A recess in a building","titleCN":"建筑中的凹间","definition":"a recessed section of a wall or room, often between columns","definitionCN":"墙面或房间中凹进的一段，常在柱子之间","example":"The bookshelf fills the bay between the pillars.","exampleCN":"书架填满了柱子之间的凹间。","why":"The architectural sense comes from a French word for an opening in a wall, parallel to the coastal inlet.","whyCN":"建筑义来自法语表示墙洞的词，与海岸小湾平行发展。"}],"etymology":{"intro":{"en":"Bay is several different words that share one spelling. The sea inlet, the laurel, the brown horse, the bark and the wall recess have separate histories. Dates are approximate.","cn":"这个词其实是几个拼写相同、来历不同的词：海湾、月桂、栗色马、吠叫与墙洞各有自己的历史。年代均为约数。"},"items":[{"era":"SEA INLET","en":"The coastal sense comes from Old French baie 'inlet', from Late Latin baia, probably borrowed from an Iberian word; its deeper source is uncertain.","cn":"海岸义来自古法语表示「小海湾」的词，再往上可能是晚期拉丁语借自伊比利亚语，更深来源不确定。"},{"era":"LAUREL","en":"The laurel sense comes from Latin for 'berry', through Old French, because the tree bears small dark fruit.","cn":"月桂义经古法语来自拉丁语表示「浆果」的词，因为这种树结深色小果。"},{"era":"BROWN HORSE","en":"The horse colour comes from Latin for 'chestnut-brown', a separate adjective that became a noun.","cn":"马的毛色义来自拉丁语表示「栗褐色」的形容词，后来转为名词。"},{"era":"BARKING","en":"The barking sense comes from an imitative Old French verb for barking; the sound shaped the word.","cn":"吠叫义来自古法语拟声动词，词形由声音塑造。"},{"era":"WALL RECESS","en":"The architectural sense comes from Old French for an opening in a wall, and it developed alongside the coastal inlet.","cn":"建筑义来自古法语表示墙洞的词，与海岸小湾义平行发展。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (the sea inlet): the Late Latin form is probably Iberian rather than Latin, and the first dates of each sense are approximate.","cn":"来源不确定（海湾义）：晚期拉丁形式可能来自伊比利亚语而非拉丁语，各义项首见年代均为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike words with unrelated histories; group two holds the coastal terms that overlap with a bay.","cn":"第一组是字形相近但来历无关的词；第二组是与海湾语义重叠的海岸术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bayou","ipa":"/ˈbaɪuː/","tag":"marshy outlet","definition":"A slow, marshy outlet of a lake or river, especially in the southern United States; it is a different word.","definitionCN":"指湖或河缓慢流出的沼泽水道，尤见于美国南部；这是另一个词。"},{"word":"bale","ipa":"/beɪl/","tag":"bound bundle","definition":"A large bundle of goods tied for transport; the spelling is close but the history is unrelated.","definitionCN":"指为运输捆扎的大包货物；拼写接近，但来历无关。"},{"word":"bey","ipa":"/beɪ/","tag":"Ottoman title","definition":"A title for a provincial governor in the Ottoman Empire; it is a loan from Turkish.","definitionCN":"指奥斯曼帝国省督的称号；借自土耳其语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"gulf","ipa":"/ɡʌlf/","tag":"large bay","definition":"A large area of sea partly enclosed by land; it is much bigger than a bay.","definitionCN":"指部分被陆地围住的大片海域；比普通海湾大得多。"},{"word":"cove","ipa":"/kəʊv/","tag":"small sheltered inlet","definition":"A small sheltered inlet with a narrow entrance; it is smaller and more enclosed than a bay.","definitionCN":"指入口狭窄的小型避风湾；比海湾更小、更封闭。"},{"word":"inlet","ipa":"/ˈɪnlet/","tag":"narrow opening","definition":"A narrow strip of water running into the land; it stresses the opening rather than the enclosed water.","definitionCN":"指伸入陆地的狭窄水域；强调开口而非被围住的水面。"},{"word":"harbor","ipa":"/ˈhɑːbə/","tag":"sheltered port","definition":"A sheltered place where ships can anchor; it stresses safety for ships, not the coastal shape.","definitionCN":"指船只可停泊的避风处；强调船只安全，而非海岸形状。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The sea sense is an inlet: a wide mouth of water biting into the land.","cn":"海义就是小湾：一大口海水咬进陆地。"},{"en":"The building sense is the same shape indoors: a recess between columns.","cn":"建筑义是同一形状搬到室内：柱子之间的凹间。"},{"en":"The family runs bay, bays, baying, bay window, bay leaf and parking bay.","cn":"同族词包括本词、复数、吠叫名词、凸窗、月桂叶与停车位。"},{"en":"Fixed phrases mark the senses: a sheltered bay, a loading bay, bay leaves, a bay horse.","cn":"固定搭配标出各义项：避风海湾、装卸区、月桂叶、栗色马。"},{"en":"The phrase keep at bay keeps the oldest hunting image: danger held off by barking.","cn":"表示遏制的固定短语保留了最古老的狩猎意象：危险被吠声挡在远处。"}],"abstract":[{"en":"Picture a blue arm curling into a green shore.","cn":"想象一条蓝色手臂弯进绿色海岸。"},{"en":"Picture a shallow shelf recessed into a wall, just deep enough for books.","cn":"想象墙里凹进一层浅架，刚好放书。"},{"en":"Picture a hound's long call rising over an empty field.","cn":"想象猎犬的长嚎在空野上扬起。"}]},"examples":[{"en":"The bay is shallow, so large ships anchor outside it.","cn":"这个海湾水浅，大船只能在外面下锚。"},{"en":"Leave the delivery van in the loading bay.","cn":"把送货车停在装卸区。"},{"en":"A row of bay trees shelters the terrace from wind.","cn":"一排月桂树为露台挡风。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「贝」：贝壳形的海岸凹进去，就是海湾。","word":"bay"},"root":"拼写相同但来源多支：海湾义经古法语，可能上溯伊比利亚语；月桂义来自拉丁语「浆果」；栗色马义来自拉丁语「栗褐色」；吠叫义来自古法语拟声动词；墙洞义来自古法语。","sensesIntro":{"en":"Eight senses come from several words that look alike. The coastal inlet gives the shape; the building recess copies it; the laurel, the brown horse and the bark are separate homographs; the phrase keep at bay returns to the hunting image.","cn":"八个义项来自几个形似的词。海岸小湾提供形状；建筑凹间复制这个形状；月桂、栗色马与吠叫是另外的同形词；表示遏制的短语则回到狩猎意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rounded recess cut into a larger edge, whether coast, wall or shelf.","cn":"核心意象：在更大边缘上切出的圆形凹入处，无论海岸、墙面还是架子。"},"chain":["SEA INLET","BUILDING RECESS","PROJECTING WINDOW","LAUREL","BROWN HORSE","HOLDING OFF"],"branches":[{"senses":"S1","en":"COAST: water bites into land and leaves a wide mouth.","cn":"海岸：水咬进陆地，留下一个宽口。"},{"senses":"S2 · S3 · S8","en":"RECESS: a loading space, a projecting window and a wall bay all repeat the coastal shape indoors.","cn":"凹间：装卸区、凸窗与墙间都在室内重复海岸形状。"},{"senses":"S4 · S5","en":"HOMOGRAPHS: the laurel and the brown horse are unrelated words that share the spelling.","cn":"同形词：月桂与栗色马是共享拼写却无关的词。"},{"senses":"S6","en":"SOUND: barking is an imitative word, not a coastal one.","cn":"声音：吠叫是拟声词，与海岸无关。"},{"senses":"S7","en":"DISTANCE: hunting dogs held prey off, and the phrase now means keeping danger away.","cn":"距离：猎犬挡住猎物，这个短语如今指把危险挡开。"}]},"affixes":{"intro":{"en":"Bay has no single root because it is several homographs; each sense has its own small family, mostly compounds and fixed phrases.","cn":"该词没有单一词根，因为它是几个同形词；每个义项各有小词族，多为复合词与固定短语。"},"latinIntro":{"en":"Some senses are Latin-derived (berry, chestnut-brown), while the sea inlet is probably Iberian and the barking sense is imitative French; the Latin list therefore holds only the genuinely Latin forms.","cn":"部分义项来自拉丁语（浆果、栗褐色），而海湾义可能来自伊比利亚语，吠叫义来自法语拟声词；因此拉丁词条只列真正来自拉丁语的形式。"},"items":[{"word":"baie","structure":"Old French baie (noun, 'inlet')","meaning":"a small sea inlet","meaningCN":"小海湾","example":"The old word named a sheltering arm of the sea.","exampleCN":"这个旧词指海中避风的一弯水。"},{"word":"baca","structure":"Latin baca (noun, 'berry')","meaning":"berry","meaningCN":"浆果","example":"The laurel's dark berries gave the tree its name.","exampleCN":"月桂的深色浆果给了这种树名字。"},{"word":"badius","structure":"Latin badius (adj., 'chestnut-brown')","meaning":"chestnut-brown","meaningCN":"栗褐色","example":"The colour word became the name of a horse.","exampleCN":"这个颜色词变成了马的名号。"},{"word":"baier","structure":"Old French baier (verb, imitative, 'to bark')","meaning":"to bark","meaningCN":"吠叫","example":"The hounds bay at the moon.","exampleCN":"猎犬对着月亮长嚎。"},{"word":"bay","structure":"bay (English noun and verb)","meaning":"inlet; to bark","meaningCN":"海湾；吠叫","example":"Fishing boats anchor inside the bay.","exampleCN":"渔船在湾内下锚。"},{"word":"bays","structure":"bay + -s (plural or third person)","meaning":"more than one bay","meaningCN":"多个海湾","example":"Two bays cut into the northern shore.","exampleCN":"北岸切进两个海湾。"},{"word":"bay window","structure":"bay + window (compound)","meaning":"a projecting window","meaningCN":"凸窗","example":"The bay window faces the garden.","exampleCN":"凸窗朝向花园。"},{"word":"bay leaf","structure":"bay + leaf (compound)","meaning":"a dried laurel leaf","meaningCN":"月桂叶","example":"One bay leaf flavours the stew.","exampleCN":"一片月桂叶就能给炖菜提味。"},{"word":"keep at bay","structure":"keep + at + bay (fixed phrase)","meaning":"to hold off","meaningCN":"使无法靠近","example":"The fence keeps animals at bay.","exampleCN":"围栏把动物挡在外面。"}],"latinEntries":[{"word":"baca","structure":"baca, bacae (f., first declension)","meaning":"berry","meaningCN":"浆果"},{"word":"badius","structure":"badius, badia, badium (adj., first/second declension)","meaning":"chestnut-brown","meaningCN":"栗褐色的"},{"word":"baia","structure":"baia, baiae (f., first declension, Late Latin)","meaning":"bay, inlet (probably borrowed from Iberian)","meaningCN":"海湾（可能借自伊比利亚语）"}]}},{"word":"gulf","ipa_uk":"/ɡʌlf/","ipa_us":"/ɡʌlf/","definition_zh":"海湾；巨大分歧；鸿沟；深渊；海湾地区","definition_en":"a large area of sea partly enclosed by land, or a wide separation between people or things","core_image":"一大片海水深深凹进陆地，近岸处像被陆地抱住","scene":"河流注入那片宽阔的海湾。The river pours into the wide gulf.","sceneCN":"这里该词指「大片伸入陆地的海面」（第 1 个义项：大海湾）；句意为河流注入那片宽阔的海湾。","pos":[{"tag":"n.","zh":"海湾；鸿沟；深渊；海湾地区"},{"tag":"vt.","zh":"吞没；使陷入（古旧用法）"}],"collocations":[{"phrase":"the Gulf of Mexico","zh":"墨西哥湾"},{"phrase":"the Persian Gulf","zh":"波斯湾"},{"phrase":"a deep gulf","zh":"巨大的鸿沟"},{"phrase":"bridge the gulf","zh":"弥合鸿沟"},{"phrase":"the Gulf states","zh":"海湾国家"},{"phrase":"a gulf between generations","zh":"代际鸿沟"}],"forms":[{"label":"复数（名词）","form":"gulfs"},{"label":"过去式（动词）","form":"gulfed"},{"label":"现在分词（动词）","form":"gulfing"},{"label":"复合名词（海湾国家）","form":"Gulf states"}],"derivatives":[{"word":"gulfed","pos":"adj.","zh":"被吞没的；陷入的"},{"word":"gulf-like","pos":"adj.","zh":"海湾状的"},{"word":"Gulf states","pos":"n.","zh":"海湾国家"},{"word":"Gulf Stream","pos":"n.","zh":"墨西哥湾流"}],"senses":[{"no":"01","title":"A large bay","titleCN":"海湾：大片伸入陆地的海面","definition":"a large area of sea partly enclosed by land","definitionCN":"部分被陆地围住的大片海域","example":"The river pours into the wide gulf.","exampleCN":"河流注入那片宽阔的海湾。","why":"Greek kolpos meant 'bosom or fold', and a gulf is the sea held in the land's lap.","whyCN":"希腊语词意为「怀抱、衣褶」，海湾就是被陆地抱在怀里的海。"},{"no":"02","title":"A wide separation","titleCN":"巨大分歧：两方之间的鸿沟","definition":"a great difference or lack of understanding between people or groups","definitionCN":"人或群体之间巨大的差异或隔阂","example":"A deep gulf opened between the two sides.","exampleCN":"双方之间出现了很深的鸿沟。","why":"A wide stretch of sea separates two shores, so the word pictures any wide separation.","whyCN":"宽阔的海水隔开两岸，因此这个词可比喻任何巨大的分隔。"},{"no":"03","title":"A deep opening","titleCN":"深渊：地面上的深坑","definition":"a deep opening in the earth or in a surface","definitionCN":"地面或表面上深深的开口","example":"A gulf opened in the road after the earthquake.","exampleCN":"地震后路上裂出一道深沟。","why":"The sea gap and a hole in the ground share the image of a deep, wide emptiness.","whyCN":"海上的间隔与地上的洞共享同一个深而宽的虚空意象。"},{"no":"04","title":"A gap between generations","titleCN":"代际或观念上的隔阂","definition":"a gap in experience or outlook between groups","definitionCN":"群体之间在经验或观念上的差距","example":"The generation gulf is wider than the family expected.","exampleCN":"代际鸿沟比这家人预想的更深。","why":"The geographic gulf becomes a social gap when two groups cannot reach each other.","whyCN":"两个群体无法相互抵达时，地理海湾就变成社会鸿沟。"},{"no":"05","title":"The Gulf region","titleCN":"海湾地区与海湾国家","definition":"the region around a particular gulf, especially the Persian Gulf","definitionCN":"某一海湾周边的地区，尤指波斯湾","example":"Trade across the Gulf has grown quickly.","exampleCN":"海湾地区的贸易增长很快。","why":"A named gulf gives its name to the whole region around it.","whyCN":"被命名的海湾把名字给了它周围的整个地区。"},{"no":"06","title":"A proper name for a sea","titleCN":"专名中的海湾","definition":"a capitalized name for a particular large bay","definitionCN":"某一特定大海湾的专名","example":"The Gulf of Mexico is warm and shallow.","exampleCN":"墨西哥湾温暖而水浅。","why":"Proper names fix the geographic sense to one body of water.","whyCN":"专名把地理义固定到一片具体水域。"},{"no":"07","title":"To swallow up","titleCN":"吞没（古旧动词用法）","definition":"to engulf or swallow something, an older verb use","definitionCN":"吞没或卷走某物，较旧的动词用法","example":"The flood gulfed the low fields.","exampleCN":"洪水吞没了低处的田地。","why":"The noun's deep opening became a verb for swallowing things into a gap.","whyCN":"名词的深口转为动词，表示把东西吞进缺口。"},{"no":"08","title":"An unbridgeable distance","titleCN":"难以跨越的距离或差距","definition":"a distance or difference so great that it cannot easily be crossed","definitionCN":"大到难以轻易跨越的距离或差异","example":"There is a gulf between the plan and the money available.","exampleCN":"计划与可用资金之间有巨大差距。","why":"The image of water too wide to cross gives the word its sense of an impossible distance.","whyCN":"宽到无法渡过的水，给这个词带来「不可能跨越的距离」之义。"}],"etymology":{"intro":{"en":"Gulf comes from Greek kolpos 'bosom, fold of the sea', through Late Latin and Italian into Old French. The Latin form is a loan. Dates are approximate.","cn":"该词来自希腊语表示「怀抱、海的衣褶」的词，经晚期拉丁语与意大利语进入古法语。拉丁形式是借词。年代均为约数。"},"items":[{"era":"GREEK KOLPOS","en":"kolpos meant 'bosom, fold, trough of the sea', and a gulf is the sea lying in a fold of land.","cn":"希腊语词意为「怀抱、衣褶、海的凹处」，海湾就是躺在陆地衣褶里的海。"},{"era":"LATE LATIN AND ITALIAN","en":"Late Latin and Italian passed the Greek word westward in altered forms; the Latin form is borrowed, not native.","cn":"晚期拉丁语与意大利语以变化后的形式把希腊词传向西边；拉丁形式是借入，并非本族。"},{"era":"OLD FRENCH","en":"Old French golfe brought the word into English, where it named large enclosed seas.","cn":"古法语把该词带入英语，用来指大片被陆地围住的海。"},{"era":"GEOGRAPHY","en":"The geographic sense settled on a large bay, usually larger than an ordinary bay and smaller than a sea.","cn":"地理义固定为大海湾，通常大于普通海湾而小于海。"},{"era":"METAPHOR","en":"The wide water gap became a picture of any wide separation, from generations to ideas.","cn":"宽阔的水上间隔成为任何巨大分隔的图景，从代际到观念。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper Greek origin): the pre-Greek root of kolpos is not agreed, and dates are approximate.","cn":"来源不确定（更深的希腊来源）：该希腊词在希腊语之前的词根无定论，年代为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike words with unrelated meanings; group two holds the coastal and separation words that overlap with gulf.","cn":"第一组是字形相近但意义无关的词；第二组是与海湾或分隔语义重叠的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"golf","ipa":"/ɡɒlf/","tag":"ball game","definition":"A game played with clubs and a small ball; the spelling is close but the word may come from a Dutch term for a club.","definitionCN":"指用球杆与小球的运动；拼写接近，但该词可能来自荷兰语表示球杆的词。"},{"word":"gully","ipa":"/ˈɡʌli/","tag":"water-cut channel","definition":"A channel cut by water on a hillside; it is a narrow groove, not a wide sea.","definitionCN":"指山坡上被水切出的沟；它是窄沟，不是宽阔的海。"},{"word":"gull","ipa":"/ɡʌl/","tag":"seabird","definition":"A seabird with grey and white plumage; it shares letters and habitat but has a separate origin.","definitionCN":"指灰白羽色的海鸟；共享字母与栖息环境，但来源不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bay","ipa":"/beɪ/","tag":"smaller inlet","definition":"A part of the sea partly enclosed by land; it is usually smaller than a gulf.","definitionCN":"指部分被陆地围住的海面；通常比海湾小。"},{"word":"bight","ipa":"/baɪt/","tag":"broad curve","definition":"A broad curve or shallow bay in a coastline; it is a bend of the shore rather than a deep enclosure.","definitionCN":"指海岸线上宽阔的弯或浅湾；它是岸线的弯曲，而非深围的水面。"},{"word":"chasm","ipa":"/ˈkæzəm/","tag":"deep gap","definition":"A deep crack or gap in the earth; it is the land version of a gulf's emptiness.","definitionCN":"指地面上的深裂口；它是海湾虚空感的陆地版本。"},{"word":"gap","ipa":"/ɡæp/","tag":"general difference","definition":"An empty space or a difference between things; it is the general word that gulf intensifies.","definitionCN":"指空处或事物之间的差距；它是通用词，海湾义使其程度加重。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root means 'bosom': the sea lies in the folded arm of the land.","cn":"词根意为「怀抱」：海躺在陆地弯起的手臂里。"},{"en":"The family runs gulf, gulfs, gulfed, gulf-like and Gulf states.","cn":"同族词包括本词、复数、被吞没形容词、海湾状形容词与海湾国家。"},{"en":"Fixed phrases mark the senses: the Gulf of Mexico, bridge the gulf, the Gulf states.","cn":"固定搭配标出各义项：墨西哥湾、弥合鸿沟、海湾国家。"},{"en":"The metaphor is simple: water too wide to cross stands for any difference too great to close.","cn":"比喻很简单：宽到渡不过的水，代表大到合不拢的差异。"},{"en":"The proper name with a capital letter points to one particular sea, usually the Persian Gulf or the Gulf of Mexico.","cn":"大写专名指向某一片具体的海，通常指波斯湾或墨西哥湾。"}],"abstract":[{"en":"Picture two people at opposite ends of a very long table.","cn":"想象两个人坐在一张极长桌子的两端。"},{"en":"Picture a canyon filled with air instead of water.","cn":"想象一条峡谷里装的不是水而是空气。"},{"en":"Picture a misunderstanding wide enough to need a bridge.","cn":"想象一个宽到需要架桥的误解。"}]},"examples":[{"en":"The gulf is warm, shallow and rich in fish.","cn":"这片海湾温暖、水浅且鱼产丰富。"},{"en":"Both sides worked hard to bridge the gulf in trust.","cn":"双方都努力弥合信任上的鸿沟。"},{"en":"The gulf between the two plans is mostly about cost.","cn":"两个方案之间的差距主要在成本。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「高夫」：高夫站在岸边，看着一大片海水凹进陆地——海湾。","word":"gulf"},"root":"希腊语 kolpos「怀抱、衣褶、海的凹处」，经晚期拉丁语与意大利语入古法语，再进英语；拉丁形式属借词。","sensesIntro":{"en":"Eight senses follow one wide opening: sea held in a fold of land. The opening then becomes any wide separation, a deep hole, a social gap, a named region, a proper sea name, a verb for swallowing and an impossible distance.","cn":"八个义项沿同一个宽大开口展开：被陆地衣褶抱住的海。这个开口随后变成任何巨大分隔、深坑、社会差距、地区名、专名海域、吞没动词与无法跨越的距离。"},"semanticMap":{"core":{"en":"CORE IMAGE: a broad arm of sea folded into the land, wide enough to keep two shores apart.","cn":"核心意象：一大弯被陆地抱住的海洋，宽到足以隔开两岸。"},"chain":["GREAT BAY","WIDE SEPARATION","DEEP OPENING","SOCIAL GAP","NAMED REGION","SWALLOWED UP"],"branches":[{"senses":"S1 · S5 · S6","en":"GEOGRAPHY: the large bay, the region around it and its proper name are one place.","cn":"地理：大海湾、周边地区与它的专名是同一个地方。"},{"senses":"S2 · S8","en":"SEPARATION: a difference between people and a distance too great to cross share the wide water.","cn":"分隔：人与人之间的差异与无法跨越的距离共享这片宽水。"},{"senses":"S4","en":"SOCIAL GAP: two generations that cannot reach each other stand on opposite shores.","cn":"社会差距：无法相互抵达的两代人站在两岸。"},{"senses":"S3","en":"DEPTH: a hole in the ground repeats the gulf's empty depth.","cn":"深度：地上的洞重复了海湾的空与深。"},{"senses":"S7","en":"VERB: the open mouth of the gulf becomes an act of swallowing.","cn":"动词：海湾的大口变成吞没的动作。"}]},"affixes":{"intro":{"en":"Gulf is a Greek loan that passed through Latin, Italian and French; its English family is mostly compounds and proper names.","cn":"该词是希腊语借词，经拉丁语、意大利语与法语传入；英语词族多为复合词与专名。"},"latinIntro":{"en":"The Latin form is itself a loan from Greek, so only that borrowed form is listed; there is no native Latin root family.","cn":"拉丁形式本身借自希腊语，因此只列这个借入形式；没有本族拉丁词根词族。"},"items":[{"word":"kolpos","structure":"Greek kolpos (noun, 'bosom, fold of the sea')","meaning":"bosom; sea fold","meaningCN":"怀抱；海的衣褶","example":"The Greek word pictured the sea in the land's lap.","exampleCN":"这个希腊词把海想象成躺在陆地怀里。"},{"word":"colfus","structure":"Late Latin colfus (noun, loan from Greek)","meaning":"gulf","meaningCN":"海湾","example":"The Late Latin form carried the word westward.","exampleCN":"晚期拉丁形式把该词传向西边。"},{"word":"golfe","structure":"Old French golfe (noun)","meaning":"gulf","meaningCN":"海湾","example":"Old French passed the word into English.","exampleCN":"古法语把该词传入英语。"},{"word":"gulf","structure":"gulf (English noun and verb)","meaning":"large bay; to swallow","meaningCN":"大海湾；吞没","example":"The river pours into the wide gulf.","exampleCN":"河流注入宽阔的海湾。"},{"word":"gulfs","structure":"gulf + -s (plural)","meaning":"more than one gulf","meaningCN":"多个海湾","example":"Two gulfs cut into the southern coast.","exampleCN":"南岸切进两个海湾。"},{"word":"gulfed","structure":"gulf + -ed (past participle)","meaning":"swallowed up","meaningCN":"被吞没的","example":"The low fields were gulfed by the flood.","exampleCN":"低田被洪水吞没。"},{"word":"gulf-like","structure":"gulf + -like (resembling)","meaning":"resembling a gulf","meaningCN":"海湾状的","example":"A gulf-like opening marks the old harbour.","exampleCN":"一处海湾状开口标出旧港位置。"},{"word":"the Gulf","structure":"proper noun (geographic)","meaning":"a particular gulf region","meaningCN":"某一海湾地区","example":"Trade across the Gulf has grown quickly.","exampleCN":"海湾地区的贸易增长很快。"}],"latinEntries":[{"word":"colfus","structure":"colfus, colfi (m., second declension, Late Latin loan from Greek)","meaning":"gulf, bay","meaningCN":"海湾；大海湾"}]}},{"word":"harbor","ipa_uk":"/ˈhɑːbə/","ipa_us":"/ˈhɑːrbər/","definition_zh":"港口；避难所；藏匿；怀有（想法或情感）；停泊","definition_en":"a sheltered place where ships anchor, or to shelter, hide or hold something","core_image":"一圈防波堤把水面围住，船在里面安稳停靠","scene":"货船在黎明时驶入港口。The cargo ships entered the harbor at dawn.","sceneCN":"这里该词指「供船只停靠的港区」（第 1 个义项：避风停泊的水域）；句意为货船在黎明时驶入港口。","pos":[{"tag":"n.","zh":"港口；避难所；庇护处"},{"tag":"vt.","zh":"藏匿；怀有；庇护"},{"tag":"vi.","zh":"停泊；进港"}],"collocations":[{"phrase":"a natural harbor","zh":"天然良港"},{"phrase":"a safe harbor","zh":"安全港；避风港"},{"phrase":"harbor a grudge","zh":"心怀怨恨"},{"phrase":"harbor doubts","zh":"心存疑虑"},{"phrase":"enter the harbor","zh":"进港"},{"phrase":"harbor refugees","zh":"收留难民"}],"forms":[{"label":"复数（名词）","form":"harbors"},{"label":"三单（动词）","form":"harbors"},{"label":"过去式","form":"harbored"},{"label":"过去分词","form":"harbored"},{"label":"现在分词","form":"harboring"}],"derivatives":[{"word":"harborage","pos":"n.","zh":"庇护所；停泊处"},{"word":"harborer","pos":"n.","zh":"窝藏者；庇护者"},{"word":"harborside","pos":"adj.","zh":"港边的"},{"word":"safe harbor","pos":"n.","zh":"安全港；避风港"}],"senses":[{"no":"01","title":"A sheltered port","titleCN":"港口：供船只避风停靠的水域","definition":"a sheltered area of water where ships can anchor safely","definitionCN":"船只可安全停泊的避风水域","example":"The cargo ships entered the harbor at dawn.","exampleCN":"货船在黎明时驶入港口。","why":"Old English joined 'army' and 'shelter', and the shelter later became a shelter for ships.","whyCN":"古英语把「军队」与「庇护」组合，后来这种庇护变成船只的庇护。"},{"no":"02","title":"A place of refuge","titleCN":"避难所：安全的庇护处","definition":"a place that offers safety or rest from danger","definitionCN":"提供安全或让人避开危险休息的地方","example":"The chapel became a harbor for travellers in the storm.","exampleCN":"小教堂成了旅人在暴风雨中的避难所。","why":"A port protects ships from rough water; the same word extends to any protecting place.","whyCN":"港口保护船只免受风浪，同一个词扩展到任何庇护之处。"},{"no":"03","title":"To hide someone or something","titleCN":"藏匿、窝藏","definition":"to give shelter to a person or thing, often secretly","definitionCN":"为某人或某物提供庇护，常含秘密之意","example":"The barn harbored stolen tools for a week.","exampleCN":"谷仓把偷来的工具藏了一个星期。","why":"Sheltering becomes hiding when the purpose is secrecy.","whyCN":"当目的是保密时，庇护就变成藏匿。"},{"no":"04","title":"To hold a feeling or idea","titleCN":"怀有想法或情感","definition":"to keep a thought or feeling in the mind over time","definitionCN":"在心里长期保留某种想法或情感","example":"She harbored a quiet hope of returning.","exampleCN":"她心里悄悄怀着回去的希望。","why":"The mind becomes a shelter that keeps a feeling safe inside it.","whyCN":"心成为一个庇护所，把情感安全地保存在里面。"},{"no":"05","title":"To anchor in a port","titleCN":"停泊、进港","definition":"to bring a ship into a harbor or to lie there at anchor","definitionCN":"把船驶入港口或停泊在那里","example":"The fleet harbored before the storm reached the coast.","exampleCN":"船队在暴风雨抵达海岸前进港停泊。","why":"The noun became a verb for the action of using the shelter.","whyCN":"名词转为动词，表示使用这个庇护处的动作。"},{"no":"06","title":"The port area","titleCN":"港区与港口城市","definition":"the town or district around a port","definitionCN":"港口周边的城镇或区域","example":"The harbor district is busy before sunrise.","exampleCN":"港区在日出前就忙碌起来。","why":"People and trade gather around the shelter, so the word names the district as well as the water.","whyCN":"人与贸易聚集在庇护处周围，因此这个词也指那片区域。"},{"no":"07","title":"To give refuge to people","titleCN":"收留、庇护他人","definition":"to protect and shelter people in need","definitionCN":"保护并收留需要帮助的人","example":"The town harbored families displaced by the flood.","exampleCN":"小镇收留了因洪水流离失所的家庭。","why":"The human sense of shelter is the oldest moral use of the word.","whyCN":"收留人的意义是这个词最古老的道德用法。"},{"no":"08","title":"To contain a virus or program","titleCN":"藏有病毒或程序","definition":"to carry a disease, fault or hidden program without showing it","definitionCN":"携带疾病、缺陷或隐藏程序而不显露","example":"The file may harbor a virus.","exampleCN":"这个文件可能藏有病毒。","why":"A hidden thing kept inside is another version of sheltering, now in biology or computing.","whyCN":"被藏在里面的东西是庇护的另一版本，如今用于生物或计算机。"}],"etymology":{"intro":{"en":"Harbor is Old English, from here 'army' plus beorg 'shelter'. The spelling was later influenced by French. Dates are approximate.","cn":"该词来自古英语，由表示「军队」与表示「庇护」的两个词构成；拼写后来受法语影响。年代均为约数。"},"items":[{"era":"OLD ENGLISH HEREBEORG","en":"herebeorg joined here 'army' and beorg 'shelter, protection', first naming a place where an army could lodge.","cn":"古英语把「军队」与「庇护、保护」组合，最初指军队可以驻扎的地方。"},{"era":"OLD ENGLISH BEORGAN","en":"beorgan 'to protect, save' is the verb behind the shelter noun.","cn":"表示「保护、拯救」的古英语动词是「庇护」名词背后的动词。"},{"era":"SHIFT TO SHIPS","en":"The military sense faded, and the word came to mean a shelter for ships and then for people.","cn":"军事义淡化后，这个词转为船只的庇护处，再转为人的庇护处。"},{"era":"SPELLING","en":"The ending changed under French influence, producing the modern spelling with a final -or.","cn":"词尾在法语影响下改变，形成现代的拼写形式。"},{"era":"VERB SENSES","en":"The noun became a verb for sheltering, then for holding a thought, a disease or a hidden program.","cn":"名词转为动词，先指庇护，再指怀有想法、携带疾病或藏有隐藏程序。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date of the nautical sense): the shift from army shelter to port is not precisely dated.","cn":"来源不确定（航海义的首见年代）：从军队庇护转为港口的确切年代无定论。"}]},"similar":{"note":{"en":"Group one holds look-alike words, including the British spelling; group two holds the port and refuge words that overlap with harbor.","cn":"第一组是形近词，其中包含英式拼写；第二组是与港口或庇护语义重叠的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"harbour","ipa":"/ˈhɑːbə/","tag":"British spelling","definition":"The British spelling of the same word; the meaning is identical, only the spelling differs.","definitionCN":"这是同一个词的英式拼写；意义完全相同，只有拼写不同。"},{"word":"harbinger","ipa":"/ˈhɑːbɪndʒə/","tag":"forerunner","definition":"A sign or person that announces what is coming; it looks close but comes from a different French word.","definitionCN":"指预告某事即将到来的征兆或人；形似但来自另一个法语词。"},{"word":"arbor","ipa":"/ˈɑːbə/","tag":"garden shelter","definition":"A shaded garden shelter or a tree; it comes from Latin for 'tree', not from the English word.","definitionCN":"指花园中的荫棚或树；来自拉丁语表示「树」的词，与本词无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"port","ipa":"/pɔːt/","tag":"trade harbour","definition":"A place where ships load and unload; it stresses trade and facilities, while harbor stresses shelter.","definitionCN":"指船只装卸货物的地方；强调贸易与设施，而本词强调庇护。"},{"word":"haven","ipa":"/ˈheɪvn/","tag":"safe place","definition":"A safe place for ships or people; it is close to harbor but often more literary.","definitionCN":"指船只或人的安全处；与本词接近，但常更带文学色彩。"},{"word":"dock","ipa":"/dɒk/","tag":"ship berth","definition":"A structure where a ship is tied to load or repair; it is a built berth, not a sheltered water area.","definitionCN":"指船只系泊装卸或修理的结构；它是修建的泊位，不是避风水域。"},{"word":"refuge","ipa":"/ˈrefjuːdʒ/","tag":"protection","definition":"A place or state of protection from danger; it covers the human sense without the nautical image.","definitionCN":"指免受危险的地方或状态；可表达庇护义，但不带航海意象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The two old halves meant 'army' and 'shelter': first a camp, then a port.","cn":"两个古老成分意为「军队」与「庇护」：先是营地，后是港口。"},{"en":"The family runs harbor, harbors, harborage, harborer and harborside.","cn":"同族词包括本词、其复数、庇护所、窝藏者与港边形容词。"},{"en":"Fixed phrases mark the senses: a natural harbor, harbor a grudge, harbor doubts, harbor refugees.","cn":"固定搭配标出各义项：天然良港、心怀怨恨、心存疑虑、收留难民。"},{"en":"The verb keeps the image: something is kept safe inside, whether a ship, a hope or a virus.","cn":"动词保留这个意象：某物被安全地保存在里面，无论是船、希望还是病毒。"},{"en":"The British spelling adds a u, but the meaning does not change.","cn":"英式拼写多一个字母，但意义不变。"}],"abstract":[{"en":"Picture two hands cupped around a small flame to keep the wind off.","cn":"想象两只手捧住一小簇火苗，替它挡风。"},{"en":"Picture a mind keeping an old anger in a locked drawer.","cn":"想象一颗心把旧怨锁在抽屉里。"},{"en":"Picture a curved wall of stone holding calm water inside.","cn":"想象一道弧形石墙把平静的水围在里面。"}]},"examples":[{"en":"The old harbor now holds fishing boats and a small museum.","cn":"旧港如今停着渔船，还有一座小博物馆。"},{"en":"He still harbors a grudge against the former partner.","cn":"他对从前的合伙人仍心怀怨恨。"},{"en":"The shelter harbored dozens of families during the storm.","cn":"暴风雨期间这处避难所收留了几十个家庭。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「哈勃」：哈勃把船开进避风的港湾——港口、庇护。","word":"harbor"},"root":"古英语 here「军队」+ beorg「庇护、保护」构成，最初指军队驻扎处；后转为船只与人的庇护处，拼写受法语影响。英语 harbor。","sensesIntro":{"en":"Eight senses follow one shelter: a place that keeps something safe. The shelter is first water for ships, then any refuge, a hiding place, the mind holding a feeling, an anchoring action, a port district, a home for people and a container for disease or code.","cn":"八个义项沿同一个庇护展开：让某物安全的地方。这个庇护先是船只的水域，再是任何避难所、藏匿处、保存情感的心、停泊动作、港区、人的收留处与疾病或代码的容器。"},"semanticMap":{"core":{"en":"CORE IMAGE: a curved wall holding calm water, with ships safe inside and rough sea outside.","cn":"核心意象：一道弧形墙围住平静的水，船在里面安全，外面是风浪。"},"chain":["SHELTERED PORT","REFUGE","HIDING PLACE","HELD FEELING","ANCHORING","CONTAINED THING"],"branches":[{"senses":"S1 · S6","en":"PORT: the sheltered water and the busy district around it.","cn":"港口：避风水域与其周边繁忙的港区。"},{"senses":"S5","en":"ANCHORING: the noun becomes the act of bringing a ship into shelter.","cn":"停泊：名词转为把船驶入庇护处的动作。"},{"senses":"S2 · S7","en":"REFUGE: the same shelter protects travellers and displaced families.","cn":"庇护：同一庇护处保护旅人与流离失所的家庭。"},{"senses":"S3 · S8","en":"CONTAINMENT: stolen goods, a virus or a hidden program can all be kept inside.","cn":"容纳：赃物、病毒或隐藏程序都可以被藏在里面。"},{"senses":"S4","en":"MIND: a feeling is kept safe in the mind's shelter.","cn":"心：情感被安全地保存在心的庇护所里。"}]},"affixes":{"intro":{"en":"Harbor is an Old English compound; both halves are native Germanic words, and the final spelling changed later.","cn":"该词是古英语复合词；两半都是本族日耳曼语词，词尾拼写后来改变。"},"latinIntro":{"en":"There is no Latin root: the word is Old English, and French only influenced the spelling, so the Latin entry list is empty.","cn":"没有拉丁词根：该词是古英语，法语只影响拼写，因此拉丁词条列表留空。"},"items":[{"word":"here","structure":"Old English here (noun, 'army')","meaning":"army","meaningCN":"军队","example":"The first half named the army that needed shelter.","exampleCN":"前半部分指需要庇护的军队。"},{"word":"beorg","structure":"Old English beorg (noun, 'shelter, protection')","meaning":"shelter","meaningCN":"庇护；保护","example":"The second half supplied the protecting place.","exampleCN":"后半部分提供保护之处。"},{"word":"beorgan","structure":"Old English beorgan (verb, 'to protect')","meaning":"to protect","meaningCN":"保护","example":"The verb behind the noun meant to keep safe.","exampleCN":"名词背后的动词意为使安全。"},{"word":"harbor","structure":"here + beorg (Old English compound)","meaning":"shelter; a port","meaningCN":"庇护所；港口","example":"The cargo ships entered the harbor at dawn.","exampleCN":"货船在黎明时驶入港口。"},{"word":"harbors","structure":"harbor + -s (plural or third person)","meaning":"more than one harbor","meaningCN":"多个港口","example":"Two harbors serve the island.","exampleCN":"两座港口为这座岛服务。"},{"word":"harborage","structure":"harbor + -age (place or state)","meaning":"shelter, anchorage","meaningCN":"庇护所；停泊处","example":"The bay offers good harborage.","exampleCN":"这个湾提供了良好的停泊处。"},{"word":"harborer","structure":"harbor + -er (person)","meaning":"one who shelters","meaningCN":"窝藏者；庇护者","example":"The harborer of the stolen goods was fined.","exampleCN":"窝藏赃物者被罚款。"},{"word":"harborside","structure":"harbor + side (compound)","meaning":"beside a harbor","meaningCN":"港边的","example":"Harborside cafés open early.","exampleCN":"港边咖啡馆很早开门。"}],"latinEntries":[]}},{"word":"delta","ipa_uk":"/ˈdeltə/","ipa_us":"/ˈdeltə/","definition_zh":"三角洲；希腊字母第四个字母；三角形物；变化量；三角翼","definition_en":"the triangular land at a river's mouth, or a triangular shape, letter or amount of change","core_image":"河流入海处分成许多支流，泥沙堆出一个三角形","scene":"河流在入海处分成许多支流，铺开成三角洲。The river splits into many arms across the delta.","sceneCN":"这里该词指「河流入海处由泥沙堆成的三角形陆地」（第 1 个义项：三角洲）；句意为河流分成许多支流，铺展成三角洲。","pos":[{"tag":"n.","zh":"三角洲；三角符号；变化量"}],"collocations":[{"phrase":"the Nile Delta","zh":"尼罗河三角洲"},{"phrase":"a river delta","zh":"河流三角洲"},{"phrase":"delta wing","zh":"三角翼"},{"phrase":"a delta variant","zh":"德尔塔变体"},{"phrase":"a delta change","zh":"变化量"},{"phrase":"the delta region","zh":"三角洲地区"}],"forms":[{"label":"复数（名词）","form":"deltas"},{"label":"形容词（三角洲的）","form":"deltaic"},{"label":"复合名词（三角洲平原）","form":"deltaic plain"}],"derivatives":[{"word":"deltaic","pos":"adj.","zh":"三角洲的"},{"word":"deltaic plain","pos":"n.","zh":"三角洲平原"},{"word":"delta front","pos":"n.","zh":"三角洲前缘"},{"word":"delta wing","pos":"n.","zh":"三角翼"}],"senses":[{"no":"01","title":"Triangular land at a river mouth","titleCN":"三角洲：河流入海处的三角形陆地","definition":"the triangular area of sediment built where a river enters a sea or lake","definitionCN":"河流入海或入湖处由沉积物堆成的三角形区域","example":"The river splits into many arms across the delta.","exampleCN":"河流分成许多支流，铺展成三角洲。","why":"Greek geographers saw the triangular mouth of the Nile and named it after the fourth letter, which has the same shape.","whyCN":"希腊地理学者看到尼罗河口的三角形，便用形状相同的第四个字母为它命名。"},{"no":"02","title":"The fourth Greek letter","titleCN":"希腊字母表的第四个字母","definition":"the fourth letter of the Greek alphabet, written as a triangle","definitionCN":"希腊字母表的第四个字母，写作三角形","example":"The symbol delta marks the change in a formula.","exampleCN":"这个符号在公式中标记变化量。","why":"The letter itself is triangular, which is why it could name the landform.","whyCN":"这个字母本身就是三角形，因此能给这种地形命名。"},{"no":"03","title":"A triangular object or mark","titleCN":"三角形物或三角标志","definition":"something shaped like a triangle or marked with one","definitionCN":"三角形的东西或带三角标记之物","example":"A delta sign warns of a changing road surface.","exampleCN":"三角标志提醒路面正在变化。","why":"The letter's shape became a general name for triangular marks.","whyCN":"字母的形状成为三角形标记的通称。"},{"no":"04","title":"A triangular aircraft wing","titleCN":"飞机三角翼","definition":"a triangular wing shape used on some aircraft","definitionCN":"某些飞机采用的三角形机翼","example":"The delta wing gives lift at high speed.","exampleCN":"三角翼在高速时提供升力。","why":"Aviation named the wing after the letter's outline.","whyCN":"航空按字母的轮廓命名这种机翼。"},{"no":"05","title":"A change in mathematics","titleCN":"数学与物理中的变化量","definition":"a finite amount of change in a variable, shown by the letter","definitionCN":"变量有限的变化量，用该字母表示","example":"The equation uses delta for a small change in time.","exampleCN":"方程用该符号表示时间的微小变化。","why":"Mathematics adopted the letter as a standard sign for difference or change.","whyCN":"数学采用这个字母作为差异或变化的标准符号。"},{"no":"06","title":"Delta wetlands","titleCN":"三角洲湿地生态","definition":"the wet, sediment-rich environment of a delta","definitionCN":"三角洲含泥沙丰富的湿地环境","example":"The delta supports reeds, fish and nesting birds.","exampleCN":"三角洲养育着芦苇、鱼类与筑巢的鸟。","why":"Fresh sediment and shallow water make a delta one of the richest habitats.","whyCN":"新鲜泥沙与浅水使三角洲成为最富饶的栖息地之一。"},{"no":"07","title":"The delta plain","titleCN":"三角洲平原与沉积体","definition":"the low, built-up plain of sediment at a river mouth","definitionCN":"河口处由沉积物堆高的低平原","example":"Farmers grow rice on the delta plain.","exampleCN":"农民在三角洲平原上种稻。","why":"Geology treats the deposit as a body of sediment with its own layers and front.","whyCN":"地质学把这片沉积当作有自身层次与前缘的沉积体。"},{"no":"08","title":"The delta region","titleCN":"三角洲地区","definition":"the settled region around a delta","definitionCN":"三角洲周边的居住地区","example":"Cities in the delta region are sinking as the ground compacts.","exampleCN":"三角洲地区的城市因地面压实而下沉。","why":"Rich soil and water make deltas crowded, so the word also names a human region.","whyCN":"肥沃土壤与水源使三角洲人口密集，因此这个词也指人文区域。"}],"etymology":{"intro":{"en":"Delta is the fourth letter of the Greek alphabet, named after a Phoenician letter shaped like a triangle; Greek geographers applied it to the Nile mouth. Dates are approximate.","cn":"该词是希腊字母表的第四个字母，得名于一个三角形形状的腓尼基字母；希腊地理学者把它用于尼罗河口。年代均为约数。"},"items":[{"era":"GREEK LETTER","en":"delta is the fourth letter of the Greek alphabet, and its capital form is a triangle.","cn":"这是希腊字母表的第四个字母，其大写形式是一个三角形。"},{"era":"PHOENICIAN SOURCE","en":"The letter goes back to a Phoenician letter called daleth, meaning 'door', whose outline was triangular.","cn":"这个字母可追溯到腓尼基语中一个意为「门」的字母，其轮廓是三角形。"},{"era":"NILE DELTA","en":"Greek geographers called the triangular mouth of the Nile the delta, and the name spread to similar river mouths.","cn":"希腊地理学者把尼罗河的三角形河口称为这个名称，它随后传播到类似的河口。"},{"era":"MATHEMATICS","en":"Mathematics adopted the letter as a standard sign for a finite change or difference.","cn":"数学采用这个字母作为有限变化或差异的标准符号。"},{"era":"AVIATION","en":"Aviation named a triangular wing after the letter's outline.","cn":"航空按字母的轮廓命名三角形机翼。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (the Phoenician link): the deeper origin of the letter name is not fully settled, and dates are approximate.","cn":"来源不确定（腓尼基环节）：字母名称的更早来历尚无定论，年代为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike words from the same letter or triangle idea; group two holds the river-mouth landforms often compared with a delta.","cn":"第一组是来自同一字母或三角形观念的形近词；第二组是常与三角洲比较的河口地形。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deltoid","ipa":"/ˈdeltɔɪd/","tag":"triangular muscle","definition":"A triangular shoulder muscle; the name comes from the letter's shape, not from a river.","definitionCN":"指三角形的肩部肌肉；名称来自字母形状，与河流无关。"},{"word":"deltaic","ipa":"/delˈteɪɪk/","tag":"adjective form","definition":"Relating to a river delta; it is the adjective while the noun names the landform.","definitionCN":"指与河流三角洲有关的；它是形容词，而名词指地形。"},{"word":"deltas","ipa":"/ˈdeltəz/","tag":"plural form","definition":"The plural of the noun, used for more than one delta or letter.","definitionCN":"名词复数，用于多个三角洲或字母。"}]},{"heading":"NEAR MEANING","entries":[{"word":"estuary","ipa":"/ˈestjuəri/","tag":"tidal river mouth","definition":"The tidal mouth of a river where fresh and salt water meet; a delta is built of sediment, while an estuary is scoured by tides.","definitionCN":"指淡水与咸水相遇的潮汐河口；三角洲由沉积物堆成，河口湾则受潮流冲刷。"},{"word":"alluvial fan","ipa":"/əˈluːviəl fæn/","tag":"fan of sediment","definition":"A fan-shaped deposit where a stream leaves a mountain; it is built on land, not at the sea.","definitionCN":"指溪流离开山地时形成的扇形沉积；它在陆上堆积，不在海边。"},{"word":"floodplain","ipa":"/ˈflʌdpleɪn/","tag":"river-side plain","definition":"Flat land beside a river that floods; it is along the channel, not at its mouth.","definitionCN":"指河边会泛滥的平地；它沿河道分布，不在河口。"},{"word":"river mouth","ipa":"/ˈrɪvə maʊθ/","tag":"general term","definition":"The place where a river meets a larger body of water; it is the general term for the location.","definitionCN":"指河流与较大水域相接之处；它是这个位置的通用说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The letter is a triangle, and the landform copies the letter.","cn":"这个字母是三角形，而地形复制了这个字母。"},{"en":"The family runs delta, deltas, deltaic, deltaic plain and delta wing.","cn":"同族词包括本词、复数、三角洲形容词、三角洲平原与三角翼。"},{"en":"Fixed phrases mark the senses: the Nile Delta, a river delta, delta wing, a delta change.","cn":"固定搭配标出各义项：尼罗河三角洲、河流三角洲、三角翼、变化量。"},{"en":"Mathematics uses the letter for a small change, which is why formulas are full of deltas.","cn":"数学用这个字母表示微小变化，因此公式里常见它。"},{"en":"A delta is built by sediment, while an estuary is carved by tides.","cn":"三角洲由沉积物堆成，河口湾则由潮流冲刷。"}],"abstract":[{"en":"Picture a triangle of sand spreading into blue water.","cn":"想象一片三角形沙地铺进蓝色水中。"},{"en":"Picture a river opening its hand into many fingers at the sea.","cn":"想象一条河在海边张开手掌，分成许多手指。"},{"en":"Picture a small change marked in the margin of an equation.","cn":"想象方程边注里标出的一个小变化。"}]},"examples":[{"en":"The delta grows every year as the river drops new sediment.","cn":"河流每年带来新泥沙，三角洲因此不断扩大。"},{"en":"The delta wing keeps the aircraft stable at high speed.","cn":"三角翼让飞机在高速时保持稳定。"},{"en":"A delta marks the difference between the two readings.","cn":"这个符号标出两次读数之间的差值。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「德尔塔」：希腊字母第几？第四，形状像三角形，正好像河口三角洲。","word":"delta"},"root":"希腊字母表第四个字母，其大写为三角形，源自腓尼基语意为「门」的字母；希腊地理学者用它命名尼罗河的三角形河口。","sensesIntro":{"en":"Eight senses follow one triangle. The shape is a letter, a sign, a wing and a mark; the landform at a river mouth gives the wetland, the sediment plain and the settled region.","cn":"八个义项沿同一个三角形展开。这个形状是字母、符号、机翼与标记；河口的三角形地形则给出湿地、沉积平原与居住地区。"},"semanticMap":{"core":{"en":"CORE IMAGE: a triangle of sediment opening into water, the same outline as the fourth Greek letter.","cn":"核心意象：一片三角形沉积物伸进水中，轮廓与希腊第四个字母相同。"},"chain":["RIVER-MOUTH TRIANGLE","GREEK LETTER","TRIANGULAR MARK","DELTA WING","AMOUNT OF CHANGE","DELTA REGION"],"branches":[{"senses":"S1 · S6 · S7","en":"LANDFORM: the river mouth builds a wetland and a sedimentary plain.","cn":"地形：河口堆出湿地与沉积平原。"},{"senses":"S2 · S3","en":"SYMBOL: the letter and any triangular mark share the shape.","cn":"符号：字母与任何三角标记共享这个形状。"},{"senses":"S4","en":"WING: aviation copies the triangle for a wing plan.","cn":"机翼：航空把三角形复制为机翼平面。"},{"senses":"S5","en":"CHANGE: mathematics uses the letter for a finite difference.","cn":"变化：数学用这个字母表示有限差值。"},{"senses":"S8","en":"REGION: rich soil and water make the delta a settled place.","cn":"地区：肥沃土壤与水源使三角洲成为居住地。"}]},"affixes":{"intro":{"en":"Delta is a letter name of Phoenician origin, not a Latin root; most English uses are compounds or technical terms.","cn":"该词是源自腓尼基语的字母名称，并非拉丁词根；英语用法多为复合词或技术术语。"},"latinIntro":{"en":"There is no native Latin root: Latin only borrowed the Greek letter name, so the Latin entry list is empty.","cn":"没有本族拉丁词根：拉丁语只借入了这个希腊字母名称，因此拉丁词条列表留空。"},"items":[{"word":"daleth","structure":"Phoenician daleth (letter name, 'door')","meaning":"door; the letter name","meaningCN":"门；字母名称","example":"The old letter name described a triangular outline.","exampleCN":"这个古老字母名描述三角形轮廓。"},{"word":"delta","structure":"Greek delta (fourth letter)","meaning":"the fourth Greek letter","meaningCN":"希腊第四个字母","example":"The river splits into many arms across the delta.","exampleCN":"河流分成许多支流，铺展成三角洲。"},{"word":"deltas","structure":"delta + -s (plural)","meaning":"more than one delta","meaningCN":"多个三角洲","example":"The coast has three large deltas.","exampleCN":"这段海岸有三个大三角洲。"},{"word":"deltaic","structure":"delta + -ic (relating to)","meaning":"of a delta","meaningCN":"三角洲的","example":"Deltaic sediment is fine and rich.","exampleCN":"三角洲沉积细而肥沃。"},{"word":"deltaic plain","structure":"deltaic + plain (compound term)","meaning":"the low plain of a delta","meaningCN":"三角洲平原","example":"Rice grows on the deltaic plain.","exampleCN":"稻米种在三角洲平原上。"},{"word":"delta front","structure":"delta + front (geological term)","meaning":"the seaward edge of a delta","meaningCN":"三角洲前缘","example":"Waves rework the delta front.","exampleCN":"波浪改造三角洲前缘。"},{"word":"delta wing","structure":"delta + wing (aviation term)","meaning":"a triangular wing","meaningCN":"三角翼","example":"The delta wing gives lift at high speed.","exampleCN":"三角翼在高速时提供升力。"},{"word":"delta variant","structure":"delta + variant (naming term)","meaning":"a named variant","meaningCN":"以该字母命名的变体","example":"The delta variant spread quickly.","exampleCN":"这一变体传播得很快。"}],"latinEntries":[]}},{"word":"watershed","ipa_uk":"/ˈwɔːtəʃed/","ipa_us":"/ˈwɔːtərʃed/","definition_zh":"分水岭；流域；转折点；分界线","definition_en":"the ridge that separates rivers flowing in different directions, or a turning point","core_image":"山脊像屋脊一样把雨水分到两侧，各自流向不同的河","scene":"这道山脊是两条河流流域之间的分水岭。The ridge marks the watershed between two river systems.","sceneCN":"这里该词指「分开不同河流流域的山脊」（第 1 个义项：分水线所在的高地）；句意为这道山脊是两条河流流域之间的分水岭。","pos":[{"tag":"n.","zh":"分水岭；流域；转折点；分界线"}],"collocations":[{"phrase":"a watershed moment","zh":"转折时刻"},{"phrase":"the watershed of a river","zh":"河流的分水岭"},{"phrase":"a watershed year","zh":"转折之年"},{"phrase":"watershed management","zh":"流域管理"},{"phrase":"cross the watershed","zh":"越过分水岭"},{"phrase":"a watershed boundary","zh":"流域边界"}],"forms":[{"label":"复数（名词）","form":"watersheds"},{"label":"复合名词（转折时刻）","form":"watershed moment"},{"label":"复合名词（流域管理）","form":"watershed management"}],"derivatives":[{"word":"watershed moment","pos":"n.","zh":"转折时刻"},{"word":"watershed year","pos":"n.","zh":"转折之年"},{"word":"watershed management","pos":"n.","zh":"流域管理"},{"word":"watershed boundary","pos":"n.","zh":"流域边界"}],"senses":[{"no":"01","title":"The ridge that divides drainage","titleCN":"分水岭：分开不同流向河流的高地","definition":"the high ground that separates rivers flowing toward different seas or basins","definitionCN":"把流向不同海域或流域的河流分开的高地","example":"The ridge marks the watershed between two river systems.","exampleCN":"这道山脊是两条河流流域之间的分水岭。","why":"Water plus the old verb 'to divide' gives the literal sense: the line where water is shed to either side.","whyCN":"「水」加上古老的「分开」动词，给出字面义：水被分向两侧的那条线。"},{"no":"02","title":"A drainage basin","titleCN":"流域：被分水岭围住的集水区","definition":"the whole area drained by one river system","definitionCN":"由一个河系统排水的整个区域","example":"The whole watershed drains into one lake.","exampleCN":"整个流域的水都流入同一个湖。","why":"People often use the word for the basin enclosed by the ridge, not only the ridge itself.","whyCN":"人们常把这个词用于被山脊围住的集水区，而不只是山脊本身。"},{"no":"03","title":"A turning point","titleCN":"转折点：局势改变的时刻","definition":"an event or moment that marks a decisive change","definitionCN":"标志决定性变化的事件或时刻","example":"The discovery was a watershed in medicine.","exampleCN":"这项发现是医学上的转折点。","why":"Once water crosses a ridge, it can never return; a decisive change has the same one-way quality.","whyCN":"水一旦越过山脊就再也回不来；决定性变化也有同样的单向性。"},{"no":"04","title":"A dividing line","titleCN":"分界线：两种状态之间的界限","definition":"a boundary between two conditions or periods","definitionCN":"两种状态或两个时期之间的界限","example":"The treaty drew a watershed between the old and new rules.","exampleCN":"条约在新旧规则之间划出一道分界线。","why":"The ridge is a line on the ground, so the word can name any line that separates two sides.","whyCN":"山脊是地面上的线，因此这个词可指任何把两侧分开的线。"},{"no":"05","title":"A unit of water management","titleCN":"流域管理单元","definition":"a river basin treated as a unit for planning and protection","definitionCN":"作为规划与保护单元的河流流域","example":"The agency manages the watershed as one unit.","exampleCN":"该机构把整个流域当作一个单元管理。","why":"Water ignores political borders, so planners use the natural basin as the unit.","whyCN":"水不理会政治边界，因此规划者用自然流域作为单元。"},{"no":"06","title":"The source line of a river","titleCN":"河流源头与分水线","definition":"the line along which rainfall chooses one river or another","definitionCN":"降雨在此选择流入这条河或那条河的线","example":"Rain falling on the watershed may reach either sea.","exampleCN":"落在分水线上的雨可能流入任一片海。","why":"The ridge is where the choice is made, so it also marks the highest source line.","whyCN":"山脊是作出选择的地方，因此也标出最高的源线。"},{"no":"07","title":"A turning point in a life","titleCN":"人生或历史的转折","definition":"a moment after which a person's or a country's course changes","definitionCN":"一个人或一个国家道路由此改变的时刻","example":"That year was a watershed in her career.","exampleCN":"那一年是她事业的转折点。","why":"The one-way crossing of a ridge fits any decision that cannot be undone.","whyCN":"越过山脊的单向性，适合任何无法撤回的决定。"},{"no":"08","title":"An ecological unit","titleCN":"生态与水文单元","definition":"a basin studied as one ecological and hydrological system","definitionCN":"作为一个生态与水文系统研究的流域","example":"Fish, forests and farms all belong to the same watershed.","exampleCN":"鱼、森林与农场都属于同一个流域。","why":"Everything inside the ridge shares water, so ecology treats the basin as one system.","whyCN":"山脊内的一切共享水源，因此生态学把流域当作一个系统。"}],"etymology":{"intro":{"en":"Watershed is an English compound of water and shed, where shed means 'a division', from an old verb 'to divide'. Dates are approximate.","cn":"该词是「水」与「分开处」构成的英语复合词，其中后半来自一个古老动词，意为「分开」。年代均为约数。"},"items":[{"era":"OLD ENGLISH SCEADAN","en":"sceadan meant 'to divide, separate', and its noun could name a division or a parting.","cn":"古英语动词意为「分开、分离」，其名词可指分开处或分界。"},{"era":"GERMANIC ROOT","en":"The verb goes back to a Germanic root meaning 'to cut, split', which also underlies the modern word for a shed in the sense of a parting.","cn":"这个动词可追溯到日耳曼语表示「切、劈」的词根，也是现代表示「分开」的名词的来源。"},{"era":"ENGLISH COMPOUND","en":"Water plus the division noun made watershed, first naming the ridge that parts drainage, recorded around 1800.","cn":"「水」与「分开处」合成该词，最初指分开水流的山脊，约在十九世纪初有记录。"},{"era":"GEOGRAPHY","en":"Geographers extended the word from the ridge to the whole basin enclosed by it.","cn":"地理学者把这个词从山脊扩展到被它围住的整个流域。"},{"era":"METAPHOR","en":"The one-way crossing of a ridge became a picture of a decisive turning point.","cn":"越过山脊的单向性成为决定性转折点的图景。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): early citations differ, and the compound's first use is approximate.","cn":"来源不确定（首见年代）：早期书证不一，复合词的最早使用为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike English compounds with different second elements; group two holds the water-boundary and turning-point words that overlap with watershed.","cn":"第一组是后半成分不同、字形相近的英语复合词；第二组是与流域边界或转折语义重叠的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"waterhead","ipa":"/ˈwɔːtəhed/","tag":"river source","definition":"The source or upper end of a river; it looks close but names the beginning, not the dividing ridge.","definitionCN":"指河流的源头或上端；形似但指起点，而非分水山脊。"},{"word":"shed","ipa":"/ʃed/","tag":"small building","definition":"A small building for storage; this common sense is a different word from the 'division' element in watershed.","definitionCN":"指储物的小屋；这个常见义与复合词中表示「分开」的成分是另一个词。"},{"word":"waterside","ipa":"/ˈwɔːtəsaɪd/","tag":"bank","definition":"The land beside water; it shares the first element but names a bank, not a boundary.","definitionCN":"指水边的陆地；共享前半部分，但指岸边，不是分界。"}]},{"heading":"NEAR MEANING","entries":[{"word":"divide","ipa":"/dɪˈvaɪd/","tag":"continental divide","definition":"A ridge that separates drainage on a very large scale; it is the same idea at continental size.","definitionCN":"指在极大尺度上分开水流的山脊；这是同一观念在大陆尺度上的说法。"},{"word":"drainage basin","ipa":"/ˈdreɪnɪdʒ ˈbeɪsn/","tag":"catchment area","definition":"The whole area drained by a river system; it is the basin inside the watershed.","definitionCN":"指由一个河系统排水的整个区域；它是分水岭之内的流域。"},{"word":"catchment","ipa":"/ˈkætʃmənt/","tag":"water collection","definition":"The area from which water is collected; it is the British technical synonym for a basin.","definitionCN":"指收集水的区域；它是流域的英式技术同义词。"},{"word":"turning point","ipa":"/ˈtɜːnɪŋ pɔɪnt/","tag":"decisive change","definition":"A moment of decisive change; it is the general phrase behind the metaphor.","definitionCN":"指决定性变化的时刻；它是这一比喻背后的通用说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The second half means 'division', not a garden hut: water divided to two sides.","cn":"后半部分意为「分开」，不是园中小屋：水被分到两侧。"},{"en":"The family runs watershed, watersheds, watershed moment, watershed year and watershed management.","cn":"同族词包括本词、复数、转折时刻、转折之年与流域管理。"},{"en":"Fixed phrases mark the senses: a watershed moment, the watershed of a river, watershed management.","cn":"固定搭配标出各义项：转折时刻、河流的分水岭、流域管理。"},{"en":"A drop on the ridge may go to either sea, which is why the ridge is the line of choice.","cn":"落在山脊的水滴可能流入任一片海，因此山脊就是选择的线。"},{"en":"A watershed is a one-way line: once water crosses it, it cannot come back.","cn":"分水岭是一条单向的线：水一旦越过，就回不来。"}],"abstract":[{"en":"Picture a roof ridge sending rain down two different slopes.","cn":"想象屋脊把雨水送到两个不同的斜面。"},{"en":"Picture a book whose next page changes the whole story.","cn":"想象一本书，翻过下一页整个故事就变了。"},{"en":"Picture a line on a map where every drop must choose a side.","cn":"想象地图上一条线，每一滴水都必须选一边。"}]},"examples":[{"en":"The watershed runs along the mountain crest for fifty kilometres.","cn":"分水岭沿山脊延伸五十公里。"},{"en":"The new law was a watershed in the history of the city.","cn":"新法律是这座城市历史上的转折点。"},{"en":"Forests on the watershed protect the water supply below.","cn":"分水岭上的森林保护着下游的供水。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「窝特谢德」：窝里的水到了山脊就分两边落下——分水岭。","word":"watershed"},"root":"英语复合词：water「水」+ shed「分开处」，后者来自古英语 sceadan「分开、分离」，更早可追溯到日耳曼语表示「切、劈」的词根。","sensesIntro":{"en":"Eight senses follow one line: water is split to two sides. The line is a ridge, then the basin inside it, a decisive turn, a boundary, a management unit, the source line, a life change and an ecological system.","cn":"八个义项沿同一条线展开：水被分到两侧。这条线先是山脊，再是其中的流域、决定性转折、分界线、管理单元、源头线、人生转折与生态系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a roof-like ridge with rain running down both sides toward different rivers.","cn":"核心意象：一条像屋脊的高地，雨水沿两侧流向不同的河。"},"chain":["DIVIDING RIDGE","DRAINAGE BASIN","DECISIVE TURN","BOUNDARY LINE","MANAGEMENT UNIT","ECOLOGICAL SYSTEM"],"branches":[{"senses":"S1 · S6","en":"THE RIDGE: the high line where rain chooses one river or the other.","cn":"山脊：雨水在此选择流入这条河或那条河的高线。"},{"senses":"S2 · S8","en":"THE BASIN: the enclosed catchment and its ecology form one natural unit.","cn":"流域：被围住的集水区与它的生态构成一个自然单元。"},{"senses":"S5","en":"THE UNIT: a drainage area handled as one unit of planning and protection.","cn":"管理单元：作为规划与保护对象的一整片集水区。"},{"senses":"S3 · S7","en":"THE TURN: a decisive event and a life change share the one-way crossing.","cn":"转折：决定性事件与人生改变共享单向越过的性质。"},{"senses":"S4","en":"THE LINE: a boundary between two conditions or periods.","cn":"界线：两种状态或两个时期之间的分界。"}]},"affixes":{"intro":{"en":"Watershed is an English compound of two native words; the second element is a division noun, not the building.","cn":"该词是两个本族词构成的英语复合词；后半是表示「分开处」的名词，不是小屋。"},"latinIntro":{"en":"There is no Latin element: both halves are Old English, so the Latin entry list is empty.","cn":"这里没有拉丁成分：两半都是古英语，因此拉丁词条列表留空。"},"items":[{"word":"water","structure":"Old English wæter (noun, 'water')","meaning":"water","meaningCN":"水","example":"The first half names what is divided.","exampleCN":"前半部分指被分开的东西。"},{"word":"sceadan","structure":"Old English sceadan (verb, 'to divide, separate')","meaning":"to divide","meaningCN":"分开；分离","example":"The old verb supplied the idea of parting.","exampleCN":"这个古老动词提供分开的观念。"},{"word":"shed","structure":"shed (noun, 'a division or parting')","meaning":"a division","meaningCN":"分开处；分界","example":"Here the word means a parting, not a hut.","exampleCN":"这里这个词指分开处，不是小屋。"},{"word":"watershed","structure":"water + shed (English compound)","meaning":"the ridge that divides drainage","meaningCN":"分开水流的高地","example":"The ridge marks the watershed between two river systems.","exampleCN":"这道山脊是两条河流流域之间的分水岭。"},{"word":"watersheds","structure":"watershed + -s (plural)","meaning":"more than one watershed","meaningCN":"多个分水岭","example":"Two watersheds meet at the pass.","exampleCN":"两道分水岭在山口相接。"},{"word":"watershed moment","structure":"watershed + moment (compound)","meaning":"a turning point","meaningCN":"转折时刻","example":"The vote was a watershed moment.","exampleCN":"这次投票是一个转折时刻。"},{"word":"watershed management","structure":"watershed + management (compound)","meaning":"basin-wide planning","meaningCN":"流域管理","example":"Watershed management controls flooding.","exampleCN":"流域管理控制洪水。"},{"word":"watershed boundary","structure":"watershed + boundary (compound)","meaning":"the line of a drainage divide","meaningCN":"流域边界","example":"The watershed boundary follows the ridge.","exampleCN":"流域边界沿山脊延伸。"}],"latinEntries":[]}}]);
